"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import { Check, Loader2, Crown, Store, Building2, Sparkles, AlertCircle } from "lucide-react";

const ARTISAN_TRADES = [
  "Carrelage",
  "Plomberie",
  "Électricité",
  "Peinture",
  "Menuiserie",
  "Maçonnerie",
  "Couvreur",
  "Isolation",
  "Climatisation",
  "Chauffage",
  "Ventilation",
  "Étanchéité",
  "Ferronnerie",
  "Serrurerie",
  "Vitrerie",
  "Autre",
];

const AGENT_NAME_SUGGESTIONS = ARTISAN_TRADES;

const normalizeSuggestion = (value: string) =>
  value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const getClosestSuggestion = (value: string) => {
  const cleanValue = normalizeSuggestion(value);
  if (!cleanValue) return "";

  const exact = AGENT_NAME_SUGGESTIONS.find((option) => normalizeSuggestion(option) === cleanValue);
  if (exact) return exact;

  let bestMatch = "";
  let bestScore = 0;

  AGENT_NAME_SUGGESTIONS.forEach((option) => {
    const optionNormalized = normalizeSuggestion(option);
    if (!optionNormalized) return;

    const startsWithScore = optionNormalized.startsWith(cleanValue) || cleanValue.startsWith(optionNormalized) ? 0.9 : 0;
    const includesScore = optionNormalized.includes(cleanValue) || cleanValue.includes(optionNormalized) ? 0.7 : 0;
    const overlap = [...new Set(cleanValue.split(""))].filter((char) => optionNormalized.includes(char)).length;
    const overlapScore = overlap > 0 ? overlap / Math.max(cleanValue.length, optionNormalized.length) : 0;
    const score = Math.max(startsWithScore, includesScore, overlapScore);

    if (score > bestScore) {
      bestScore = score;
      bestMatch = option;
    }
  });

  return bestScore >= 0.3 ? bestMatch : "";
};

const getSuggestions = (query: string) => {
  const cleanValue = normalizeSuggestion(query);
  if (!cleanValue) return AGENT_NAME_SUGGESTIONS;

  return [...AGENT_NAME_SUGGESTIONS]
    .filter((option) => normalizeSuggestion(option).includes(cleanValue) || cleanValue.includes(normalizeSuggestion(option)))
    .slice(0, 6);
};

type Agent = {
  id: string;
  name: string;
  type: string;
  specialty: string | null;
  description: string | null;
  priceMonthly: number;
  priceYearly: number;
  isActive: boolean;
};

export default function AbonnementPage() {
  const { data: session, status } = useSession();
  const router = useRouter();
  const [agents, setAgents] = useState<Agent[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [quantity, setQuantity] = useState(1);
  const [agentNames, setAgentNames] = useState<string[]>([""]);
  const [activeNameInput, setActiveNameInput] = useState<number | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [showModal, setShowModal] = useState(false);

  const profileRole = (() => {
    const currentRole = (session?.user?.role || session?.user?.trade || "artisan").toLowerCase();
    if (currentRole.includes("vendeur")) return "vendeur";
    if (currentRole.includes("promoteur")) return "promoteur";
    return "artisan";
  })();

  const isSupervisorAgent = (agent: Agent) =>
    agent.specialty?.toLowerCase() === "superviseur" || /superviseur/i.test(agent.name || "");

  const roleHeadingMap: Record<string, { title: string; subtitle: string }> = {
    artisan: {
      title: "Choisissez votre agent IA artisan",
      subtitle: "Des assistants spécialisés pour vos chantiers, vos devis et votre suivi de projets.",
    },
    vendeur: {
      title: "Choisissez votre agent IA vendeur",
      subtitle: "Des outils pour piloter votre catalogue, vos offres et votre prospection commerciale.",
    },
    promoteur: {
      title: "Choisissez votre agent IA promoteur",
      subtitle: "Un accompagnement pour superviser les projets, les équipes et la coordination de travaux.",
    },
  };

  useEffect(() => {
    if (status === "loading") return;
    if (!session) {
      router.push("/login");
      return;
    }

    const fetchAgents = async () => {
      try {
        const res = await fetch("/api/agents", { credentials: "include" });
        if (!res.ok) throw new Error("Erreur");
        const data = await res.json();
        const filtered = (data as Agent[])
          .filter((a: Agent) => a.isActive)
          .filter((a: Agent) => a.type === "artisan" || a.type === "vendeur" || a.type === "societe" || a.type === "sur-mesure");
        setAgents(filtered);
      } catch {
        setError("Impossible de charger les offres");
      } finally {
        setLoading(false);
      }
    };

    fetchAgents();
  }, [session, status, router, profileRole]);

  const handleChoose = (agent: Agent) => {
    setSelectedAgent(agent);
    setQuantity(1);
    const fallbackName = agent.specialty || session?.user?.trade || "Vendeur";
    setAgentNames([fallbackName]);
    setActiveNameInput(0);
    setShowModal(true);
  };

  const updateAgentCount = (nextQuantity: number) => {
    const safeQuantity = Math.max(1, Number.isFinite(nextQuantity) ? nextQuantity : 1);
    setQuantity(safeQuantity);
    setAgentNames((prev) => {
      const nextNames = Array.from({ length: safeQuantity }, (_, index) => prev[index]?.trim() || "");
      if (safeQuantity === 1 && !nextNames[0]) {
        nextNames[0] = selectedAgent?.specialty || session?.user?.trade || "Vendeur";
      }
      return nextNames;
    });
  };

  const requiresRoleSupervisor = quantity > 2;

  const handleConfirm = async () => {
    if (!selectedAgent) return;

    const fixedNames = Array.from({ length: quantity }, (_, index) => {
      const rawValue = (agentNames[index] || "").trim();
      if (!rawValue) {
        return selectedAgent.specialty || session?.user?.trade || "Vendeur";
      }
      return getClosestSuggestion(rawValue) || rawValue;
    });

    const hasDuplicateNames = new Set(fixedNames.map((name) => name.toLowerCase())).size !== fixedNames.length;
    if (hasDuplicateNames) {
      setError("Les noms d'agents doivent être différents pour chaque agent.");
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch("/api/user/agents/activate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          agentId: selectedAgent.id,
          quantity: quantity,
          agentNames: fixedNames,
        }),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Erreur");
      }
      setShowModal(false);
      // Rediriger vers l'espace approprié
      const role = session?.user?.role;
      const trade = session?.user?.trade;
      if (role === "promoteur" || trade === "promoteur") {
        router.push("/dashboard");
      } else if (role === "vendeur" || trade === "vendeur") {
        router.push("/vendeur");
      } else if (role === "artisan" || trade === "artisan") {
        router.push("/artisan");
      } else {
        router.push("/dashboard");
      }
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-12">
          <div className="inline-flex items-center gap-2 rounded-full bg-blue-50 px-3 py-1 text-sm font-medium text-blue-700 mb-4">
            <span className="uppercase tracking-wide">Profil</span>
            <span>{profileRole}</span>
          </div>
          <h1 className="text-4xl font-extrabold text-gray-900 sm:text-5xl">
            🔥 {roleHeadingMap[profileRole].title}
          </h1>
          <p className="mt-4 text-xl text-gray-500 max-w-2xl mx-auto">
            {roleHeadingMap[profileRole].subtitle}
            <span className="block text-blue-600 font-semibold mt-2">
              ✅ 14 jours d&apos;essai gratuit offerts – Aucune carte demandée.
            </span>
          </p>
        </div>

        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-8 text-red-700 flex items-center gap-2 max-w-3xl mx-auto">
            <AlertCircle className="w-5 h-5" />
            {error}
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {agents.map((agent) => {
            const isPopular = profileRole === "promoteur" && agent.type === "societe";
            return (
              <div
                key={agent.id}
                className={`bg-white rounded-2xl shadow-lg overflow-hidden border transition-all hover:shadow-xl ${
                  isPopular ? "border-blue-500 ring-2 ring-blue-500 ring-offset-2" : "border-gray-200"
                }`}
              >
                {isPopular && (
                  <div className="bg-blue-600 text-white text-center text-sm font-semibold py-1.5">
                    ⭐ Le plus populaire
                  </div>
                )}
                <div className="p-6">
                  <div className="flex items-center gap-2 mb-2">
                    {agent.type === "artisan" && <Crown className="w-6 h-6 text-yellow-500" />}
                    {agent.type === "vendeur" && <Store className="w-6 h-6 text-blue-500" />}
                    {agent.type === "societe" && <Building2 className="w-6 h-6 text-purple-500" />}
                    {agent.type === "sur-mesure" && <Sparkles className="w-6 h-6 text-indigo-500" />}
                    <h3 className="text-xl font-bold text-gray-800">{agent.name}</h3>
                  </div>
                  {agent.specialty && (
                    <p className="text-sm text-gray-500 mb-2">Spécialité : {agent.specialty}</p>
                  )}
                  <p className="text-gray-600 text-sm mb-4">{agent.description || "Agent polyvalent"}</p>
                  <div className="mb-4">
                    <span className="text-3xl font-bold text-gray-900">{agent.priceMonthly}€</span>
                    <span className="text-gray-500 text-sm"> /mois</span>
                    {agent.priceYearly > 0 && (
                      <div className="text-sm text-green-600 font-medium">
                        ou {agent.priceYearly}€ /an (économie de 10%)
                      </div>
                    )}
                  </div>
                  <ul className="space-y-2 text-sm text-gray-600 mb-6">
                    <li className="flex items-center gap-2">
                      <Check className="w-4 h-4 text-green-500" />
                      {agent.type === "artisan" ? "5 projets / mois" : agent.type === "vendeur" ? "20 projets / mois" : "Gestion multi-sites"}
                    </li>
                    <li className="flex items-center gap-2">
                      <Check className="w-4 h-4 text-green-500" />
                      {agent.type === "artisan" ? "10 offres / mois" : agent.type === "vendeur" ? "50 offres / mois" : "Suivi des lots et équipes"}
                    </li>
                    <li className="flex items-center gap-2">
                      <Check className="w-4 h-4 text-green-500" />
                      {agent.type === "artisan" ? "IA basique" : agent.type === "vendeur" ? "IA avancée" : "IA de coordination"}
                    </li>
                    <li className="flex items-center gap-2">
                      <Check className="w-4 h-4 text-green-500" />
                      {agent.type === "artisan" ? "Support standard" : agent.type === "vendeur" ? "Support prioritaire" : "Support projet 24/7"}
                    </li>
                  </ul>
                  <button
                    onClick={() => handleChoose(agent)}
                    className="w-full bg-blue-600 text-white py-2.5 rounded-lg hover:bg-blue-700 transition font-semibold"
                  >
                    {agent.type === "sur-mesure" ? "Contactez-nous" : "Commencer votre essai de 14 jours gratuit"}
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        <div className="mt-16 max-w-3xl mx-auto bg-white rounded-xl shadow-sm border border-gray-100 p-6">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">❓ Questions fréquentes</h2>
          <div className="space-y-4">
            <div>
              <h4 className="font-semibold text-gray-700">Comment fonctionne l&apos;essai gratuit ?</h4>
              <p className="text-gray-600 text-sm">Vous bénéficiez de 14 jours d&apos;essai complet, sans fournir de carte bancaire. Au 15e jour, vous serez invité à payer pour continuer.</p>
            </div>
            <div>
              <h4 className="font-semibold text-gray-700">Puis-je arrêter l&apos;essai avant la fin ?</h4>
              <p className="text-gray-600 text-sm">Oui, vous pouvez arrêter à tout moment. Vos données seront conservées 30 jours au cas où vous reviendriez.</p>
            </div>
            <div>
              <h4 className="font-semibold text-gray-700">Que se passe-t-il après l&apos;essai ?</h4>
              <p className="text-gray-600 text-sm">Vous recevrez un rappel, puis votre carte sera débitée automatiquement si vous avez souscrit. Sinon, le service sera suspendu.</p>
            </div>
          </div>
        </div>
      </div>

      {/* Modal de sélection */}
      {showModal && selectedAgent && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 relative max-h-[90vh] overflow-y-auto">
            <button
              onClick={() => setShowModal(false)}
              className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"
            >
              <span className="sr-only">Fermer</span>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
            <h2 className="text-xl font-bold mb-4">Personnalisez votre abonnement</h2>
            <p className="text-gray-600 mb-4">
              Vous avez choisi : <strong>{selectedAgent.name}</strong> ({selectedAgent.priceMonthly}€/mois)
            </p>
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Nombre d&apos;agents (1 inclus)
              </label>
              <input
                type="number"
                min="1"
                value={quantity}
                onChange={(e) => updateAgentCount(Math.max(1, parseInt(e.target.value) || 1))}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"
              />
              <p className="text-xs text-gray-400 mt-1">
                {quantity === 1
                  ? "1 agent inclus"
                  : `${quantity} agents (${selectedAgent.priceMonthly * quantity}€ / mois)`}
              </p>
            </div>

            <div className="space-y-3 mb-4">
              {Array.from({ length: quantity }, (_, index) => {
                const value = agentNames[index] || "";
                const suggestions = getSuggestions(value);
                const isSupervisorSelected = isSupervisorAgent(selectedAgent);
                const selectedTrade = value === "" ? (selectedAgent.specialty || session?.user?.trade || "Vendeur") : value;
                const isOtherSelected = selectedTrade === "Autre" || !ARTISAN_TRADES.includes(selectedTrade);

                return (
                  <div key={index} className="relative">
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      {isSupervisorSelected ? "Nom du superviseur" : "Quel métier ?"}
                    </label>

                    {isSupervisorSelected ? (
                      <input
                        type="text"
                        value={value || selectedAgent.name}
                        onChange={(e) => {
                          const nextValue = e.target.value.trim();
                          setAgentNames((prev) => {
                            const updated = [...prev];
                            updated[index] = nextValue || selectedAgent.name;
                            return updated;
                          });
                        }}
                        placeholder="Ex : Superviseur Vendeur 1"
                        className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500"
                      />
                    ) : (
                      <>
                        <select
                          value={isOtherSelected ? "Autre" : selectedTrade}
                          onChange={(e) => {
                            const nextValue = e.target.value;
                            setAgentNames((prev) => {
                              const updated = [...prev];
                              updated[index] = nextValue;
                              return updated;
                            });
                          }}
                          className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 bg-white"
                        >
                          {ARTISAN_TRADES.map((option) => (
                            <option key={option} value={option}>{option}</option>
                          ))}
                        </select>

                        {isOtherSelected && (
                          <input
                            type="text"
                            value={selectedTrade === "Autre" ? "" : selectedTrade}
                            onChange={(e) => {
                              const nextValue = e.target.value.trim();
                              setAgentNames((prev) => {
                                const updated = [...prev];
                                updated[index] = nextValue || "Autre";
                                return updated;
                              });
                            }}
                            placeholder="Précisez votre métier"
                            className="w-full border border-gray-300 rounded-lg px-3 py-2 mt-2 focus:ring-2 focus:ring-blue-500"
                          />
                        )}

                        {!isOtherSelected && suggestions.length > 0 && value && getClosestSuggestion(value) && getClosestSuggestion(value) !== value && (
                          <p className="mt-1 text-xs text-blue-600">
                            Suggestion : <span className="font-medium">{getClosestSuggestion(value)}</span>
                          </p>
                        )}
                      </>
                    )}
                  </div>
                );
              })}
            </div>

            <div className="bg-gray-50 rounded-lg p-3 mb-4 text-sm">
              <p className="font-semibold">Résumé</p>
              <p>Abonnement : {selectedAgent.priceMonthly * quantity}€ / mois</p>
              {requiresRoleSupervisor && (
                <p className="mt-1 text-amber-700 font-medium">
                  ⚠️ Si votre équipe dépasse 2 agents spécialisés d’une même famille, un superviseur associé est ajouté automatiquement.
                </p>
              )}
              <p className="text-green-600">✅ 14 jours d&apos;essai offerts</p>
            </div>
            <button
              onClick={handleConfirm}
              disabled={submitting}
              className="w-full bg-blue-600 text-white py-2.5 rounded-lg hover:bg-blue-700 transition disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {submitting ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Activation...
                </>
              ) : (
                "Commencer votre essai de 14 jours gratuit"
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useSession, signOut } from "next-auth/react";
import { useEffect } from "react";
import {
  LayoutDashboard,
  Package,
  FolderKanban,
  Settings,
  LogOut,
  Store,
  Shield,
} from "lucide-react";

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const router = useRouter();
  const { data: session, status } = useSession();

  useEffect(() => {
    if (!session) {
      router.push("/login");
    }
  }, [session, router]);

  if (status === "loading") {
    return (
      <div className="flex items-center justify-center h-screen text-gray-500">
        ⏳ Chargement de votre session...
      </div>
    );
  }

  if (!session) {
    return null;
  }

  const currentRole = (session.user.role || session.user.trade || "artisan").toLowerCase();
  const profileType = currentRole.includes("vendeur") ? "vendeur" : currentRole.includes("promoteur") ? "promoteur" : "artisan";

  const staticMenuByProfile: Record<string, Array<{ name: string; href: string; icon: typeof LayoutDashboard }>> = {
    artisan: [
      { name: "Tableau de bord", href: "/dashboard", icon: LayoutDashboard },
      { name: "Catalogue", href: "/artisan/catalogue", icon: Package },
      { name: "Projets", href: "/artisan/projets", icon: FolderKanban },
      { name: "Demandes de devis", href: "/artisan/demandes", icon: Package },
      { name: "Offres reçues", href: "/artisan/offres", icon: Package },
      { name: "Portfolio", href: "/artisan/portfolio", icon: Store },
      { name: "Partenaires", href: "/partenaires", icon: Store },
      { name: "Paramètres", href: "/parametres", icon: Settings },
    ],
    vendeur: [
      { name: "Tableau de bord", href: "/dashboard", icon: LayoutDashboard },
      { name: "Catalogue", href: "/vendeur?section=catalogue", icon: Package },
      { name: "Projets disponibles", href: "/vendeur/projets", icon: FolderKanban },
      { name: "Demandes de devis", href: "/vendeur/demandes", icon: FolderKanban },
      { name: "Offres envoyées", href: "/vendeur?section=offres", icon: Store },
      { name: "Annonces", href: "/vendeur?section=annonces", icon: Store },
      { name: "Assistant IA", href: "/vendeur?section=ia", icon: Store },
      { name: "Partenaires", href: "/partenaires", icon: Store },
      { name: "Paramètres", href: "/parametres", icon: Settings },
    ],
    promoteur: [
      { name: "Tableau de bord", href: "/dashboard", icon: LayoutDashboard },
      { name: "Programmes", href: "/promoteur/programmes", icon: FolderKanban },
      { name: "Lots suivis", href: "/promoteur/lots", icon: Package },
      { name: "Entreprises actives", href: "/promoteur/entreprises", icon: Store },
      { name: "Partenaires", href: "/partenaires", icon: Store },
      { name: "Paramètres", href: "/parametres", icon: Settings },
    ],
  };

  const navItems = staticMenuByProfile[profileType] ?? staticMenuByProfile.artisan;

  return (
    <div className="flex h-screen bg-gray-50">
      {/* Sidebar */}
      <aside className="w-64 bg-white border-r border-gray-200 flex flex-col">
        <nav aria-label="Menu principal" className="flex-1 p-4 space-y-1">
          {navItems.map((item) => {
            const isActive = pathname === item.href;
            const Icon = item.icon;
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`flex items-center gap-3 px-4 py-3 rounded-lg transition ${
                  isActive
                    ? "bg-blue-50 text-blue-700 font-medium"
                    : "text-gray-700 hover:bg-gray-100"
                }`}
              >
                <Icon className="w-5 h-5" />
                {item.name}
              </Link>
            );
          })}
        </nav>

        <div className="p-4 border-t border-gray-200">
          <button
            onClick={() => signOut({ callbackUrl: "/" })}
            className="flex items-center gap-3 px-4 py-3 w-full text-gray-700 rounded-lg hover:bg-gray-100 transition"
          >
            <LogOut className="w-5 h-5" />
            Déconnexion
          </button>
        </div>
      </aside>

      {/* Contenu principal */}
      <main className="flex-1 overflow-y-auto p-8 bg-gray-50">{children}</main>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { ShoppingCart, Check, X, Loader2 } from "lucide-react";

type Suggestion = {
  area: string;
  label: string;
  surface: number;
  unit: string;
  recommendedProducts: {
    id: string;
    name: string;
    price: number;
    stock: number;
    imageUrl?: string;
  }[];
};

export default function SelectorTab({ projectId }: { projectId: string }) {
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [loading, setLoading] = useState(false);
  const [generated, setGenerated] = useState(false);
  const [selectedProducts, setSelectedProducts] = useState<Record<string, string[]>>({});

  const generateSuggestions = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/assistant/selector', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ projectId }),
      });
      const data = await res.json();
      setSuggestions(data.suggestions || []);
      setGenerated(true);
    } catch (error) {
      console.error("Erreur génération suggestions :", error);
      alert("Erreur lors de la génération des suggestions");
    } finally {
      setLoading(false);
    }
  };

  const toggleProductSelection = (suggestionIndex: number, productId: string) => {
    const key = `${suggestionIndex}`;
    const current = selectedProducts[key] || [];
    if (current.includes(productId)) {
      setSelectedProducts({
        ...selectedProducts,
        [key]: current.filter(id => id !== productId),
      });
    } else {
      setSelectedProducts({
        ...selectedProducts,
        [key]: [...current, productId],
      });
    }
  };

  const addSelectedToProject = async () => {
    // Pour chaque suggestion, récupérer les produits sélectionnés
    const allSelected: string[] = [];
    Object.values(selectedProducts).forEach(ids => allSelected.push(...ids));
    if (allSelected.length === 0) {
      alert("Veuillez sélectionner au moins un produit.");
      return;
    }
    // Ici, on pourrait appeler une API pour ajouter les produits au projet
    // Pour l'instant, on affiche un message
    alert(`✅ ${allSelected.length} produit(s) sélectionnés. (Fonctionnalité d'ajout en développement)`);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-lg font-semibold text-gray-800">🛒 Sélecteur IA</h2>
        <button
          onClick={generateSuggestions}
          disabled={loading}
          className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition disabled:opacity-50 flex items-center gap-2"
        >
          {loading ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <ShoppingCart className="w-4 h-4" />
          )}
          {loading ? "Analyse..." : "Proposer des produits"}
        </button>
      </div>

      {!generated && !loading && (
        <div className="text-center py-12 text-gray-500 bg-gray-50 rounded-xl border border-gray-200">
          <ShoppingCart className="w-12 h-12 mx-auto text-gray-400 mb-3" />
          <p>Cliquez sur "Proposer des produits" pour que l'IA analyse votre projet</p>
          <p className="text-sm">Elle sélectionnera les produits adaptés depuis votre catalogue.</p>
        </div>
      )}

      {loading && (
        <div className="text-center py-12">
          <Loader2 className="w-8 h-8 mx-auto animate-spin text-purple-600" />
          <p className="mt-2 text-gray-500">Analyse du projet et recherche de produits...</p>
        </div>
      )}

      {generated && !loading && (
        <>
          {suggestions.length === 0 ? (
            <div className="text-center py-8 text-gray-500 bg-gray-50 rounded-xl border border-gray-200">
              <p>Aucun produit suggéré.</p>
              <p className="text-sm">Vérifiez votre catalogue ou les données du projet.</p>
            </div>
          ) : (
            <div className="space-y-6">
              {suggestions.map((suggestion, index) => (
                <div key={index} className="bg-white rounded-xl shadow-sm border border-gray-200 p-4">
                  <h3 className="font-semibold text-gray-800">
                    {suggestion.label} ({suggestion.surface.toFixed(1)} {suggestion.unit})
                  </h3>
                  <div className="mt-3 grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {suggestion.recommendedProducts.map((product) => {
                      const isSelected = (selectedProducts[`${index}`] || []).includes(product.id);
                      return (
                        <div
                          key={product.id}
                          className={`flex items-center gap-3 p-3 border rounded-lg cursor-pointer transition ${
                            isSelected ? 'border-purple-500 bg-purple-50' : 'border-gray-200 hover:bg-gray-50'
                          }`}
                          onClick={() => toggleProductSelection(index, product.id)}
                        >
                          <div className="flex-1">
                            <p className="text-sm font-medium">{product.name}</p>
                            <p className="text-xs text-gray-500">{product.price} €</p>
                          </div>
                          {isSelected ? (
                            <Check className="w-5 h-5 text-purple-600" />
                          ) : (
                            <div className="w-5 h-5 border-2 border-gray-300 rounded-full" />
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}

              <button
                onClick={addSelectedToProject}
                className="w-full py-3 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition font-semibold"
              >
                Ajouter les produits sélectionnés au devis
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { AlertCircle, Lightbulb } from "lucide-react";

type Suggestion = {
  type: "warning" | "info" | "suggestion" | "alternative";
  title: string;
  description: string;
  action?: string;
  missingItems?: any[];
  serviceId?: string;
};

type ProjectItem = {
  id: string;
  quantity: number;
  unitPriceHtAtSale: number;
  tvaRate: number;
  product?: { name: string; salePrice: number };
  service?: { name: string; unitPriceHt: number };
  customLabel?: string;
  customPrice?: number;
};

type SuggestionsIAProps = {
  projectId: string;
  onAddItem: (item: any) => void;
  existingItems: ProjectItem[];
};

// ============================================================
// NORMALISATION DU NOM (supprime les parenthèses et unités)
// ============================================================
function normalizeName(name: string): string {
  return name
    .replace(/\([^)]*\)/g, '')           // Supprime (13 m²), (25 kg), etc.
    .replace(/\d+\.?\d*\s*(m²|kg|L|cm|mm|unite?)/gi, '') // Supprime les unités
    .trim()
    .toLowerCase();
}

export default function SuggestionsIA({ projectId, onAddItem, existingItems }: SuggestionsIAProps) {
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [loading, setLoading] = useState(true);
  const [addedKeys, setAddedKeys] = useState<Set<string>>(new Set());

  // Construction de la liste des clés existantes (noms normalisés)
  const existingKeys = new Set(
    existingItems.map(item => {
      const rawName = item.customLabel || item.product?.name || item.service?.name || "";
      return normalizeName(rawName);
    }).filter(Boolean)
  );

  useEffect(() => {
    console.log('🔍 SuggestionsIA monté, projectId =', projectId);
    const fetchSuggestions = async () => {
      try {
        const res = await fetch('/api/assistant/advice', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ projectId }),
        });
        const data = await res.json();
        setSuggestions(data.advice || []);
      } catch (error) {
        console.error("Erreur suggestions :", error);
      } finally {
        setLoading(false);
      }
    };
    fetchSuggestions();
  }, [projectId]);

  // Ajout automatique des suggestions (avec vérification des doublons par nom normalisé)
  useEffect(() => {
    if (loading || suggestions.length === 0) return;

    suggestions.forEach((suggestion) => {
      // Produits manquants
      if (suggestion.type === "warning" && suggestion.missingItems) {
        suggestion.missingItems.forEach((item) => {
          const key = normalizeName(item.name);
          if (!existingKeys.has(key) && !addedKeys.has(key)) {
            onAddItem({
              customLabel: item.name, // Nom pur (sans quantité)
              customPrice: item.estimatedPrice || 0,
              quantity: item.quantity || 1, // Quantité séparée
            });
            setAddedKeys(prev => new Set(prev).add(key));
          }
        });
      }

      // Prestations de pose
      if (suggestion.title?.includes('Pose sol') || suggestion.title?.includes('Pose mur')) {
        const key = normalizeName(suggestion.title);
        if (!existingKeys.has(key) && !addedKeys.has(key)) {
          const match = suggestion.description.match(/(\d+\.?\d*)\s*€/);
          const price = match ? parseFloat(match[1]) : 0;
          onAddItem({
            customLabel: suggestion.title,
            customPrice: price,
            quantity: 1,
          });
          setAddedKeys(prev => new Set(prev).add(key));
        }
      }
    });
  }, [suggestions, loading, onAddItem, existingKeys, addedKeys]);

  if (loading) {
    return <div className="text-sm text-gray-500">⏳ Analyse du projet en cours...</div>;
  }

  if (suggestions.length === 0) {
    return <div className="text-sm text-gray-500">✅ Aucune suggestion pour le moment.</div>;
  }

  // Filtrer les suggestions déjà ajoutées
  const remainingSuggestions = suggestions.filter(s => {
    if (s.type === "warning" && s.missingItems) {
      return s.missingItems.some(item => !existingKeys.has(normalizeName(item.name)) && !addedKeys.has(normalizeName(item.name)));
    }
    if (s.title?.includes('Pose sol') || s.title?.includes('Pose mur')) {
      return !existingKeys.has(normalizeName(s.title)) && !addedKeys.has(normalizeName(s.title));
    }
    return true;
  });

  return (
    <div className="space-y-4">
      {remainingSuggestions.map((suggestion, index) => {
        if (suggestion.type === "warning" && suggestion.missingItems) {
          const remainingItems = suggestion.missingItems.filter(
            item => !existingKeys.has(normalizeName(item.name)) && !addedKeys.has(normalizeName(item.name))
          );
          if (remainingItems.length === 0) return null;

          return (
            <div key={index}>
              <p className="text-sm font-medium text-yellow-800 flex items-center gap-1">
                <AlertCircle className="w-4 h-4" /> {suggestion.title}
              </p>
              <div className="mt-2 space-y-2">
                {remainingItems.map((item, idx) => {
                  const price = item.estimatedPrice || 0;
                  return (
                    <div key={idx} className="flex items-center gap-2 bg-white p-2 rounded border border-gray-200">
                      <span className="text-sm flex-1">
                        {item.name} → <strong>{price} €</strong> (x{item.quantity} {item.unit})
                      </span>
                      <span className="text-xs text-green-600">✅ Ajouté automatiquement</span>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        }

        if (suggestion.title?.includes('Pose sol') || suggestion.title?.includes('Pose mur')) {
          if (existingKeys.has(normalizeName(suggestion.title)) || addedKeys.has(normalizeName(suggestion.title))) return null;
          return (
            <div key={index} className="p-3 bg-blue-50 border border-blue-200 rounded-lg">
              <p className="text-sm text-gray-700">{suggestion.description}</p>
              <span className="text-xs text-green-600">✅ Ajouté automatiquement</span>
            </div>
          );
        }

        return (
          <div key={index} className="text-sm text-gray-700">
            <span className="font-medium">{suggestion.title}</span> : {suggestion.description}
          </div>
        );
      })}
    </div>
  );
}

