                  {countryName ? `Détecté : ${countryName}` : 'Détection automatique'}
                </span>
              </div>
              <div className="flex items-center gap-4 text-sm">
                <span className="text-gray-600">Total HT : <strong className="text-gray-800">{totalHT.toFixed(2)} €</strong></span>
