'use client';

import { useEffect, useState } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';

type Agent = {
  id: string;
  name: string;
  type: string;
  specialty?: string | null;
  description?: string | null;
  priceMonthly: number;
  priceYearly: number;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
  userAgents?: Array<{ id: string; status: string; userId: string }>;
};

const emptyForm = {
  name: '',
  type: 'vendeur',
  specialty: '',
  description: '',
  priceMonthly: '0',
  priceYearly: '0',
  isActive: true,
};

export default function AdminAgentsPage() {
  const router = useRouter();
  const { data: session, status } = useSession();
  const [agents, setAgents] = useState<Agent[]>([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (status === 'loading') return;
    if (!session) {
      router.push('/login');
      return;
    }
    if (session.user.role !== 'admin') {
      router.push('/dashboard');
      return;
    }

    void loadAgents();
  }, [session, status, router]);

  const loadAgents = async () => {
    try {
      const res = await fetch('/api/admin/agents', { credentials: 'include' });
      if (!res.ok) {
        throw new Error('Erreur de chargement');
      }
      const data = await res.json();
      setAgents(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error(error);
      alert('Erreur lors du chargement des agents');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);

    try {
      const url = editingId ? `/api/admin/agents/${editingId}` : '/api/admin/agents';
      const method = editingId ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          ...form,
          priceMonthly: Number(form.priceMonthly),
          priceYearly: Number(form.priceYearly),
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data?.error || 'Erreur lors de la sauvegarde');
      }

      setForm(emptyForm);
      setEditingId(null);
      await loadAgents();
      alert(editingId ? 'Agent mis à jour' : 'Agent créé');
    } catch (error) {
      alert((error as Error).message);
    } finally {
      setSubmitting(false);
    }
  };

  const handleEdit = (agent: Agent) => {
    setEditingId(agent.id);
    setForm({
      name: agent.name,
      type: agent.type,
      specialty: agent.specialty || '',
      description: agent.description || '',
      priceMonthly: String(agent.priceMonthly),
      priceYearly: String(agent.priceYearly),
      isActive: agent.isActive,
    });
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Supprimer cet agent ?')) return;

    try {
      const res = await fetch(`/api/admin/agents/${id}`, {
        method: 'DELETE',
        credentials: 'include',
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'Suppression impossible');
      await loadAgents();
      alert('Agent supprimé');
    } catch (error) {
      alert((error as Error).message);
    }
  };

  if (status === 'loading' || !session) {
    return <div className="p-8 text-slate-600">Chargement...</div>;
  }

  return (
    <div className="min-h-screen bg-slate-100 p-8 text-slate-800">
      <div className="mx-auto max-w-7xl space-y-6">
