      if (!res.ok) throw new Error(data?.error || 'Erreur de chargement');
      setAssistantLogs(Array.isArray(data.assistantLogs) ? data.assistantLogs : []);
      setAdminLogs(Array.isArray(data.adminLogs) ? data.adminLogs : []);
