      if (!res.ok) throw new Error(data?.error || 'Erreur de chargement');
      setNotifications(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error(error);
      alert('Erreur lors du chargement des notifications');
    } finally {
      setLoading(false);
    }
  };

