'use client';

import { useEffect, useState } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';

type Tutorial = {
  id: string;
  title: string;
  type: string;
  url?: string | null;
  description?: string | null;
  trade?: string | null;
  source?: string | null;
  tags?: string | null;
  keywords: string;
  createdAt: string;
};

const emptyForm = {
  title: '',
  type: 'video',
  url: '',
  description: '',
  trade: '',
  source: '',
  tags: '',
  keywords: '',
};

export default function AdminTutorialsPage() {
  const router = useRouter();
  const { data: session, status } = useSession();
  const [tutorials, setTutorials] = useState<Tutorial[]>([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (status === 'loading') return;
    if (!session) {
      router.push('/login');
      return;
    }
    if (session.user.role !== 'admin') {
      router.push('/dashboard');
      return;
    }

    void loadTutorials();
  }, [session, status, router]);

  const loadTutorials = async () => {
    try {
      const res = await fetch('/api/admin/tutorials', { credentials: 'include' });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'Erreur de chargement');
      setTutorials(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error(error);
      alert('Erreur lors du chargement des tutoriels');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);

    try {
      const url = editingId ? `/api/admin/tutorials/${editingId}` : '/api/admin/tutorials';
      const method = editingId ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'Erreur lors de la sauvegarde');

      setForm(emptyForm);
      setEditingId(null);
      await loadTutorials();
      alert(editingId ? 'Tutoriel mis à jour' : 'Tutoriel créé');
    } catch (error) {
      alert((error as Error).message);
    } finally {
      setSubmitting(false);
    }
  };

  const handleEdit = (tutorial: Tutorial) => {
    setEditingId(tutorial.id);
    setForm({
      title: tutorial.title,
      type: tutorial.type,
      url: tutorial.url || '',
      description: tutorial.description || '',
      trade: tutorial.trade || '',
      source: tutorial.source || '',
      tags: tutorial.tags || '',
      keywords: tutorial.keywords || '',
    });
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Supprimer ce tutoriel ?')) return;

    try {
      const res = await fetch(`/api/admin/tutorials/${id}`, {
        method: 'DELETE',
        credentials: 'include',
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'Suppression impossible');
      await loadTutorials();
      alert('Tutoriel supprimé');
    } catch (error) {
      alert((error as Error).message);
    }
  };

  if (status === 'loading' || !session) {
    return <div className="p-8 text-slate-600">Chargement...</div>;
