  tvaRate: ['tvarate', 'tva', 'tauxdeva', 'vat', 'tauxdetva'],
  imageUrl: ['imageurl', 'image', 'urlimage', 'nomimage'],
};

const normalizeHeader = (value: string) =>
  String(value ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '');

const parseNumericValue = (value: unknown) => {
  if (value === null || value === undefined || value === '') return NaN;
  const raw = String(value).trim();
  if (!raw) return NaN;
  const sanitized = raw
    .replace(/€/g, '')
    .replace(/\s/g, '')
    .replace(/\./g, '')
    .replace(/,/g, '.')
    .replace(/[^0-9.-]/g, '');
  if (!sanitized || sanitized === '-' || sanitized === '.') return NaN;
  return Number(sanitized);
};

const isMeaninglessRow = (row: Record<string, unknown>) => {
  const values = Object.values(row).map((value) => String(value ?? '').trim());
  if (values.every((value) => value === '')) return true;
  const joined = values.join(' ').toLowerCase();
  return ['welcome', 'bienvenue', 'example', 'exemple', 'name', 'nom', 'category', 'categorie', 'description', 'prix achat', 'prix vente', 'stock', 'tva', 'image'].some((keyword) => joined.includes(keyword));
};

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Non authentifié' }, { status: 401 });
    }

    const formData = await request.formData();
    const file = formData.get('file') as File;

    if (!file) {
      return NextResponse.json({ error: 'Aucun fichier envoyé' }, { status: 400 });
    }

    const ext = file.name.split('.').pop();
    if (ext !== 'xlsx' && ext !== 'xls') {
      return NextResponse.json({ error: 'Format non supporté. Utilisez .xlsx ou .xls' }, { status: 400 });
    }

    const buffer = await file.arrayBuffer();
    const workbook = XLSX.read(buffer, { type: 'array' });
    const sheet = workbook.Sheets[workbook.SheetNames[0]];
    const rawData: Record<string, unknown>[] = XLSX.utils.sheet_to_json(sheet, { defval: '' });

    const productsData: Record<string, unknown>[] = [];
    for (const row of rawData) {
      if (!row || isMeaninglessRow(row)) continue;
      productsData.push(row);
    }

    if (productsData.length === 0) {
      return NextResponse.json({ error: 'Aucune ligne de produit valide trouvée dans le fichier' }, { status: 400 });
    }

    let importedCount = 0;
    let errorCount = 0;
    const errors: string[] = [];

    for (let i = 0; i < productsData.length; i++) {
      const row = productsData[i];
      const normalizedRow = Object.fromEntries(
        Object.entries(row).map(([key, value]) => [normalizeHeader(String(key)), value])
      ) as Record<string, unknown>;

      const getCell = (aliases: string[]) => {
        for (const alias of aliases) {
          const normalizedAlias = normalizeHeader(alias);
          if (normalizedRow[normalizedAlias] !== undefined) {
            return normalizedRow[normalizedAlias];
          }
        }
        return '';
      };

      const name = String(getCell(HEADER_ALIASES.name) ?? '').trim();
      const description = String(getCell(HEADER_ALIASES.description) ?? '').trim();
      const category = String(getCell(HEADER_ALIASES.category) ?? '').trim();
      const purchasePrice = parseNumericValue(getCell(HEADER_ALIASES.purchasePrice));
      const salePrice = parseNumericValue(getCell(HEADER_ALIASES.salePrice));
      const stock = Number.isFinite(parseNumericValue(getCell(HEADER_ALIASES.stock))) ? Math.max(0, Math.round(parseNumericValue(getCell(HEADER_ALIASES.stock)))) : 0;
      const tvaRate = Number.isFinite(parseNumericValue(getCell(HEADER_ALIASES.tvaRate))) ? parseNumericValue(getCell(HEADER_ALIASES.tvaRate)) : 20;
      const imageName = String(getCell(HEADER_ALIASES.imageUrl) ?? '').trim();

      if (!name || !category || (!Number.isFinite(purchasePrice) && !Number.isFinite(salePrice))) {
        errorCount++;
        errors.push(`Ligne ${i + 1} : Nom, catégorie ou prix manquant`);
        continue;
      }

      try {
        await (prisma.product as any).create({
          data: {
            name,
            description: description || null,
            category: category || 'Non catégorisé',
            purchasePrice: Number.isFinite(purchasePrice) ? purchasePrice : 0,
            salePrice: Number.isFinite(salePrice) ? salePrice : 0,
            stock: stock || 0,
            tvaRate: Number.isFinite(tvaRate) ? tvaRate : 20,
            imageUrl: imageName ? `/uploads/${imageName}` : null,
            userId: session.user.id,
          },
        });
        importedCount++;
      } catch (err) {
        errorCount++;
        errors.push(`Ligne ${i + 1} : Erreur base de données - ${(err as Error).message}`);
      }
    }

    if (importedCount === 0) {
      return NextResponse.json({ error: 'Aucune ligne de produit valide n’a été importée. Vérifiez les colonnes du fichier.', details: errors.slice(0, 10) }, { status: 400 });
    }

    return NextResponse.json({
      success: true,
      importedCount,
      errorCount,
      errors,
    });
  } catch (error) {
    console.error('Import error:', error);
    return NextResponse.json(
      { error: 'Erreur serveur : ' + (error as Error).message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '../../../../../../auth';
import { prisma } from '@/lib/prisma';

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; itemId: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Non authentifié' }, { status: 401 });
    }

    const { id: projectId, itemId } = await params;
    const body = await request.json();
    const { isClientProvided } = body;

    const project = await prisma.project.findUnique({
      where: { id: projectId },
    });
    if (!project || project.userId !== session.user.id) {
      return NextResponse.json({ error: 'Accès refusé' }, { status: 403 });
    }

    // Ici, vous pouvez stocker le statut "fourni par le client" dans un champ dédié
    // ou dans un champ JSON. Pour l'exemple, on va l'ajouter dans un champ JSON.
    const updated = await prisma.projectItem.update({
      where: { id: itemId },
      data: {
        // Si vous avez ajouté un champ `clientProvided` dans le schéma Prisma
        // clientProvided: isClientProvided,
      },
    });

    return NextResponse.json(updated);
  } catch (error) {
    console.error('Erreur client-provided:', error);
    return NextResponse.json({ error: 'Erreur serveur' }, { status: 500 });
  }
}

// app/api/projects/[id]/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { requireRole } from '@/lib/role-access';

const permissionRank: Record<string, number> = {
  READ: 1,
  COMMENT: 2,
  EDIT: 3,
  VALIDATE: 4,
};

async function getUserProjectPermission(userId: string, projectId: string) {
  const project = await prisma.project.findUnique({
    where: { id: projectId },
    select: { id: true, userId: true },
  });

  if (!project) {
    return { project: null, permission: null };
  }

  if (project.userId === userId) {
    return { project, permission: 'VALIDATE' };
  }

  const accesses = await prisma.projectTeamAccess.findMany({
    where: {
      projectId,
      team: {
        members: {
          some: {
            userId,
            isActive: true,
          },
        },
      },
    },
    select: { permission: true },
  });

  const maxPermission = accesses.reduce((best, access) => {
    const rank = permissionRank[access.permission] ?? 0;
    return rank > best ? rank : best;
  }, 0);

  if (maxPermission <= 0) {
    return { project, permission: null };
  }

  const highest = Object.entries(permissionRank)
    .filter(([, rank]) => rank === maxPermission)
    .map(([name]) => name)[0] || 'READ';

  return { project, permission: highest };
}

// ========== GET : récupérer un projet avec ses items ==========
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Non authentifie' }, { status: 401 });
    }

    const { id: projectId } = await params;

    const project = await prisma.project.findUnique({
      where: { id: projectId },
      include: {
        items: {
          include: {
            product: true,
            service: true,
          },
        },
      },
    });

    if (!project) {
      return NextResponse.json({ error: 'Projet introuvable' }, { status: 404 });
    }

    const { permission } = await getUserProjectPermission(session.user.id, projectId);
    if (!permission) {
      return NextResponse.json({ error: 'Accès refusé' }, { status: 403 });
    }

    return NextResponse.json({
      ...project,
      userPermission: permission,
    });
  } catch (error) {
    console.error('GET /api/projects/[id] error:', error);
    return NextResponse.json({ error: 'Erreur serveur' }, { status: 500 });
  }
}

// ========== PUT : mettre à jour les notes de paiement (ou autres) ==========
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Non authentifie' }, { status: 401 });
    }

    const { id: projectId } = await params;

    const project = await prisma.project.findUnique({
      where: { id: projectId },
    });

    if (!project) {
      return NextResponse.json({ error: 'Projet introuvable' }, { status: 404 });
    }

    const { permission } = await getUserProjectPermission(session.user.id, projectId);
    if (!permission || !['EDIT', 'VALIDATE'].includes(permission)) {
      return NextResponse.json({ error: 'Accès refusé' }, { status: 403 });
    }

    const body = await request.json();
    const {
      paymentNotes,
      attachmentUrl,
      startDate,
      endDate,
      clientName,
      clientPhone,
      clientEmail,
      clientAddress,
      clientFeedbackStatus,
      clientFeedbackMessage,
      clientRejectReason,
      clientRejectDetails,
      sharePublicUrl,
      projectProgressMedia,
      portfolioMedia,
      portfolioRating,
      portfolioReview,
      clientBudgetMax,
      depositAmount,
      depositPercent,
      depositProofUrl,
      depositValidated,
      handoffStatus,
      handoffTargetFamily,
      handoffMessage,
    } = body;

    const normalizedDepositAmount = depositAmount !== undefined
      ? (depositAmount === '' || depositAmount === null ? null : Number(depositAmount))
      : project.depositAmount;

    const normalizedDepositPercent = depositPercent !== undefined
      ? (depositPercent === '' || depositPercent === null ? null : Number(depositPercent))
      : project.depositPercent;

    const normalizedDepositValidated = depositValidated !== undefined
      ? Boolean(depositValidated)
      : project.depositValidated;

    const normalizedProgressMedia = Array.isArray(projectProgressMedia)
      ? JSON.stringify(projectProgressMedia)
      : (typeof projectProgressMedia === 'string' ? projectProgressMedia : project.projectProgressMedia);

    const existingMetadata = (project.metadata && typeof project.metadata === 'object' && !Array.isArray(project.metadata))
      ? { ...(project.metadata as Record<string, unknown>) }
      : {};

    const nextMetadata = {
      ...existingMetadata,
      ...(handoffStatus !== undefined ? { handoffStatus: handoffStatus || 'none' } : {}),
      ...(handoffTargetFamily !== undefined ? { handoffTargetFamily: handoffTargetFamily || null } : {}),
      ...(handoffMessage !== undefined ? { handoffMessage: handoffMessage || '' } : {}),
      handoffUpdatedAt: new Date().toISOString(),
    };

    const updatedProject = await prisma.project.update({
      where: { id: projectId },
      data: {
        paymentNotes: paymentNotes ?? project.paymentNotes,
        attachmentUrl: attachmentUrl ?? project.attachmentUrl,
        startDate: startDate ? new Date(startDate) : project.startDate,
        endDate: endDate ? new Date(endDate) : project.endDate,
        clientName: clientName ?? project.clientName,
        clientPhone: clientPhone ?? project.clientPhone,
        clientEmail: clientEmail ?? project.clientEmail,
        clientAddress: clientAddress ?? project.clientAddress,
        clientFeedbackStatus: clientFeedbackStatus ?? project.clientFeedbackStatus,
        clientFeedbackMessage: clientFeedbackMessage ?? project.clientFeedbackMessage,
        clientRejectReason: clientRejectReason ?? project.clientRejectReason,
        clientRejectDetails: clientRejectDetails ?? project.clientRejectDetails,
        sharePublicUrl: sharePublicUrl ?? project.sharePublicUrl,
        projectProgressMedia: normalizedProgressMedia ?? project.projectProgressMedia,
        portfolioMedia: portfolioMedia ?? project.portfolioMedia,
        portfolioRating: portfolioRating !== undefined ? (portfolioRating === '' || portfolioRating === null ? null : Number(portfolioRating)) : project.portfolioRating,
        portfolioReview: portfolioReview ?? project.portfolioReview,
        clientBudgetMax: clientBudgetMax !== undefined ? (clientBudgetMax === '' || clientBudgetMax === null ? null : Number(clientBudgetMax)) : project.clientBudgetMax,
        depositAmount: normalizedDepositAmount,
        depositPercent: normalizedDepositPercent,
        depositProofUrl: depositProofUrl ?? project.depositProofUrl,
        depositValidated: normalizedDepositValidated || (
          normalizedDepositPercent !== null && normalizedDepositPercent >= 25
        ) || (
          normalizedDepositAmount !== null && project.clientBudgetMax !== null && project.clientBudgetMax > 0 && (normalizedDepositAmount / project.clientBudgetMax) * 100 >= 25
        ),
        metadata: nextMetadata,
      },
    });

    return NextResponse.json(updatedProject);
  } catch (error) {
    console.error('PUT /api/projects/[id] error:', error);
    return NextResponse.json({ error: 'Erreur serveur' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
// Si vous utilisez Stripe, importez Stripe
// import Stripe from 'stripe';
// const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Non authentifié' }, { status: 401 });
    }

    const body = await request.json();
    const { userAgentId, paymentMethodId } = body;

    if (!userAgentId) {
      return NextResponse.json({ error: 'userAgentId requis' }, { status: 400 });
    }

    // Récupérer le UserAgent
    const userAgent = await prisma.userAgent.findUnique({
      where: { id: userAgentId },
      include: { agent: true },
    });
    if (!userAgent || userAgent.userId !== session.user.id) {
      return NextResponse.json({ error: 'Abonnement introuvable' }, { status: 404 });
    }

    // Vérifier que l'essai est encore valide
    if (userAgent.status !== 'TRIAL') {
      return NextResponse.json({ error: 'Cet abonnement n\'est pas en essai' }, { status: 400 });
    }
    if (userAgent.trialEndDate && userAgent.trialEndDate < new Date()) {
      return NextResponse.json({ error: 'La période d\'essai est expirée' }, { status: 400 });
    }

    // --- Intégration Stripe ---
    // Si vous utilisez Stripe, créez un abonnement ou un paiement unique.
    // Ici on simule un paiement réussi.
    // const subscription = await stripe.subscriptions.create({
    //   customer: customerId,
    //   items: [{ price: 'price_xxx' }],
    //   default_payment_method: paymentMethodId,
    //   trial_end: Math.floor(Date.now() / 1000) + 14 * 86400, // si vous voulez prolonger l'essai
    // });
    // Puis mettez à jour userAgent avec stripeSubscriptionId

    // Mettre à jour le UserAgent
    const updated = await prisma.userAgent.update({
      where: { id: userAgentId },
      data: {
        status: 'ACTIVE',
        endDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000), // +1 mois
        // stripeSubscriptionId: subscription.id,
        trialEndDate: null, // fin de l'essai
      },
    });

    return NextResponse.json({ success: true, subscription: updated });
  } catch (error) {
    console.error('Payment error:', error);
    return NextResponse.json({ error: 'Erreur serveur' }, { status: 500 });
  }
}

"use client";

import { useState, useEffect, FormEvent } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import {
  Plus, Edit, Trash2, Search, Loader2, Upload, CheckCircle
} from "lucide-react";
import Sidebar from "@/components/Sidebar";

type Product = {
  id: string;
  name: string;
  description: string | null;
  category: string;
  purchasePrice: number;
  salePrice: number;
  stock: number;
  tvaRate: number;
  imageUrl: string | null;
};

export default function CataloguePage() {
  const router = useRouter();
  const { data: session } = useSession();

  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    category: "",
    purchasePrice: "",
    salePrice: "",
    stock: "",
    tvaRate: "20",
    imageUrl: "",
  });
  const [showImportModal, setShowImportModal] = useState(false);
  const [importFile, setImportFile] = useState<File | null>(null);
  const [importLoading, setImportLoading] = useState(false);

  const fetchProducts = async () => {
    try {
      const res = await fetch("/api/seller/products", { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setProducts(data);
      }
    } catch (error) {
      console.error("Erreur chargement produits:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      const url = editingProduct
        ? `/api/seller/products/${editingProduct.id}`
        : "/api/seller/products";
      const method = editingProduct ? "PUT" : "POST";
      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          name: formData.name,
          description: formData.description,
          category: formData.category,
          purchasePrice: parseFloat(formData.purchasePrice),
          salePrice: parseFloat(formData.salePrice),
          stock: parseInt(formData.stock) || 0,
          tvaRate: parseFloat(formData.tvaRate) || 20,
          imageUrl: formData.imageUrl || null,
        }),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Erreur");
      }
      await fetchProducts();
      setShowModal(false);
      setEditingProduct(null);
      setFormData({
        name: "",
        description: "",
        category: "",
        purchasePrice: "",
        salePrice: "",
        stock: "",
        tvaRate: "20",
        imageUrl: "",
      });
    } catch (error) {
      console.error("Erreur:", error);
      alert("Erreur lors de l'enregistrement");
    }
  };

  const deleteProduct = async (id: string) => {
    if (!confirm("Supprimer ce produit ?")) return;
    try {
      const res = await fetch(`/api/seller/products/${id}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (!res.ok) throw new Error("Erreur");
      await fetchProducts();
    } catch (error) {
      console.error("Erreur:", error);
      alert("Erreur lors de la suppression");
    }
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData({
      name: product.name,
      description: product.description || "",
      category: product.category,
      purchasePrice: String(product.purchasePrice),
      salePrice: String(product.salePrice),
      stock: String(product.stock),
      tvaRate: String(product.tvaRate),
      imageUrl: product.imageUrl || "",
    });
    setShowModal(true);
  };

  const handleImport = async () => {
    if (!importFile) return;
    setImportLoading(true);
    try {
      const formData = new FormData();
      formData.append('file', importFile);
      const res = await fetch('/api/seller/products/import', {
        method: 'POST',
        body: formData,
        credentials: 'include',
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || 'Erreur import');
      }
      const data = await res.json();
      alert(`✅ ${data.count} produits importés !`);
      await fetchProducts();
      setShowImportModal(false);
      setImportFile(null);
    } catch (error) {
      console.error('Erreur import:', error);
      alert('Erreur lors de l\'import : ' + (error as Error).message);
    } finally {
      setImportLoading(false);
    }
  };

  const filteredProducts = products.filter(p =>
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div className="min-h-screen flex items-center justify-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600" /></div>;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar />
      <div className="flex-1 ml-64 p-8">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold text-gray-800">📋 Mon catalogue</h1>
          <div className="flex gap-2">
            <button
              onClick={() => setShowImportModal(true)}
              className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition flex items-center gap-2 text-sm"
            >
              <Upload className="w-4 h-4" /> Importer
            </button>
            <button
              onClick={() => {
                setEditingProduct(null);
                setFormData({
                  name: "",
                  description: "",
                  category: "",
                  purchasePrice: "",
                  salePrice: "",
                  stock: "",
                  tvaRate: "20",
                  imageUrl: "",
                });
                setShowModal(true);
              }}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition flex items-center gap-2 text-sm"
            >
              <Plus className="w-4 h-4" /> Ajouter un produit
            </button>
          </div>
        </div>

        <div className="relative mb-4">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
          <input
            type="text"
            placeholder="Rechercher un produit..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
          {filteredProducts.length === 0 ? (
            <p className="text-gray-500 text-center py-8">Aucun produit dans votre catalogue.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Image</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Nom</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Catégorie</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Prix vente</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Stock</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredProducts.map((p) => (
                    <tr key={p.id} className="border-b border-gray-100 hover:bg-gray-50">
                      <td className="px-4 py-3 text-sm">
                        {p.imageUrl ? (
                          <img src={p.imageUrl} alt={p.name} className="w-10 h-10 object-cover rounded" />
                        ) : (
                          <div className="w-10 h-10 bg-gray-200 rounded flex items-center justify-center text-gray-400 text-xs">No img</div>
                        )}
                      </td>
                      <td className="px-4 py-3 text-sm font-medium">{p.name}</td>
                      <td className="px-4 py-3 text-sm">{p.category}</td>
                      <td className="px-4 py-3 text-sm">{p.salePrice} €</td>
                      <td className="px-4 py-3 text-sm">
                        <span className={`px-2 py-1 rounded-full text-xs ${p.stock < 5 ? "bg-red-100 text-red-800" : p.stock < 20 ? "bg-yellow-100 text-yellow-800" : "bg-green-100 text-green-800"}`}>
                          {p.stock}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-sm text-right">
                        <button onClick={() => openEditModal(p)} className="text-blue-600 hover:text-blue-800 mr-2">
                          <Edit className="w-4 h-4 inline" />
                        </button>
                        <button onClick={() => deleteProduct(p.id)} className="text-red-600 hover:text-red-800">
                          <Trash2 className="w-4 h-4 inline" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* MODALE AJOUT / MODIFICATION */}
        {showModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto">
            <div className="bg-white rounded-xl w-full max-w-md p-6 relative my-8">
              <button onClick={() => setShowModal(false)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600">✕</button>
              <h2 className="text-xl font-bold mb-4">{editingProduct ? "Modifier le produit" : "Ajouter un produit"}</h2>
              <form onSubmit={handleSubmit} className="space-y-4">
                <input placeholder="Nom *" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} className="w-full px-4 py-2 border rounded-lg" required />
                <input placeholder="Description" value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} className="w-full px-4 py-2 border rounded-lg" />
                <input placeholder="Catégorie *" value={formData.category} onChange={(e) => setFormData({ ...formData, category: e.target.value })} className="w-full px-4 py-2 border rounded-lg" required />
                <div className="grid grid-cols-2 gap-2">
                  <input placeholder="Prix achat HT" type="number" step="0.01" value={formData.purchasePrice} onChange={(e) => setFormData({ ...formData, purchasePrice: e.target.value })} className="w-full px-4 py-2 border rounded-lg" required />
                  <input placeholder="Prix vente TTC" type="number" step="0.01" value={formData.salePrice} onChange={(e) => setFormData({ ...formData, salePrice: e.target.value })} className="w-full px-4 py-2 border rounded-lg" required />
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <input placeholder="Stock" type="number" value={formData.stock} onChange={(e) => setFormData({ ...formData, stock: e.target.value })} className="w-full px-4 py-2 border rounded-lg" />
                  <input placeholder="TVA %" type="number" step="0.1" value={formData.tvaRate} onChange={(e) => setFormData({ ...formData, tvaRate: e.target.value })} className="w-full px-4 py-2 border rounded-lg" />
                </div>
                <input placeholder="URL image" value={formData.imageUrl} onChange={(e) => setFormData({ ...formData, imageUrl: e.target.value })} className="w-full px-4 py-2 border rounded-lg" />
                <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition">{editingProduct ? "Mettre à jour" : "Ajouter"}</button>
              </form>
            </div>
          </div>
        )}

        {/* MODALE IMPORT */}
        {showImportModal && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto">
            <div className="bg-white rounded-xl w-full max-w-md p-6 relative my-8">
              <button onClick={() => { setShowImportModal(false); setImportFile(null); }} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600">✕</button>
              <h2 className="text-xl font-bold mb-4">📤 Importer un catalogue</h2>
              <p className="text-sm text-gray-600 mb-4">
                Téléchargez un fichier CSV ou Excel avec les colonnes :<br/>
                <strong>Nom;Catégorie;PrixAchat;PrixVente;Stock;TVA;URLImage</strong>
              </p>
              <div className="relative w-full mb-4">
                <label className="flex flex-col items-center justify-center w-full py-6 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:bg-gray-50 transition">
                  <div className="flex flex-col items-center">
                    <Upload className="w-8 h-8 text-gray-400 mb-2" />
                    <p className="text-sm text-gray-600 font-medium">
                      {importFile ? importFile.name : "Cliquez pour choisir un fichier"}
                    </p>
                    <p className="text-xs text-gray-400 mt-1">CSV ou Excel (max 5 Mo)</p>
                  </div>
                  <input
                    type="file"
                    accept=".csv,.xlsx,.xls"
                    onChange={(e) => setImportFile(e.target.files?.[0] || null)}
                    className="hidden"
                  />
                </label>
                {importFile && (
                  <div className="mt-2 text-sm text-green-600 flex items-center gap-2">
                    <CheckCircle className="w-4 h-4" />
                    Fichier sélectionné : {importFile.name}
                  </div>
                )}
              </div>
              <div className="flex gap-2">
                <button
                  onClick={handleImport}
                  disabled={!importFile || importLoading}
                  className="flex-1 px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {importLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
                  {importLoading ? 'Importation...' : 'Importer'}
                </button>
                <button
                  onClick={() => { setShowImportModal(false); setImportFile(null); }}
                  className="px-4 py-2 bg-gray-300 rounded hover:bg-gray-400"
                >
                  Annuler
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import { Plus, Eye, Loader2, Award, BadgeCheck, ShieldCheck, Star, CheckCircle2 } from "lucide-react";
import Sidebar from "@/components/Sidebar";

type Project = {
  id: string;
  name: string;
  description: string | null;
  type: string | null;
  surface: number | null;
  status: string;
  budgetEstimate: number | null;
  clientBudgetMax: number | null;
  depositAmount: number | null;
  depositPercent: number | null;
  depositProofUrl: string | null;
  depositValidated: boolean | null;
  createdAt: string;
  clientName: string | null;
  clientPhone: string | null;
  clientEmail: string | null;
  clientAddress: string | null;
  clientFeedbackStatus: string | null;
  startDate: string | null;
  endDate: string | null;
  sharePublicUrl: string | null;
  portfolioRating: number | null;
  items: { id: string; productName: string; quantity: number; unitPriceHtAtSale?: number; unitPrice?: number; product?: { name?: string }; service?: { name?: string } }[];
};

type Question = {
  id: number;
  question: string;
  options: string[];
  correct: string;
};

const certificationQuestions: Question[] = [
  {
    id: 1,
    question: "Quel élément doit être vérifié avant de poser un revêtement de sol sur une surface existante ?",
    options: ["La couleur des murs", "L'état de la sous-face et son planéité", "La météo de la semaine prochaine"],
    correct: "L'état de la sous-face et son planéité",
  },
  {
    id: 2,
    question: "En cas de chantier humide, quelle précaution est prioritaire ?",
    options: ["Raccourcir les délais", "Prévoir un système de drainage et des matériaux adaptés", "Négocier la main d'œuvre"],
    correct: "Prévoir un système de drainage et des matériaux adaptés",
  },
  {
    id: 3,
    question: "Quelle information est indispensable pour établir un devis fiable ?",
    options: ["Le nom du voisin", "La nature du projet, la surface et le budget client", "Le numéro de plaque d'immatriculation"],
    correct: "La nature du projet, la surface et le budget client",
  },
  {
    id: 4,
    question: "Qu'est-ce qui permet d'améliorer la qualité d'un chantier de rénovation ?",
    options: ["Faire les travaux sans plan", "S'assurer d'une préparation du support et d'un suivi de chantier", "Éviter les échanges avec le client"],
    correct: "S'assurer d'une préparation du support et d'un suivi de chantier",
  },
  {
    id: 5,
    question: "Quelle bonne pratique protège le client lors d'un chantier en cours ?",
    options: ["Publier uniquement des photos de fin de chantier", "Renseigner les étapes, les délais et les points de vigilance", "Ne rien documenter avant le paiement"],
    correct: "Renseigner les étapes, les délais et les points de vigilance",
  },
];

const STORAGE_KEY = "aqil-bina-artisan-certification";

const normalizeProjectDescription = (value: string | null | undefined) => {
  if (!value) return { description: '', solSurface: null, murSurface: null };

  const raw = String(value).trim();
  if (!raw) return { description: '', solSurface: null, murSurface: null };

  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const description = typeof parsed.description === 'string' ? parsed.description.trim() : '';
      const solSurface = typeof parsed.sol?.surface === 'number' ? parsed.sol.surface : null;
      const murSurface = typeof parsed.mur?.surface === 'number' ? parsed.mur.surface : null;

      return {
        description,
        solSurface: solSurface !== null && Number(solSurface) > 0 ? Number(solSurface) : null,
        murSurface: murSurface !== null && Number(murSurface) > 0 ? Number(murSurface) : null,
      };
    }
  } catch {
    return { description: raw, solSurface: null, murSurface: null };
  }

  return { description: raw, solSurface: null, murSurface: null };
};

const getCertificationState = (score: number) => {
  if (score >= 85) return { label: "Expert certifié", color: "text-emerald-700", badge: "bg-emerald-100 text-emerald-700 border-emerald-200" };
  if (score >= 70) return { label: "Professionnel certifié", color: "text-blue-700", badge: "bg-blue-100 text-blue-700 border-blue-200" };
  if (score >= 50) return { label: "Certificat en cours", color: "text-amber-700", badge: "bg-amber-100 text-amber-700 border-amber-200" };
  return { label: "À renforcer", color: "text-rose-700", badge: "bg-rose-100 text-rose-700 border-rose-200" };
};

const computeQcmScore = (answers: Record<number, string>) => {
  const total = certificationQuestions.length;
  let correct = 0;
  certificationQuestions.forEach((question) => {
    if (answers[question.id] === question.correct) correct += 1;
  });
  return Math.round((correct / total) * 100);
};

export default function ProjetsPage() {
  const router = useRouter();
  const { data: session } = useSession();
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [hasActiveSubscription, setHasActiveSubscription] = useState(true);
  const [query, setQuery] = useState('');
  const [answers, setAnswers] = useState<Record<number, string>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [qcmValidated, setQcmValidated] = useState(false);

  const qcmScore = useMemo(() => computeQcmScore(answers), [answers]);
  const certification = useMemo(() => getCertificationState(qcmScore), [qcmScore]);

  const ratedProjects = useMemo(
    () => projects.filter((project) => typeof project.portfolioRating === 'number' && project.portfolioRating > 0),
    [projects]
  );
  const reviewedProjects = ratedProjects.length;
  const clientRating = ratedProjects.length > 0
    ? ratedProjects.reduce((sum, project) => sum + (project.portfolioRating ?? 0), 0) / ratedProjects.length
    : 4.9;
  const globalScore = Math.min(100, Math.round((qcmScore * 0.4) + ((clientRating / 5) * 100 * 0.4) + (Math.min(reviewedProjects, 20) / 20 * 100 * 0.2)));

  const fetchProjects = async (search = '') => {
    try {
      const res = await fetch(`/api/projects${search ? `?q=${encodeURIComponent(search)}` : ''}`, { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setProjects(data);
      }
    } catch (error) {
      console.error("Erreur chargement projets:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!session) {
      router.push('/auth/signin');
      return;
    }

    if (session.user.role !== 'artisan' && session.user.trade !== 'artisan') {
      router.push('/auth/signin');
      return;
    }

    const hydrateCertification = async () => {
      try {
        const profileRes = await fetch('/api/user/profile', { credentials: 'include' });
        if (profileRes.ok) {
          const data = await profileRes.json();
          const savedAnswers = data?.certificationAnswers ? JSON.parse(data.certificationAnswers) : null;
          if (savedAnswers && typeof savedAnswers === 'object') {
            setAnswers(savedAnswers);
            const hasValidation = Object.keys(savedAnswers).length > 0;
            setIsSubmitted(hasValidation);
            setQcmValidated(hasValidation);
          } else {
            const localSaved = window.localStorage.getItem(STORAGE_KEY);
            if (localSaved) {
              try {
                const parsed = JSON.parse(localSaved) as Record<number, string>;
                setAnswers(parsed);
                const hasValidation = Object.keys(parsed).length > 0;
                setIsSubmitted(hasValidation);
                setQcmValidated(hasValidation);
              } catch {
                setAnswers({});
              }
            }
          }
        } else {
          const localSaved = window.localStorage.getItem(STORAGE_KEY);
          if (localSaved) {
            try {
              const parsed = JSON.parse(localSaved) as Record<number, string>;
              setAnswers(parsed);
              const hasValidation = Object.keys(parsed).length > 0;
              setIsSubmitted(hasValidation);
              setQcmValidated(hasValidation);
            } catch {
              setAnswers({});
            }
          }
        }
      } catch {
        const localSaved = window.localStorage.getItem(STORAGE_KEY);
        if (localSaved) {
          try {
            const parsed = JSON.parse(localSaved) as Record<number, string>;
            setAnswers(parsed);
            const hasValidation = Object.keys(parsed).length > 0;
            setIsSubmitted(hasValidation);
            setQcmValidated(hasValidation);
          } catch {
            setAnswers({});
          }
        }
      }
    };

    void hydrateCertification();

    const checkAccess = async () => {
      try {
        const res = await fetch('/api/user/agents/check', { credentials: 'include' });
        const data = await res.json();
        const active = Boolean(res.ok && data?.hasActive);
        setHasActiveSubscription(active);

        if (!active) {
          router.push('/abonnement');
          return;
        }
      } catch {
        setHasActiveSubscription(false);
        router.push('/abonnement');
        return;
      }

      await fetchProjects();
    };

    void checkAccess();
  }, [session, router]);

  useEffect(() => {
    if (Object.keys(answers).length > 0) {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(answers));
    }
  }, [answers]);

  const handleAnswer = (questionId: number, value: string) => {
    setAnswers((current) => ({ ...current, [questionId]: value }));
  };

  const handleSubmit = async () => {
    if (qcmValidated || isSubmitted) return;

    setIsSubmitted(true);
    setQcmValidated(true);

    try {
      const score = computeQcmScore(answers);
      const nextLabel = getCertificationState(score).label;
      await fetch('/api/user/profile', {
        method: 'PUT',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          certificationScore: score,
          certificationLabel: nextLabel,
          certificationAnswers: JSON.stringify(answers),
        }),
      });
    } catch (error) {
      console.error('Erreur sauvegarde certification:', error);
    }
  };

  const getStatusBadge = (status: string) => {
    const normalized = (status || '').toUpperCase();

    switch (normalized) {
      case "BROUILLON": return <span className="bg-gray-100 text-gray-600 px-2 py-1 rounded text-xs">Brouillon</span>;
      case "EN_ATTENTE": return <span className="bg-yellow-100 text-yellow-800 px-2 py-1 rounded text-xs">En attente</span>;
      case "ACCEPTE":
      case "ACCEPTED": return <span className="bg-green-100 text-green-800 px-2 py-1 rounded text-xs">Accepté</span>;
      case "REFUSE":
      case "REJECTED": return <span className="bg-rose-100 text-rose-800 px-2 py-1 rounded text-xs">Refusé</span>;
      case "TERMINE":
      case "TERMINEE": return <span className="bg-blue-100 text-blue-800 px-2 py-1 rounded text-xs">Terminé</span>;
      default: return <span className="bg-gray-100 text-gray-800 px-2 py-1 rounded text-xs">{status}</span>;
    }
  };

  if (loading) {
    return <div className="min-h-screen flex items-center justify-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600" /></div>;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar />
      <div className="flex-1 ml-64 p-8">
        <div className="flex justify-between items-center mb-6 gap-4 flex-wrap">
          <h1 className="text-2xl font-bold text-gray-800">📋 Mes projets</h1>
          <button
            onClick={() => router.push("/artisan/projets/nouveau")}
            className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition flex items-center gap-2"
          >
            <Plus className="w-4 h-4" /> Nouveau projet
          </button>
        </div>

        <div className="mb-6 rounded-2xl border border-emerald-200 bg-gradient-to-r from-emerald-50 via-white to-sky-50 p-5 shadow-sm">
          <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex items-start gap-4">
              <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-emerald-100 text-emerald-700">
                <Award className="h-6 w-6" />
              </div>
              <div>
                <p className="text-xs font-semibold uppercase tracking-[0.18em] text-slate-500">Certification Aqil Bina</p>
                <h2 className="mt-1 text-2xl font-black text-slate-900">{certification.label}</h2>
                <p className="mt-1 text-sm text-slate-600">Badge public affiché à vos clients et partenaires.</p>
              </div>
            </div>

            <div className="rounded-2xl border border-slate-200 bg-white px-4 py-3 shadow-sm">
              <p className="text-xs uppercase tracking-[0.14em] text-slate-500">Score global</p>
              <div className="mt-1 flex items-baseline gap-2">
                <span className="text-3xl font-black text-slate-900">{globalScore}</span>
                <span className="text-sm text-slate-500">/ 100</span>
              </div>
            </div>
          </div>

          <div className="mt-5 grid gap-3 md:grid-cols-3">
            <div className="rounded-xl border border-slate-200 bg-white p-3">
              <p className="text-[10px] uppercase tracking-[0.12em] text-slate-500">QCM technique</p>
              <p className="mt-2 text-xl font-black text-blue-700">{qcmScore}%</p>
            </div>
            <div className="rounded-xl border border-slate-200 bg-white p-3">
              <p className="text-[10px] uppercase tracking-[0.12em] text-slate-500">Avis clients</p>
              <p className="mt-2 text-xl font-black text-emerald-700">{clientRating.toFixed(1)}/5</p>
            </div>
            <div className="rounded-xl border border-slate-200 bg-white p-3">
              <p className="text-[10px] uppercase tracking-[0.12em] text-slate-500">Volume</p>
              <p className="mt-2 text-xl font-black text-violet-700">{reviewedProjects} avis</p>
            </div>
          </div>
        </div>

        {!qcmValidated && (
          <div className="mt-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
            <div className="mb-4 flex items-center justify-between gap-3 flex-wrap">
              <div className="flex items-center gap-2">
                <ShieldCheck className="h-5 w-5 text-blue-600" />
                <h3 className="text-lg font-bold text-slate-900">Questionnaire de certification</h3>
              </div>
            </div>

            <div className="space-y-5">
              {certificationQuestions.map((question) => (
                <div key={question.id} className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                  <p className="font-semibold text-slate-900">{question.id}. {question.question}</p>
                  <div className="mt-3 grid gap-2 md:grid-cols-3">
                    {question.options.map((option) => {
                      const selected = answers[question.id] === option;
                      const isCorrect = isSubmitted && option === question.correct;
                      const isWrongSelected = isSubmitted && selected && option !== question.correct;

                      return (
                        <button
                          key={option}
                          type="button"
                          onClick={() => handleAnswer(question.id, option)}
                          className={`rounded-xl border px-3 py-2 text-left text-sm transition ${
                            isCorrect
                              ? "border-emerald-300 bg-emerald-100 text-emerald-800"
                              : isWrongSelected
                                ? "border-rose-300 bg-rose-100 text-rose-800"
                                : selected
                                  ? "border-blue-300 bg-blue-100 text-blue-700"
                                  : "border-slate-200 bg-white text-slate-700 hover:border-blue-200"
                          }`}
                        >
                          {option}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>

            <div className="mt-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div className="flex items-center gap-2 text-sm text-slate-600">
                {isSubmitted ? (
                  <>
                    <CheckCircle2 className="h-4 w-4 text-emerald-600" />
                    Score actuel : <span className={`font-bold ${certification.color}`}>{qcmScore}%</span>
                  </>
                ) : (
                  <>
                    <Star className="h-4 w-4 text-amber-500" />
                    Répondez à chaque question pour calculer votre badge public.
                  </>
                )}
              </div>

              <button
                type="button"
                onClick={handleSubmit}
                className="rounded-full bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-slate-300"
                disabled={qcmValidated || isSubmitted}
              >
                Valider mon QCM
              </button>
            </div>
          </div>
        )}

        <div className="mb-6 rounded-xl border border-gray-200 bg-white p-3 shadow-sm mt-6">
          <div className="flex flex-col gap-3 md:flex-row md:items-center">
            <input
              type="text"
              value={query}
              onChange={(e) => {
                const next = e.target.value;
                setQuery(next);
                if (next.trim().length >= 2 || next.trim().length === 0) {
                  void fetchProjects(next);
                }
              }}
              placeholder="Rechercher par nom client, téléphone ou email"
              className="w-full rounded-lg border border-gray-200 px-3 py-2 text-sm outline-none ring-0 focus:border-blue-500"
            />
          </div>
        </div>

        {projects.length === 0 ? (
          <p className="text-gray-500 text-center py-8">Aucun projet créé.</p>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {projects.map((project) => {
              const projectSummary = normalizeProjectDescription(project.description);
              const proposedTotal = project.items.reduce((sum: number, item: any) => {
                const quantity = Number(item.quantity || 0);
                const unitPrice = Number(item.unitPriceHtAtSale || item.unitPrice || 0);
                return sum + quantity * unitPrice;
              }, 0);
              const depositAmount = Number(project.depositAmount ?? 0);
              const depositPercent = Number(project.depositPercent ?? 0);
              const depositValid = Boolean(project.depositValidated) || depositPercent >= 25;
              const clientStatus = project.clientFeedbackStatus || "PENDING";

              return (
                <div key={project.id} className="rounded-[24px] border border-slate-200 bg-white p-5 shadow-sm transition hover:shadow-md">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <p className="text-[11px] font-semibold uppercase tracking-[0.12em] text-slate-500">Projet</p>
                      <h3 className="mt-1 text-[15px] font-bold text-slate-900 sm:text-lg">{project.name}</h3>
                    </div>
                    <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.12em] ${depositValid ? 'border border-emerald-200 bg-emerald-100 text-emerald-700' : 'border border-amber-200 bg-amber-100 text-amber-700'}`}>
                      {depositValid ? 'Paiement OK' : 'Paiement à valider'}
                    </span>
                  </div>

                  <div className="mt-4 space-y-3 text-sm text-slate-700">
                    <div><span className="font-medium text-slate-900">Nom du projet :</span> {project.name}</div>
                    <div><span className="font-medium text-slate-900">Type de projet :</span> {project.type || "Non spécifié"}</div>
                    <div><span className="font-medium text-slate-900">Statut de paiement :</span> {depositValid ? 'Validé' : 'À vérifier'}</div>
                  </div>

                  <button
                    onClick={() => router.push(`/artisan/projets/${project.id}`)}
                    className="mt-4 inline-flex items-center gap-2 rounded-full bg-blue-600 px-4 py-2 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700"
                  >
                    <Eye className="w-4 h-4" /> Voir l’offre
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { useSession } from "next-auth/react";
import {
  CheckCircle, XCircle, Loader2, ArrowLeft,
  Sparkles
} from "lucide-react";
import Sidebar from "@/components/Sidebar";

// Types (optionnels, pour une meilleure autocomplétion)
type ProjectItem = {
  id: string;
  productName: string | null;
  serviceName: string | null;
  quantity: number;
  unitPriceHtAtSale: number;
  tvaRate: number;
};

type Proposal = {
  id: string;
  quantity: number;
  unitPrice: number;
  status: string;
  message: string | null;
  marketingMessage: string | null;
  deliveryDate: string | null;
  createdAt: string;
  product: { name: string; salePrice: number };
  vendor: { name: string; companyName: string | null };
};

const normalizeProjectDescription = (value: string | null | undefined) => {
  if (!value) return { description: '', solSurface: null, murSurface: null };

  const raw = String(value).trim();
  if (!raw) return { description: '', solSurface: null, murSurface: null };

  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const description = typeof parsed.description === 'string' ? parsed.description.trim() : '';
      const solSurface = typeof parsed.sol?.surface === 'number' ? parsed.sol.surface : null;
      const murSurface = typeof parsed.mur?.surface === 'number' ? parsed.mur.surface : null;

      return {
        description,
        solSurface: solSurface !== null && Number(solSurface) > 0 ? Number(solSurface) : null,
        murSurface: murSurface !== null && Number(murSurface) > 0 ? Number(murSurface) : null,
      };
    }
  } catch {
    return { description: raw, solSurface: null, murSurface: null };
  }

  return { description: raw, solSurface: null, murSurface: null };
};

export default function ProjectDetailPage() {
  const router = useRouter();
  const params = useParams();
  const { data: session } = useSession();
  const projectId = params.id as string;

  const [project, setProject] = useState<any>(null);
  const [userPermission, setUserPermission] = useState<'READ' | 'COMMENT' | 'EDIT' | 'VALIDATE' | null>(null);
  const [proposals, setProposals] = useState<Proposal[]>([]);
  const [loading, setLoading] = useState(true);
  const projectSummary = normalizeProjectDescription(project?.description);
  const canEditProject = userPermission === 'EDIT' || userPermission === 'VALIDATE';
  const canValidateProject = userPermission === 'VALIDATE';
  const canManageProjectAccess = !!session?.user?.id && project?.userId === session.user.id;
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [assistantData, setAssistantData] = useState<any>(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [clientProvidedItems, setClientProvidedItems] = useState<Record<string, boolean>>({});
  const [recommendations, setRecommendations] = useState<any[]>([]);
  const [projectRecommendations, setProjectRecommendations] = useState<any[]>([]);
  const [availableTeams, setAvailableTeams] = useState<any[]>([]);
  const [teamAccesses, setTeamAccesses] = useState<any[]>([]);
  const [teamAccessForm, setTeamAccessForm] = useState({ teamId: '', permission: 'READ' });
  const [projectForm, setProjectForm] = useState<any>({
    startDate: '',
    endDate: '',
    clientName: '',
    clientPhone: '',
    clientEmail: '',
    clientAddress: '',
    clientFeedbackStatus: 'PENDING',
    clientFeedbackMessage: '',
    sharePublicUrl: '',
    projectProgressMedia: [] as string[],
    portfolioMedia: [],
    portfolioRating: '',
    portfolioReview: '',
    clientBudgetMax: '',
    depositAmount: '',
    depositPercent: '',
    depositProofUrl: '',
    depositValidated: false,
    handoffStatus: 'none',
    handoffTargetFamily: 'vendeur',
    handoffMessage: '',
  });
  const [discountFinalPrice, setDiscountFinalPrice] = useState<string>('');

  const openDiscountResponse = (type: 'accept' | 'refuse', finalPrice?: string) => {
    const baseUrl = projectForm.sharePublicUrl || `/projets/${projectId}`;
    const params = new URLSearchParams();

    if (type === 'accept') {
      const priceValue = finalPrice && Number(finalPrice) > 0 ? Number(finalPrice).toFixed(2) : '0.00';
      params.set('artisanAction', 'final-price');
      params.set('artisanFinalPrice', priceValue);
      params.set('artisanMessage', `Voici le prix final non négociable : ${priceValue} €.`);
    } else {
      params.set('artisanAction', 'refused');
      params.set('artisanMessage', 'Je vous remercie pour votre demande mais malheureusement je ne peux pas accéder à votre requête. Nous ferons de notre possible pour vous offrir le meilleur travail possible.');
    }

    const separator = baseUrl.includes('?') ? '&' : '?';
    const targetUrl = `${baseUrl}${separator}${params.toString()}`;
    window.open(targetUrl, '_blank', 'noopener,noreferrer');
  };

  const parseMediaList = (value: string | string[] | null | undefined) => {
    if (Array.isArray(value)) return value.filter(Boolean);
    if (!value) return [];

    try {
      const parsed = JSON.parse(value);
      if (Array.isArray(parsed)) return parsed.filter(Boolean);
    } catch {
      // no-op
    }

    return String(value)
      .split(',')
      .map((item) => item.trim())
      .filter(Boolean);
  };

  const uploadProgressMedia = async (files: FileList | null) => {
    if (!files || files.length === 0) return;

    try {
      const uploadedUrls: string[] = [];

      for (const file of Array.from(files)) {
        const form = new FormData();
        form.append('file', file);

        const res = await fetch('/api/upload', {
          method: 'POST',
          body: form,
          credentials: 'include',
        });

        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Upload impossible');
        uploadedUrls.push(data.url);
      }

      setProjectForm((prev: any) => ({
        ...prev,
        projectProgressMedia: [...parseMediaList(prev.projectProgressMedia), ...uploadedUrls],
      }));

      alert(`${uploadedUrls.length} média${uploadedUrls.length > 1 ? 'x' : ''} ajouté${uploadedUrls.length > 1 ? 's' : ''} avec succès`);
    } catch (error) {
      alert('Erreur upload média : ' + (error as Error).message);
    }
  };

  const updateProjectMeta = async () => {
    if (!projectId) return;

    try {
      const payload = {
        ...projectForm,
        projectProgressMedia: projectForm.projectProgressMedia?.length
          ? JSON.stringify(projectForm.projectProgressMedia)
          : '',
        portfolioMedia: Array.isArray(projectForm.portfolioMedia)
          ? JSON.stringify(projectForm.portfolioMedia)
          : (projectForm.portfolioMedia || ''),
      };

      const res = await fetch(`/api/projects/${projectId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || 'Erreur');
      }

      await fetchProject();
      alert('✅ Informations du projet mises à jour');
    } catch (error) {
      console.error('Erreur mise à jour projet:', error);
      alert('Erreur lors de la mise à jour : ' + (error as Error).message);
    }
  };

  const fetchTeamAccesses = async () => {
    if (!projectId) return;

    try {
      const [teamsRes, accessRes] = await Promise.all([
        fetch('/api/user/teams', { credentials: 'include' }),
        fetch(`/api/projects/${projectId}/team-access`, { credentials: 'include' }),
      ]);

      if (teamsRes.ok) {
        const teamsData = await teamsRes.json();
        setAvailableTeams(Array.isArray(teamsData) ? teamsData : []);
      }

      if (accessRes.ok) {
        const accessData = await accessRes.json();
        setTeamAccesses(Array.isArray(accessData) ? accessData : []);
      }
    } catch (error) {
      console.error('Erreur chargement accès équipes projet:', error);
      setAvailableTeams([]);
      setTeamAccesses([]);
    }
  };

  const fetchProjectRecommendations = async () => {
    if (!projectId) return;

    try {
      const res = await fetch(`/api/projects/${projectId}/recommendations`, { credentials: 'include' });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || 'Erreur récupération recommandations');
      }

      const data = await res.json();
      setProjectRecommendations(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Erreur chargement recommandations projet:', error);
      setProjectRecommendations([]);
    }
  };

  const handleRecommendationValidation = async (recommendationId: string, status: 'VALIDATED' | 'REJECTED' | 'MODIFIED', validationNote?: string) => {
    if (!recommendationId) return;

    try {
      const res = await fetch(`/api/projects/${projectId}/recommendations`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ recommendationId, status, validationNote: validationNote || undefined }),
      });

      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Erreur validation recommandation');
      await fetchProjectRecommendations();
      alert('✅ Recommandation mise à jour.');
    } catch (error) {
      alert('Erreur : ' + (error as Error).message);
    }
  };

  const handleShareWithTeam = async () => {
    if (!projectId || !teamAccessForm.teamId) {
      alert('Sélectionnez d’abord une équipe.');
      return;
    }

    try {
      const res = await fetch(`/api/projects/${projectId}/team-access`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          teamId: teamAccessForm.teamId,
          permission: teamAccessForm.permission,
        }),
      });

      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Erreur partage équipe');

      setTeamAccessForm({ teamId: '', permission: 'READ' });
      await fetchTeamAccesses();
      alert('✅ Accès équipe mis à jour.');
    } catch (error) {
      alert('Erreur : ' + (error as Error).message);
    }
  };

  const handleRemoveTeamAccess = async (accessId: string) => {
    if (!accessId) return;

    try {
      const res = await fetch(`/api/projects/${projectId}/team-access`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ accessId }),
      });

      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Erreur retrait accès');
      await fetchTeamAccesses();
      alert('✅ Accès retiré.');
    } catch (error) {
      alert('Erreur : ' + (error as Error).message);
    }
  };

  // ===== FETCH PROJECT =====
  const fetchProject = async () => {
    try {
      const res = await fetch(`/api/projects/${projectId}`, { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setProject(data);
        setUserPermission(data.userPermission || null);
        const effectiveDepositPercent = data.depositPercent ?? (
          data.clientBudgetMax && Number(data.clientBudgetMax) > 0 && data.depositAmount
            ? (Number(data.depositAmount) / Number(data.clientBudgetMax)) * 100
            : null
        );

        const metadata = (data.metadata && typeof data.metadata === 'object' && !Array.isArray(data.metadata)) ? data.metadata : {};

        setProjectForm({
          startDate: data.startDate ? new Date(data.startDate).toISOString().slice(0, 10) : '',
          endDate: data.endDate ? new Date(data.endDate).toISOString().slice(0, 10) : '',
          clientName: data.clientName || '',
          clientPhone: data.clientPhone || '',
          clientEmail: data.clientEmail || '',
          clientAddress: data.clientAddress || '',
          clientFeedbackStatus: data.clientFeedbackStatus || 'PENDING',
          clientFeedbackMessage: data.clientFeedbackMessage || '',
          sharePublicUrl: data.sharePublicUrl || '',
          projectProgressMedia: parseMediaList(data.projectProgressMedia),
          portfolioMedia: parseMediaList(data.portfolioMedia),
          portfolioRating: data.portfolioRating != null ? String(data.portfolioRating) : '',
          portfolioReview: data.portfolioReview || '',
          clientBudgetMax: data.clientBudgetMax != null ? String(data.clientBudgetMax) : '',
          depositAmount: data.depositAmount != null ? String(data.depositAmount) : '',
          depositPercent: effectiveDepositPercent != null ? String(effectiveDepositPercent) : '',
          depositProofUrl: data.depositProofUrl || '',
          depositValidated: Boolean(data.depositValidated) || (effectiveDepositPercent != null && effectiveDepositPercent >= 25),
          handoffStatus: typeof metadata.handoffStatus === 'string' ? metadata.handoffStatus : 'none',
          handoffTargetFamily: typeof metadata.handoffTargetFamily === 'string' ? metadata.handoffTargetFamily : 'vendeur',
          handoffMessage: typeof metadata.handoffMessage === 'string' ? metadata.handoffMessage : '',
        });
      } else {
        console.error("Erreur fetch project:", await res.text());
      }
    } catch (error) {
      console.error("Erreur chargement projet:", error);
    }
  };

  // ===== FETCH PROPOSALS =====
  const fetchProposals = async () => {
    try {
      const res = await fetch(`/api/projects/${projectId}/proposals`, { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setProposals(data);
      } else {
        console.error("Erreur fetch proposals:", await res.text());
      }
    } catch (error) {
      console.error("Erreur chargement offres:", error);
    }
  };

  // ===== ACCEPTER OFFRE =====
  const handleAccept = async (proposalId: string) => {
    if (!confirm("Accepter cette offre ?")) return;
    setActionLoading(proposalId);
    try {
      const res = await fetch(`/api/proposals/${proposalId}/accept`, {
        method: "PATCH",
        credentials: "include",
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Erreur");
      }
      await fetchProposals();
      alert("✅ Offre acceptée !");
    } catch (error) {
      console.error("Erreur acceptation:", error);
      alert("Erreur lors de l'acceptation : " + (error as Error).message);
    } finally {
      setActionLoading(null);
    }
  };

  // ===== REFUSER OFFRE =====
  const handleRefuse = async (proposalId: string) => {
    const reason = window.prompt(
      "Raison du refus ?\n1 = Prix trop élevé\n2 = Délais incompatibles\n3 = Qualité / produit non adapté\n4 = Autre",
      "1"
    );
    if (reason === null) return;

    const reasonMap: Record<string, string> = {
      '1': 'PRIX_TROP_ELEVE',
      '2': 'DELAIS_INCOMPATIBLES',
      '3': 'QUALITE_NON_ADAPTEE',
      '4': 'AUTRE',
    };

    const normalizedReason = reasonMap[reason.trim()] || 'AUTRE';
    const details = window.prompt("Décrivez précisément la raison du refus (ou laissez vide si aucun détail).", "") || '';

    setActionLoading(proposalId);
    try {
      const res = await fetch(`/api/proposals/${proposalId}/refuse`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ reason: normalizedReason, details }),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Erreur");
      }
      await fetchProposals();
      alert("Offre refusée avec motif enregistré.");
    } catch (error) {
      console.error("Erreur refus:", error);
      alert("Erreur lors du refus : " + (error as Error).message);
    } finally {
      setActionLoading(null);
    }
  };

  // ===== IA (appel à l'API assistant/advice) =====
  const handleAIAnalysis = async () => {
    setAiLoading(true);
    try {
      const res = await fetch('/api/assistant/advice', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ projectId }),
      });
      if (res.ok) {
        const data = await res.json();
        let analysisText = '';
        if (data.advice && Array.isArray(data.advice)) {
          analysisText = data.advice.map((item: any) => {
            return `🔹 ${item.title}\n${item.description}\n${item.action ? '➡️ ' + item.action : ''}\n`;
          }).join('\n');
        } else if (data.analysis) {
          analysisText = data.analysis;
        } else {
          analysisText = JSON.stringify(data, null, 2);
        }
        setAiAnalysis(analysisText);
      } else {
        const err = await res.json();
        alert('Erreur lors de l’analyse IA : ' + (err.error || ''));
      }
    } catch (error) {
      console.error(error);
      alert('Erreur réseau lors de l’analyse IA');
    } finally {
      setAiLoading(false);
    }
  };

  const handleArtisanAssistant = async () => {
    setAiLoading(true);
    try {
      const res = await fetch('/api/artisan/assistant', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ projectId }),
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({ error: 'Erreur inconnue' }));
        throw new Error(errorData.error || 'Erreur lors du calcul assistant');
      }

      const data = await res.json();
      setAssistantData(data);
      setAiAnalysis('Assistant artisan prêt : estimations, plan de chantier et comparaison d’offres disponibles ci-dessous.');
    } catch (error) {
      console.error('Erreur assistant artisan:', error);
      alert(error instanceof Error ? error.message : 'Erreur réseau lors de l’assistant artisan');
    } finally {
      setAiLoading(false);
    }
  };

  const toggleClientProvidedItem = (itemId: string) => {
    setClientProvidedItems((prev) => ({
      ...prev,
      [itemId]: !prev[itemId],
    }));
  };

  const addRecommendation = () => {
    setRecommendations((prev) => [
      ...prev,
      {
        id: `rec-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        productName: 'Produit recommandé',
        brand: '',
        vendorName: '',
        unitPrice: 0,
        externalUrl: '',
        notes: '',
        selected: prev.length === 0,
      },
    ]);
  };

  const updateRecommendation = (id: string, field: string, value: string | number | boolean) => {
    setRecommendations((prev) => prev.map((item) =>
      item.id === id ? { ...item, [field]: value } : item
    ));
  };

  const selectedRecommendation = recommendations.find((item) => item.selected) || recommendations[0] || null;

  const projectTotalHt = project?.items?.reduce((sum: number, item: any) => {
    const quantity = Number(item.quantity || 0);
    const unitPrice = Number(item.unitPriceHtAtSale || 0);
    return sum + quantity * unitPrice;
  }, 0) || 0;

  const materialTotal = project?.items?.reduce((sum: number, item: any) => {
    if (!item.product) return sum;
    const quantity = Number(item.quantity || 0);
    const unitPrice = Number(item.unitPriceHtAtSale || 0);
    return sum + quantity * unitPrice;
  }, 0) || 0;

  const serviceTotal = project?.items?.reduce((sum: number, item: any) => {
    if (!item.service) return sum;
    const quantity = Number(item.quantity || 0);
    const unitPrice = Number(item.unitPriceHtAtSale || 0);
    return sum + quantity * unitPrice;
  }, 0) || 0;

  const excludedClientTotal = project?.items?.reduce((sum: number, item: any) => {
    if (!clientProvidedItems[item.id]) return sum;
    const quantity = Number(item.quantity || 0);
    const unitPrice = Number(item.unitPriceHtAtSale || 0);
    return sum + quantity * unitPrice;
  }, 0) || 0;

  const budgetLimit = projectForm.clientBudgetMax ? Number(projectForm.clientBudgetMax) : null;
  const effectiveProjectTotal = Math.max(projectTotalHt - excludedClientTotal, 0);
  const budgetExceeded = budgetLimit !== null && effectiveProjectTotal > budgetLimit;
  const projectProgressMedia = Array.isArray(projectForm.projectProgressMedia) ? projectForm.projectProgressMedia : [];
  const portfolioMedia = Array.isArray(projectForm.portfolioMedia) ? projectForm.portfolioMedia : [];

  const renderMediaCard = (url: string, label: string, compact = false) => {
    const isVideo = /\.(mp4|webm|mov|avi|m4v)(\?.*)?$/i.test(url) || /video/i.test(url);

    return (
      <div key={`${label}-${url}`} className={`overflow-hidden rounded-xl border border-slate-200 bg-white ${compact ? 'h-28' : 'h-40'}`}>
        {isVideo ? (
          <video src={url} controls className="h-full w-full object-cover" />
        ) : (
          <img src={url} alt={label} className="h-full w-full object-cover" />
        )}
      </div>
    );
  };

  // ===== LOAD =====
  useEffect(() => {
    const load = async () => {
      setLoading(true);
      await Promise.all([fetchProject(), fetchProposals(), fetchTeamAccesses(), fetchProjectRecommendations()]);
      setLoading(false);
    };
    load();
  }, [projectId]);

  useEffect(() => {
    if (!project?.items || project.items.length === 0) {
      if (recommendations.length === 0) {
        setRecommendations([
          {
            id: 'default-rec-1',
            productName: 'Produit à comparer',
            brand: '',
            vendorName: '',
            unitPrice: 0,
            externalUrl: '',
            notes: '',
            selected: true,
          },
        ]);
      }
      return;
    }

    setRecommendations((prev) => {
      if (prev.length > 0) return prev;

      return project.items.slice(0, 3).map((item: any, index: number) => {
        const name = item.product?.name || item.service?.name || 'Produit recommandé';
        return {
          id: `proj-rec-${item.id || index}`,
          productName: name,
          brand: '',
          vendorName: '',
          unitPrice: Number(item.unitPriceHtAtSale || 0),
          externalUrl: '',
          notes: '',
          selected: index === 0,
        };
      });
    });
  }, [project]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  if (!project) {
    return (
      <div className="min-h-screen flex items-center justify-center text-gray-500">
        Projet introuvable.
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar />
      <div className="flex-1 ml-64 p-8">
        <button
          onClick={() => router.push("/artisan")}
          className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-6"
        >
          <ArrowLeft className="w-4 h-4" /> Retour à mes projets
        </button>

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">
          <div className="flex justify-between items-center gap-2 flex-wrap">
            <h1 className="text-2xl font-bold text-gray-800">{project.name}</h1>
            {(project.status === 'ACCEPTE' || project.clientFeedbackStatus === 'ACCEPTED') && (
              <span className="rounded-full bg-emerald-100 px-3 py-1 text-sm font-medium text-emerald-800">✅ Projet accepté par le client</span>
            )}
            {(project.status === 'REFUSE' || project.clientFeedbackStatus === 'REJECTED') && (
              <span className="rounded-full bg-rose-100 px-3 py-1 text-sm font-medium text-rose-800">⚠️ Projet refusé par le client</span>
            )}
            {(project.clientFeedbackStatus === 'REQUEST_DISCOUNT') && (
              <span className="rounded-full bg-amber-100 px-3 py-1 text-sm font-medium text-amber-800">💸 Demande de remise du client</span>
            )}
          </div>

          {project.clientFeedbackStatus === 'REQUEST_DISCOUNT' && (
            <div className="mt-4 rounded-lg border border-amber-300 bg-amber-50 px-4 py-3 text-sm text-amber-900">
              <strong>Demande de remise reçue :</strong> le client souhaite une négociation sur le devis. Vérifiez le commentaire ci-dessous et ajustez votre offre si nécessaire.
            </div>
          )}

          {budgetExceeded && (
            <div className="mt-4 rounded-lg border border-amber-300 bg-amber-50 px-4 py-3 text-sm text-amber-900">
              ⚠️ Le montant estimé du projet dépasse le budget max client. Coût actuel estimé : <strong>{effectiveProjectTotal.toFixed(2)} €</strong> pour un budget de <strong>{budgetLimit!.toFixed(2)} €</strong>.
              <div className="mt-1 text-xs text-amber-800">Le client a un budget maximal, il faut soit revaloriser le devis soit ajuster les quantités ou les matériaux fournis par le client.</div>
            </div>
          )}

          <div className="mt-6 space-y-4">
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-4">
              <div className="rounded-2xl border border-sky-200 bg-sky-50 p-4 xl:col-span-1 shadow-sm shadow-sky-100/80">
                <p className="text-[11px] font-semibold uppercase tracking-[0.12em] text-sky-700">Infos client</p>
                <div className="mt-3 grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-slate-700">
                  {project.clientName && <div><span className="font-medium text-slate-900">Nom client :</span> {project.clientName}</div>}
                  {project.clientPhone && <div><span className="font-medium text-slate-900">Téléphone :</span> {project.clientPhone}</div>}
                  {project.clientEmail && <div className="md:col-span-2"><span className="font-medium text-slate-900">Email :</span> {project.clientEmail}</div>}
                  {project.clientAddress && <div className="md:col-span-2"><span className="font-medium text-slate-900">Adresse :</span> {project.clientAddress}</div>}
                </div>

                <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Nom client</span>
                    <input type="text" value={projectForm.clientName} onChange={(e) => setProjectForm({ ...projectForm, clientName: e.target.value })} disabled={!canEditProject} className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" />
                  </label>
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Téléphone</span>
                    <input type="text" value={projectForm.clientPhone} onChange={(e) => setProjectForm({ ...projectForm, clientPhone: e.target.value })} disabled={!canEditProject} className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" />
                  </label>
                  <label className="text-sm text-gray-700 md:col-span-2">
                    <span className="block mb-1 font-medium">Email client</span>
                    <input type="email" value={projectForm.clientEmail} onChange={(e) => setProjectForm({ ...projectForm, clientEmail: e.target.value })} disabled={!canEditProject} className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" />
                  </label>
                  <label className="text-sm text-gray-700 md:col-span-2">
                    <span className="block mb-1 font-medium">Adresse client</span>
                    <input type="text" value={projectForm.clientAddress} onChange={(e) => setProjectForm({ ...projectForm, clientAddress: e.target.value })} disabled={!canEditProject} className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" />
                  </label>
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Date de début</span>
                    <input type="date" value={projectForm.startDate} onChange={(e) => setProjectForm({ ...projectForm, startDate: e.target.value })} disabled={!canEditProject} className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" />
                  </label>
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Date de fin</span>
                    <input type="date" value={projectForm.endDate} onChange={(e) => setProjectForm({ ...projectForm, endDate: e.target.value })} disabled={!canEditProject} className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" />
                  </label>
                </div>
              </div>

              <div className="rounded-2xl border border-rose-200 bg-rose-50 p-4 xl:col-span-2 shadow-sm shadow-rose-100/80">
                <p className="text-[11px] font-semibold uppercase tracking-[0.12em] text-rose-700">Infos projet</p>

                <div className="mt-3 grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-slate-700">
                  {project.type && <div><span className="font-medium text-slate-900">Type :</span> {project.type}</div>}
                  {project.surface && <div><span className="font-medium text-slate-900">Surface :</span> {project.surface} m²</div>}
                  <div><span className="font-medium text-slate-900">Statut :</span> {project.status || "BROUILLON"}</div>
                  {projectSummary.description ? (
                    <div className="md:col-span-2 text-slate-600"><span className="font-medium text-slate-900">Description :</span> {projectSummary.description}</div>
                  ) : null}
                </div>

                {project.items && project.items.length > 0 && (
                  <div className="mt-4 border-t border-rose-200 pt-4">
                    <p className="text-sm font-medium text-gray-700 mb-2">📦 Matériaux / Prestations :</p>
                    <div className="space-y-3">
                      {project.items.map((item: any) => {
                        const name = item.product?.name || item.service?.name || 'Inconnu';
                        const kind = item.product ? 'Produit' : item.service ? 'Prestation' : 'Ligne';
                        const isProvidedByClient = !!clientProvidedItems[item.id];
                        const lineTotal = Number(item.quantity || 0) * Number(item.unitPriceHtAtSale || 0);

                        return (
                          <div
                            key={item.id}
                            className={`rounded-lg border p-3 ${isProvidedByClient ? 'border-green-200 bg-green-50' : 'border-white bg-white/60'}`}
                          >
                            <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
                              <div className="text-sm text-gray-700">
                                <span className="font-medium text-gray-900">{name}</span>
                                <span className="mx-2 text-xs uppercase tracking-wide text-gray-500">{kind}</span>
                                <span className="mx-2">–</span>
                                {item.quantity} unité(s)
                                <span className="mx-2">–</span>
                                {item.unitPriceHtAtSale} € HT
                                <span className="ml-2 text-gray-500">({lineTotal.toFixed(2)} €)</span>
                              </div>
                              {item.product && (
                                <label className="flex items-center gap-2 text-xs text-gray-700">
                                  <input
                                    type="checkbox"
                                    checked={isProvidedByClient}
                                    onChange={() => toggleClientProvidedItem(item.id)}
                                    className="h-4 w-4 rounded border-gray-300 text-green-600 focus:ring-green-500"
                                  />
                                  Matériel fourni par le client
                                </label>
                              )}
                            </div>
                            {isProvidedByClient && item.product && (
                              <div className="mt-2 text-xs text-green-700 bg-white border border-green-200 rounded px-2 py-1">
                                ✅ Prix exclu du devis : ce matériel est à la charge du client.
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                    <div className="mt-4 rounded-lg bg-white/70 border border-rose-200 p-3 text-sm text-slate-700">
                      <div className="flex flex-col gap-1 md:flex-row md:items-center md:justify-between">
                        <span>Montant total du devis :</span>
                        <strong>{projectTotalHt.toFixed(2)} €</strong>
                      </div>
                      <div className="flex flex-col gap-1 md:flex-row md:items-center md:justify-between">
                        <span>Montant matériels :</span>
                        <strong>{materialTotal.toFixed(2)} €</strong>
                      </div>
                      <div className="flex flex-col gap-1 md:flex-row md:items-center md:justify-between">
                        <span>Montant prestations artisan :</span>
                        <strong>{serviceTotal.toFixed(2)} €</strong>
                      </div>
                      <div className="flex flex-col gap-1 md:flex-row md:items-center md:justify-between">
                        <span>Matériaux fournis par le client :</span>
                        <strong>{excludedClientTotal.toFixed(2)} €</strong>
                      </div>
                      <div className="flex flex-col gap-1 md:flex-row md:items-center md:justify-between">
                        <span>Montant net après ajustement :</span>
                        <strong>{effectiveProjectTotal.toFixed(2)} €</strong>
                      </div>
                    </div>
                  </div>
                )}

                <div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                  {projectSummary.description ? (
                    <label className="text-sm text-gray-700 md:col-span-2">
                      <span className="block mb-1 font-medium">Description</span>
                      <textarea value={projectSummary.description} readOnly className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-gray-100" rows={3} />
                    </label>
                  ) : null}
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 xl:grid-cols-3 gap-4">
              <div className="rounded-2xl border border-violet-200 bg-violet-50 p-4 xl:col-span-2 shadow-sm shadow-violet-100/80">
                <p className="text-[11px] font-semibold uppercase tracking-[0.12em] text-violet-700">Compléments</p>
                <div className="mt-3 grid grid-cols-1 md:grid-cols-2 gap-4">
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Statut client</span>
                    <select value={projectForm.clientFeedbackStatus} onChange={(e) => setProjectForm({ ...projectForm, clientFeedbackStatus: e.target.value })} disabled={!canEditProject} className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500">
                      <option value="PENDING">En attente</option>
                      <option value="CONFIRMED">Confirmé</option>
                      <option value="REQUEST_CHANGES">Demande des modifications</option>
                      <option value="REJECTED">Refusé</option>
                    </select>
                  </label>
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">URL publique du projet</span>
                    <input type="text" value={projectForm.sharePublicUrl} onChange={(e) => setProjectForm({ ...projectForm, sharePublicUrl: e.target.value })} disabled={!canEditProject} className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500" placeholder="https://..." />
                  </label>
                  <label className="text-sm text-gray-700 md:col-span-2">
                    <span className="block mb-1 font-medium">Commentaire client / retour</span>
                    <textarea value={projectForm.clientFeedbackMessage} onChange={(e) => setProjectForm({ ...projectForm, clientFeedbackMessage: e.target.value })} disabled={!canEditProject} className={`w-full px-3 py-2 border rounded-lg disabled:bg-slate-100 disabled:text-slate-500 ${projectForm.clientFeedbackStatus === 'REQUEST_DISCOUNT' ? 'border-amber-300 bg-amber-50' : 'border-gray-300 bg-white'}`} rows={3} />
                  </label>

                  {projectForm.clientFeedbackStatus === 'REQUEST_DISCOUNT' && (
                    <div className="md:col-span-2 rounded-xl border border-amber-200 bg-amber-50 p-4">
                      <p className="text-sm font-semibold text-amber-900">Réponse à la demande de remise</p>
                      <div className="mt-3 grid grid-cols-1 md:grid-cols-[1fr_auto_auto] gap-3 items-end">
                        <label className="text-sm text-gray-700">
                          <span className="block mb-1 font-medium">Prix final (€)</span>
                          <input
                            type="number"
                            min="0"
                            step="0.01"
                            value={discountFinalPrice}
                            onChange={(e) => setDiscountFinalPrice(e.target.value)}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                            placeholder="300.00"
                          />
                        </label>

                        <button
                          type="button"
                          onClick={() => openDiscountResponse('accept', discountFinalPrice)}
                          disabled={!canEditProject}
                          className="rounded-lg bg-emerald-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                          OK
                        </button>

                        <button
                          type="button"
                          onClick={() => openDiscountResponse('refuse')}
                          disabled={!canEditProject}
                          className="rounded-lg bg-rose-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-rose-700 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                          Refus
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              <div className={`rounded-2xl border p-4 shadow-sm ${Number(projectForm.depositPercent || 0) >= 25 ? 'border-emerald-200 bg-emerald-50 shadow-emerald-100/80' : 'border-amber-200 bg-amber-50 shadow-amber-100/80'}`}>
                <p className="text-[11px] font-semibold uppercase tracking-[0.12em] text-slate-500">Infos paiement</p>
                <div className="mt-3 space-y-3 text-sm text-slate-700">
                  <div><span className="font-medium text-slate-900">Statut :</span> {Number(projectForm.depositPercent || 0) >= 25 ? 'Validé' : 'À valider'}</div>
                </div>

                <div className="mt-4 space-y-4">
                  <label className="text-sm text-gray-700 block">
                    <span className="block mb-1 font-medium">Acompte versé (€)</span>
                    <input
                      type="number"
                      min="0"
                      step="0.01"
                      value={projectForm.depositAmount}
                      onChange={(e) => {
                        const nextAmount = e.target.value;
                        const clientBudget = Number(projectForm.clientBudgetMax || 0);
                        const percent = clientBudget > 0 && nextAmount !== '' ? (Number(nextAmount) / clientBudget) * 100 : 0;
                        setProjectForm({
                          ...projectForm,
                          depositAmount: nextAmount,
                          depositPercent: nextAmount === '' ? '' : String(percent),
                          depositValidated: percent >= 25,
                        });
                      }}
                      disabled={!canEditProject}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500"
                      placeholder="2500"
                    />
                  </label>
                  <label className="text-sm text-gray-700 block">
                    <span className="block mb-1 font-medium">Pourcentage (%)</span>
                    <input
                      type="number"
                      min="0"
                      max="100"
                      step="0.1"
                      value={projectForm.depositPercent}
                      onChange={(e) => {
                        const nextPercent = e.target.value;
                        setProjectForm({
                          ...projectForm,
                          depositPercent: nextPercent,
                          depositValidated: Number(nextPercent || 0) >= 25,
                        });
                      }}
                      disabled={!canEditProject}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500"
                      placeholder="25"
                    />
                  </label>
                  <label className="text-sm text-gray-700 block">
                    <span className="block mb-1 font-medium">Preuve d’acompte / justificatif</span>
                    <input
                      type="url"
                      value={projectForm.depositProofUrl}
                      onChange={(e) => setProjectForm({ ...projectForm, depositProofUrl: e.target.value })}
                      disabled={!canEditProject}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg disabled:bg-slate-100 disabled:text-slate-500"
                      placeholder="https://... / lien de paiement / preuve"
                    />
                  </label>
                  <div className="rounded-lg border px-3 py-2 text-sm text-gray-700 bg-white/60">
                    {Number(projectForm.depositPercent || 0) >= 25
                      ? '✅ Validation : acompte de 25% minimum confirmé.'
                      : '⚠️ Condition non remplie : acompte inférieur à 25%.'}
                  </div>
                </div>

                {projectForm.depositProofUrl && (
                  <div className="mt-3">
                    <a href={projectForm.depositProofUrl} target="_blank" rel="noreferrer" className="text-blue-700 underline underline-offset-2">Voir la preuve d’acompte</a>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="mt-6 grid grid-cols-1 xl:grid-cols-3 gap-4">
            <div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4 shadow-sm shadow-emerald-100/80">
              <p className="text-[11px] font-semibold uppercase tracking-[0.12em] text-emerald-700">Portfolio</p>
              <div className="mt-3 space-y-3">
                {portfolioMedia.length > 0 ? (
                  portfolioMedia.map((url: string) => renderMediaCard(url, 'Portfolio', true))
                ) : (
                  <div className="rounded-xl border border-dashed border-violet-200 bg-white/50 p-3 text-sm text-slate-600">
                    Aucun média de portfolio.
                  </div>
                )}
              </div>
              <div className="mt-4">
                <span className="block mb-1 font-medium text-sm text-gray-700">Ajouter plusieurs images / vidéos</span>
                <input
                  type="file"
                  accept="image/*,video/*"
                  multiple
                  onChange={async (e) => {
                    const files = Array.from(e.target.files || []);
                    if (files.length === 0) return;

                    try {
                      const uploadedUrls: string[] = [];

                      for (const file of files) {
                        const form = new FormData();
                        form.append('file', file);

                        const res = await fetch('/api/upload', { method: 'POST', body: form, credentials: 'include' });
                        const data = await res.json();
                        if (!res.ok) throw new Error(data.error || 'Upload impossible');
                        uploadedUrls.push(data.url);
                      }

                      setProjectForm((prev: any) => ({
                        ...prev,
                        portfolioMedia: [...parseMediaList(prev.portfolioMedia), ...uploadedUrls],
                      }));
                      alert(`${uploadedUrls.length} média${uploadedUrls.length > 1 ? 'x' : ''} ajouté${uploadedUrls.length > 1 ? 's' : ''} avec succès`);
                    } catch (error) {
                      alert('Erreur upload média : ' + (error as Error).message);
                    }
                  }}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white"
                />
              </div>
            </div>

            <div className="rounded-2xl border border-orange-200 bg-orange-50 p-4 xl:col-span-2 shadow-sm shadow-orange-100/80">
              <p className="text-[11px] font-semibold uppercase tracking-[0.12em] text-orange-700">Téléchargements du projet</p>
              <div className="mt-3 grid grid-cols-2 md:grid-cols-3 gap-3">
                {projectProgressMedia.length > 0 ? (
                  projectProgressMedia.map((url: string) => renderMediaCard(url, 'Média projet', true))
                ) : (
                  <div className="col-span-full rounded-xl border border-dashed border-orange-200 bg-white/50 p-3 text-sm text-slate-600">
                    Aucune image ou vidéo ajoutée pour ce projet.
                  </div>
                )}
              </div>
              <div className="mt-4">
                <span className="block mb-1 font-medium text-sm text-gray-700">Ajouter des médias de progression</span>
                <input
                  type="file"
                  accept="image/*,video/*"
                  multiple
                  onChange={(e) => void uploadProgressMedia(e.target.files)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white"
                />
              </div>
            </div>
          </div>

          <div className="mt-6 flex justify-end">
            <button
              onClick={updateProjectMeta}
              disabled={!canEditProject}
              className="px-4 py-2 bg-gray-900 text-white rounded-lg hover:bg-black transition text-sm disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Enregistrer les infos projet
            </button>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">
          <div className="flex items-center justify-between gap-3 flex-wrap mb-4">
            <h2 className="text-lg font-semibold">� Transfert de devis entre superviseurs</h2>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">
            <select
              value={projectForm.handoffStatus || 'none'}
              onChange={(e) => setProjectForm((prev: any) => ({ ...prev, handoffStatus: e.target.value }))}
              className="px-3 py-2 border border-gray-300 rounded-lg"
            >
              <option value="none">Aucun transfert</option>
              <option value="artisan-to-vendor">Devis technique prêt pour le superviseur vendeur</option>
              <option value="vendor-to-artisan">Retour vendeur / demande de compléments artisan</option>
              <option value="validated">Devis finalisé et validé</option>
            </select>

            <select
              value={projectForm.handoffTargetFamily || 'vendeur'}
              onChange={(e) => setProjectForm((prev: any) => ({ ...prev, handoffTargetFamily: e.target.value }))}
              className="px-3 py-2 border border-gray-300 rounded-lg"
            >
              <option value="vendeur">Superviseur vendeur</option>
              <option value="artisan">Superviseur artisan</option>
            </select>

            <input
              type="text"
              value={projectForm.handoffMessage || ''}
              onChange={(e) => setProjectForm((prev: any) => ({ ...prev, handoffMessage: e.target.value }))}
              placeholder="Message de transfert"
              className="px-3 py-2 border border-gray-300 rounded-lg"
            />
          </div>

          <div className="text-sm text-slate-600">
            {projectForm.handoffStatus === 'none' && 'Aucun transfert actif pour ce projet.'}
            {projectForm.handoffStatus === 'artisan-to-vendor' && 'Le devis technique est prêt et transmis au superviseur vendeur pour l’orientation commerciale.'}
            {projectForm.handoffStatus === 'vendor-to-artisan' && 'Le superviseur vendeur demande un complément ou une validation technique côté artisan.'}
            {projectForm.handoffStatus === 'validated' && 'Le devis est validé et le projet est prêt pour finalisation.'}
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">
          <div className="flex items-center justify-between gap-3 flex-wrap mb-4">
            <h2 className="text-lg font-semibold">�🔐 Partage du projet avec une équipe</h2>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">
            <select
              value={teamAccessForm.teamId}
              onChange={(e) => setTeamAccessForm((prev) => ({ ...prev, teamId: e.target.value }))}
              className="px-3 py-2 border border-gray-300 rounded-lg"
            >
              <option value="">Choisir une équipe</option>
              {availableTeams.map((team) => (
                <option key={team.id} value={team.id}>{team.name}</option>
              ))}
            </select>

            <select
              value={teamAccessForm.permission}
              onChange={(e) => setTeamAccessForm((prev) => ({ ...prev, permission: e.target.value }))}
              className="px-3 py-2 border border-gray-300 rounded-lg"
            >
              <option value="READ">Lecture</option>
              <option value="COMMENT">Commentaire</option>
              <option value="EDIT">Édition</option>
              <option value="VALIDATE">Validation</option>
            </select>

            <button
              type="button"
              onClick={handleShareWithTeam}
              disabled={!canManageProjectAccess}
              className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Partager le projet
            </button>
          </div>

          {teamAccesses.length === 0 ? (
            <div className="text-sm text-slate-500">Aucune équipe n’a encore accès à ce projet.</div>
          ) : (
            <div className="space-y-2">
              {teamAccesses.map((access) => (
                <div key={access.id} className="flex items-center justify-between gap-3 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-sm">
                  <div>
                    <span className="font-medium text-slate-800">{access.team?.name || 'Équipe'}</span>
                    <span className="ml-2 text-slate-500">({access.permission})</span>
                  </div>
                  <button
                    type="button"
                    onClick={() => handleRemoveTeamAccess(access.id)}
                    disabled={!canManageProjectAccess}
                    className="px-2 py-1 text-xs border border-red-200 text-red-700 rounded-md hover:bg-red-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Retirer
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">
          <div className="flex items-center justify-between gap-3 flex-wrap mb-4">
            <h2 className="text-lg font-semibold">🧭 Recommandations éditables</h2>
            <button
              onClick={addRecommendation}
              disabled={!canEditProject}
              className="px-3 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
            >
              + Ajouter une recommandation
            </button>
          </div>

          <div className="mb-6 rounded-xl border border-slate-200 bg-slate-50 p-4">
            <div className="flex items-center justify-between gap-3 mb-3">
              <h3 className="text-sm font-semibold text-slate-800">Validation IA / décision humaine</h3>
            </div>

            {projectRecommendations.length === 0 ? (
              <p className="text-sm text-slate-500">Aucune recommandation IA n’a encore été générée pour ce projet.</p>
            ) : (
              <div className="space-y-3">
                {projectRecommendations.map((item) => (
                  <div key={item.id} className="rounded-lg border border-slate-200 bg-white p-3">
                    <div className="flex flex-col gap-2 md:flex-row md:items-start md:justify-between">
                      <div>
                        <div className="text-sm font-semibold text-slate-800">{item.agent?.name || 'Agent IA'} · {item.category}</div>
                        <div className="mt-1 text-sm text-slate-600 whitespace-pre-wrap">{item.content}</div>
                      </div>
                      <span className={`inline-flex rounded-full px-2 py-1 text-xs font-medium ${
                        item.status === 'VALIDATED' ? 'bg-emerald-100 text-emerald-800' :
                        item.status === 'REJECTED' ? 'bg-red-100 text-red-800' :
                        item.status === 'MODIFIED' ? 'bg-amber-100 text-amber-800' :
                        'bg-slate-200 text-slate-700'
                      }`}>
                        {item.status || 'PENDING'}
                      </span>
                    </div>

                    <div className="mt-3 flex flex-wrap gap-2">
                      <button
                        type="button"
                        onClick={() => handleRecommendationValidation(item.id, 'VALIDATED', 'Recommandation validée par l’équipe.')}
                        disabled={!canValidateProject}
                        className="px-3 py-1.5 rounded-md bg-emerald-600 text-white text-xs font-medium hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        Valider
                      </button>
                      <button
                        type="button"
                        onClick={() => handleRecommendationValidation(item.id, 'REJECTED', 'Recommandation rejetée par l’équipe.')}
                        disabled={!canValidateProject}
                        className="px-3 py-1.5 rounded-md bg-red-600 text-white text-xs font-medium hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        Rejeter
                      </button>
                      <button
                        type="button"
                        onClick={() => handleRecommendationValidation(item.id, 'MODIFIED', 'Recommandation ajustée par l’équipe.')}
                        disabled={!canValidateProject}
                        className="px-3 py-1.5 rounded-md bg-amber-500 text-white text-xs font-medium hover:bg-amber-600 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        Modifier
                      </button>
                    </div>

                    {item.validationNote && (
                      <div className="mt-3 rounded-md bg-slate-100 px-2 py-1 text-xs text-slate-600">
                        Note de validation : {item.validationNote}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>

          {selectedRecommendation && (
            <div className="mb-4 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-sm text-emerald-800">
              Vendeur sélectionné : <strong>{selectedRecommendation.vendorName || 'À définir'}</strong>
              {selectedRecommendation.externalUrl ? (
                <>
                  <span className="mx-2">•</span>
                  <a href={selectedRecommendation.externalUrl} target="_blank" rel="noreferrer" className="underline font-medium">Ouvrir l’achat externe</a>
                </>
              ) : null}
            </div>
          )}

          <div className="space-y-4">
            {recommendations.map((item) => (
              <div
                key={item.id}
                className={`rounded-xl border p-4 ${item.selected ? 'border-blue-200 bg-blue-50' : 'border-gray-200 bg-white'}`}
              >
                <div className="flex items-center justify-between gap-3 mb-3">
                  <div className="font-medium text-gray-800">{item.productName || 'Produit recommandé'}</div>
                  <button
                    type="button"
                    onClick={() => setRecommendations((prev) => prev.map((r) => ({ ...r, selected: r.id === item.id }))) }
                    className={`px-2 py-1 text-xs rounded ${item.selected ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'}`}
                  >
                    {item.selected ? 'Sélectionné' : 'Choisir'}
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Produit</span>
                    <input
                      value={item.productName}
                      onChange={(e) => updateRecommendation(item.id, 'productName', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    />
                  </label>
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Marque</span>
                    <input
                      value={item.brand}
                      onChange={(e) => updateRecommendation(item.id, 'brand', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      placeholder="Ex. Roca, Hager, ..."
                    />
                  </label>
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Vendeur</span>
                    <input
                      value={item.vendorName}
                      onChange={(e) => updateRecommendation(item.id, 'vendorName', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      placeholder="Nom du vendeur"
                    />
                  </label>
                  <label className="text-sm text-gray-700">
                    <span className="block mb-1 font-medium">Prix unitaire</span>
                    <input
                      type="number"
                      step="0.01"
                      value={item.unitPrice}
                      onChange={(e) => updateRecommendation(item.id, 'unitPrice', Number(e.target.value || 0))}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    />
                  </label>
                  <label className="text-sm text-gray-700 md:col-span-2">
                    <span className="block mb-1 font-medium">URL d’achat externe</span>
                    <input
                      value={item.externalUrl}
                      onChange={(e) => updateRecommendation(item.id, 'externalUrl', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      placeholder="https://..."
                    />
                  </label>
                  <label className="text-sm text-gray-700 md:col-span-2">
                    <span className="block mb-1 font-medium">Notes / remarque</span>
                    <textarea
                      value={item.notes}
                      onChange={(e) => updateRecommendation(item.id, 'notes', e.target.value)}
                      rows={2}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      placeholder="Ex. produit compatible, meilleure finition, livraison 3 jours..."
                    />
                  </label>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Offres reçues */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">
          <h2 className="text-lg font-semibold mb-4">📨 Offres reçues pour ce projet</h2>
          {proposals.length === 0 ? (
            <p className="text-gray-500">Aucune offre reçue pour le moment.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Vendeur</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Produit</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Quantité</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Prix unitaire</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Total</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase">Statut</th>
                    <th className="px-4 py-3 text-xs font-medium text-gray-500 uppercase text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {proposals.map((p) => (
                    <tr key={p.id} className="border-b border-gray-100 hover:bg-gray-50">
                      <td className="px-4 py-3 text-sm">{p.vendor?.companyName || p.vendor?.name || "Inconnu"}</td>
                      <td className="px-4 py-3 text-sm">{p.product.name}</td>
                      <td className="px-4 py-3 text-sm">{p.quantity}</td>
                      <td className="px-4 py-3 text-sm">{p.unitPrice} €</td>
                      <td className="px-4 py-3 text-sm font-medium">{(p.quantity * p.unitPrice).toFixed(2)} €</td>
                      <td className="px-4 py-3 text-sm">
                        {p.status === "EN_ATTENTE" && <span className="bg-yellow-100 text-yellow-800 px-2 py-1 rounded text-xs">En attente</span>}
                        {p.status === "ACCEPTE" && <span className="bg-green-100 text-green-800 px-2 py-1 rounded text-xs">Acceptée</span>}
                        {p.status === "REFUSE" && <span className="bg-red-100 text-red-800 px-2 py-1 rounded text-xs">Refusée</span>}
                      </td>
                      <td className="px-4 py-3 text-sm text-right">
                        {p.status === "EN_ATTENTE" && (
                          <div className="flex gap-2 justify-end">
                            <button
                              onClick={() => handleAccept(p.id)}
                              disabled={actionLoading === p.id}
                              className="px-3 py-1 bg-green-600 text-white rounded hover:bg-green-700 text-xs flex items-center gap-1 disabled:opacity-50"
                            >
                              {actionLoading === p.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <CheckCircle className="w-3 h-3" />}
                              Accepter
                            </button>
                            <button
                              onClick={() => handleRefuse(p.id)}
                              disabled={actionLoading === p.id}
                              className="px-3 py-1 bg-red-600 text-white rounded hover:bg-red-700 text-xs flex items-center gap-1 disabled:opacity-50"
                            >
                              {actionLoading === p.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <XCircle className="w-3 h-3" />}
                              Refuser
                            </button>
                          </div>
                        )}
                        {p.status !== "EN_ATTENTE" && <span className="text-xs text-gray-400">Déjà traité</span>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Assistant IA */}
        <div className="bg-gradient-to-r from-purple-50 to-blue-50 rounded-xl shadow-sm border border-purple-200 p-6">
          <div className="flex justify-between items-center mb-4 gap-3 flex-wrap">
            <h2 className="text-lg font-semibold flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-purple-600" /> Assistant IA – Conseils pour ce projet
            </h2>
            <div className="flex gap-2 flex-wrap">
              <button
                onClick={handleAIAnalysis}
                disabled={aiLoading}
                className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition disabled:opacity-50 flex items-center gap-2 text-sm"
              >
                {aiLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                {aiLoading ? 'Analyse en cours...' : 'Analyser avec IA'}
              </button>
              <button
                onClick={handleArtisanAssistant}
                disabled={aiLoading}
                className="px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition disabled:opacity-50 flex items-center gap-2 text-sm"
              >
                {aiLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                {aiLoading ? 'Calcul...' : 'Assistant artisan'}
              </button>
            </div>
          </div>

          {aiAnalysis ? (
            <div className="bg-white rounded-lg p-4 border border-purple-100 whitespace-pre-wrap text-sm mb-4">
              {aiAnalysis}
            </div>
          ) : (
            <p className="text-gray-500 text-sm">
              Cliquez sur "Analyser avec IA" pour obtenir des recommandations personnalisées pour ce projet.
            </p>
          )}

          {assistantData && (
            <div className="space-y-6">
              <div className="grid md:grid-cols-3 gap-4">
                <div className="bg-white rounded-xl border border-emerald-200 p-4">
                  <p className="text-xs uppercase tracking-wide text-emerald-600 font-semibold">Estimations</p>
                  <p className="mt-2 text-2xl font-bold text-emerald-700">{assistantData.summary?.materials ?? 0}</p>
                  <p className="text-sm text-gray-600">matières calculées</p>
                </div>
                <div className="bg-white rounded-xl border border-blue-200 p-4">
                  <p className="text-xs uppercase tracking-wide text-blue-600 font-semibold">Étapes</p>
                  <p className="mt-2 text-2xl font-bold text-blue-700">{assistantData.summary?.steps ?? 0}</p>
                  <p className="text-sm text-gray-600">étapes de chantier</p>
                </div>
                <div className="bg-white rounded-xl border border-violet-200 p-4">
                  <p className="text-xs uppercase tracking-wide text-violet-600 font-semibold">Offres</p>
                  <p className="mt-2 text-2xl font-bold text-violet-700">{assistantData.summary?.offers ?? 0}</p>
                  <p className="text-sm text-gray-600">comparaisons générées</p>
                </div>
              </div>

              {assistantData.estimate && assistantData.estimate.length > 0 && (
                <div className="bg-white rounded-xl border border-emerald-100 p-4">
                  <h3 className="text-base font-semibold mb-3 text-gray-800">📦 Estimation matériaux</h3>
                  <div className="space-y-2">
                    {assistantData.estimate.map((item: any) => (
                      <div key={item.id} className="flex items-center justify-between border-b border-gray-100 pb-2 last:border-0 last:pb-0">
                        <div>
                          <p className="font-medium text-gray-800">{item.material}</p>
                          <p className="text-sm text-gray-500">{item.quantity} {item.unit}</p>
                        </div>
                        <p className="font-semibold text-emerald-700">{Number(item.totalPrice ?? 0).toFixed(2)} €</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {assistantData.steps && assistantData.steps.length > 0 && (
                <div className="bg-white rounded-xl border border-blue-100 p-4">
                  <h3 className="text-base font-semibold mb-3 text-gray-800">🗓️ Plan de chantier</h3>
                  <ol className="space-y-3">
                    {assistantData.steps.map((step: any) => (
                      <li key={step.id} className="flex gap-3 items-start">
                        <span className="inline-flex items-center justify-center w-7 h-7 rounded-full bg-blue-100 text-blue-700 text-xs font-bold">{step.order}</span>
                        <div>
                          <p className="font-medium text-gray-800">{step.title}</p>
                          {step.description && <p className="text-sm text-gray-600">{step.description}</p>}
                          {step.durationDays && <p className="text-xs text-gray-500 mt-1">Durée estimée : {step.durationDays} jour(s)</p>}
                        </div>
                      </li>
                    ))}
                  </ol>
                </div>
              )}

              {assistantData.comparisons && assistantData.comparisons.length > 0 && (
                <div className="bg-white rounded-xl border border-violet-100 p-4">
                  <h3 className="text-base font-semibold mb-3 text-gray-800">🏷️ Comparaison d’offres</h3>
                  <div className="grid gap-3">
                    {assistantData.comparisons.map((offer: any) => (
                      <div key={offer.id} className="border border-violet-100 rounded-lg p-3 bg-violet-50/40">
                        <div className="flex justify-between items-center gap-3">
                          <div>
                            <p className="font-medium text-gray-800">{offer.vendor?.companyName || offer.vendor?.name || 'Vendeur'}</p>
                            <p className="text-sm text-gray-600">{offer.deliveryDays ? `Livraison : ${offer.deliveryDays} jours` : 'Livraison : non précisée'}</p>
                          </div>
                          <div className="text-right">
                            <p className="font-bold text-violet-700">{Number(offer.totalPrice ?? 0).toFixed(2)} €</p>
                            <p className="text-xs text-gray-500">Score {offer.score ?? '—'}</p>
                          </div>
                        </div>
                        <p className="text-xs text-gray-600 mt-2 whitespace-pre-wrap">{offer.products}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, FormEvent, useMemo } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import { Search, X, Loader2 } from "lucide-react";
import Sidebar from "@/components/Sidebar";
import { getTradeRules, getWorkTypeLabel } from "@/lib/trade-rules";

type Product = {
  id: string;
  name: string;
  category: string;
  salePrice: number;
  stock: number;
};

const MARKET_REFERENCE_PRODUCTS: Product[] = [
  { id: 'market-ceramique-1', name: 'Carrelage céramique 60x60', category: 'Sol', salePrice: 24.5, stock: 999 },
  { id: 'market-colle-1', name: 'Colle à carrelage standard', category: 'Adjuvant', salePrice: 8.9, stock: 999 },
  { id: 'market-joint-1', name: 'Joint de carrelage blanc', category: 'Finition', salePrice: 6.2, stock: 999 },
  { id: 'market-primaire-1', name: 'Primaire d’accrochage', category: 'Préparation', salePrice: 11.4, stock: 999 },
  { id: 'market-mortier-1', name: 'Mortier de chape', category: 'Préparation', salePrice: 15.8, stock: 999 },
  { id: 'market-etancheite-1', name: 'Résine d’étanchéité', category: 'Étanchéité', salePrice: 18.9, stock: 999 },
];

type Service = {
  id: string;
  name: string;
  serviceCategory: string;
  unit: string;
  unitPrice: number;
  isActive: boolean;
};

type SelectedProduct = {
  id: string;
  name: string;
  quantity: number;
  unitPrice: number;
};

type Wall = {
  id: string;
  longueur: number;
  hauteur: number;
};

type ProjectItem = {
  productId?: string;
  serviceId?: string;
  quantity: number;
  unitPriceHtAtSale: number;
  tvaRate: number;
  name: string;
  type: "product" | "service";
  surface?: "sol" | "mur";
};

// Produits supplémentaires suggérés selon le type de chantier
const SUGGESTED_PRODUCTS = {
  refresh: [
    "Colle à carrelage",
    "Joint de carrelage",
    "Croisillons",
    "Primaire d'accrochage",
  ],
  renovation: [
    "Colle à carrelage",
    "Joint de carrelage",
    "Croisillons",
    "Primaire d'accrochage",
    "Mortier de chape",
    "Résine d'étanchéité",
    "Réglette de nivellement",
    "Disque de coupe (carrelage)",
  ],
};

const FALLBACK_SERVICE_PRICES = {
  refresh: { sol: 32, mur: 35 },
  renovation: { sol: 45, mur: 52 },
};

export default function NouveauProjetPage() {
  const router = useRouter();
  const { data: session } = useSession();
  const activeTrade = String(session?.user?.trade || "carreleur");
  const tradeRules = useMemo(() => getTradeRules(activeTrade), [activeTrade]);
  const projectTypeOptions = tradeRules.projectTypes;
  const workTypeOptions = tradeRules.workTypes;

  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [hasActiveSubscription, setHasActiveSubscription] = useState(true);

  const [formData, setFormData] = useState({
    name: "",
    description: "",
    type: "",
    workType: "",
    budgetEstimate: "",
  });

  // SOL
  const [solLongueur, setSolLongueur] = useState<number | "">("");
  const [solLargeur, setSolLargeur] = useState<number | "">("");
  const [surfaceSol, setSurfaceSol] = useState(0);
  const [solService, setSolService] = useState<Service | null>(null);
  const [solUnitPrice, setSolUnitPrice] = useState<number>(0);
  const [solProducts, setSolProducts] = useState<SelectedProduct[]>([]);
  const [solSearchTerm, setSolSearchTerm] = useState("");
  const [solSearchResults, setSolSearchResults] = useState<Product[]>([]);

  // MURS
  const [nbMurs, setNbMurs] = useState(0);
  const [walls, setWalls] = useState<Wall[]>([]);
  const [surfaceMurs, setSurfaceMurs] = useState(0);
  const [murService, setMurService] = useState<Service | null>(null);
  const [murUnitPrice, setMurUnitPrice] = useState<number>(0);
  const [murProducts, setMurProducts] = useState<SelectedProduct[]>([]);
  const [murSearchTerm, setMurSearchTerm] = useState("");
  const [murSearchResults, setMurSearchResults] = useState<Product[]>([]);

  const [services, setServices] = useState<Service[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [suggestedProducts, setSuggestedProducts] = useState<SelectedProduct[]>([]);

  // ===== Calcul des surfaces =====
  useEffect(() => {
    if (solLongueur && solLargeur) {
      setSurfaceSol(solLongueur * solLargeur);
    } else {
      setSurfaceSol(0);
    }
  }, [solLongueur, solLargeur]);

  useEffect(() => {
    const total = walls.reduce((acc, w) => acc + w.longueur * w.hauteur, 0);
    setSurfaceMurs(total);
  }, [walls]);

  // ===== Gestion des murs =====
  useEffect(() => {
    if (nbMurs > 0) {
      setWalls(
        Array.from({ length: nbMurs }, (_, i) => ({
          id: `mur-${i + 1}`,
          longueur: 0,
          hauteur: 0,
        }))
      );
    } else {
      setWalls([]);
    }
  }, [nbMurs]);

  const updateWall = (index: number, field: "longueur" | "hauteur", value: number) => {
    const newWalls = [...walls];
    newWalls[index][field] = value;
    setWalls(newWalls);
  };

  // ===== Chargement des données =====
  useEffect(() => {
    if (!session) {
      router.push('/auth/signin');
      return;
    }

    if (session.user.role !== 'artisan' && session.user.trade !== 'artisan') {
      router.push('/auth/signin');
      return;
    }

    const ensureAccess = async () => {
      try {
        const res = await fetch('/api/user/agents/check', { credentials: 'include' });
        const data = await res.json();
        setHasActiveSubscription(Boolean(res.ok && data?.hasActive));
      } catch {
        setHasActiveSubscription(false);
      }

      try {
        const [resProducts, resServices] = await Promise.all([
          fetch("/api/seller/products", { credentials: "include" }),
          fetch("/api/services", { credentials: "include" }),
        ]);

        const marketProducts = resProducts.ok ? await resProducts.json() : [];
        setAllProducts((marketProducts && marketProducts.length > 0) ? marketProducts : MARKET_REFERENCE_PRODUCTS);

        if (resServices.ok) {
          const data = await resServices.json();
          const activeServices = data.filter((s: Service) => s.isActive);
          setServices(activeServices);
        }
      } catch (error) {
        console.error("Erreur chargement:", error);
        setAllProducts(MARKET_REFERENCE_PRODUCTS);
      }
    };

    void ensureAccess();
  }, [session, router]);

  // ===== Mise à jour des services sol/mur en fonction du workType =====
  useEffect(() => {
    if (!formData.workType) {
      setSolService(null);
      setMurService(null);
      setSolUnitPrice(0);
      setMurUnitPrice(0);
      return;
    }

    const normalize = (value: string | null | undefined) =>
      (value ?? "")
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9]+/g, " ")
        .trim();

    const workTypeLabel = getWorkTypeLabel(activeTrade, formData.workType);
    const normalizedWorkTypeLabel = normalize(workTypeLabel);
    const preset = formData.workType === "renovation" ? "renovation" : "refresh";
    const baseKeywords =
      preset === "refresh"
        ? ["rafraichissement", "refresh", "relooking", "support existant", "pose sur support", "reprise", "retouche"]
        : ["renovation", "complete", "complet", "demolition", "preparation", "preparatif", "refection"];
    const workKeywords = Array.from(new Set([
      ...normalizedWorkTypeLabel.split(" ").filter((word) => word.length > 2),
      ...baseKeywords,
    ]));

    const pickServiceForSurface = (surface: "sol" | "mur") => {
      const targetWords =
        surface === "sol"
          ? ["sol", "plancher", "carrelage", "pose sol", "pose de carrelage sol", "carrelage sol"]
          : ["mur", "murs", "paroi", "faience", "pose mur", "pose de carrelage mur", "carrelage mur"];

      const candidates = services.filter((s) => s.isActive);

      const exactRegExp = surface === "sol" ? /(sol|plancher|carrelage)/i : /(mur|murs|paroi|faience)/i;
      const sameSurfaceCandidates = candidates.filter((s) => {
        const haystack = normalize(`${s.serviceCategory} ${s.name}`);
        return targetWords.some((word) => haystack.includes(word)) || exactRegExp.test(s.serviceCategory + ' ' + s.name);
      });

      const workSpecific = sameSurfaceCandidates.find((s) => {
        const haystack = normalize(`${s.serviceCategory} ${s.name}`);
        return workKeywords.some((word) => haystack.includes(word));
      });

      if (workSpecific) return workSpecific;

      const generic = sameSurfaceCandidates.find((s) => {
        const haystack = normalize(`${s.serviceCategory} ${s.name}`);
        return ["pose", "carrelage", "prestation", "travail"].some((word) => haystack.includes(word));
      });

      if (surface === "sol" && surfaceSol === 0) return null;
      if (surface === "mur" && surfaceMurs === 0) return null;

      return generic ?? sameSurfaceCandidates[0] ?? null;
    };

    const fallbackService = (surface: "sol" | "mur") => ({
      id: `fallback-${surface}`,
      name: surface === "sol" ? "Pose de carrelage sol" : "Pose de carrelage mur",
      serviceCategory: surface === "sol" ? "sol" : "mur",
      unit: "m²",
      unitPrice: FALLBACK_SERVICE_PRICES[preset][surface],
      isActive: true,
    });

    const sol = pickServiceForSurface("sol") ?? (surfaceSol > 0 ? fallbackService("sol") : null);
    if (sol) {
      setSolService(sol as Service);
      setSolUnitPrice(sol.unitPrice);
    } else {
      setSolService(null);
      setSolUnitPrice(0);
    }

    const mur = pickServiceForSurface("mur") ?? (surfaceMurs > 0 ? fallbackService("mur") : null);
    if (mur) {
      setMurService(mur as Service);
      setMurUnitPrice(mur.unitPrice);
    } else {
      setMurService(null);
      setMurUnitPrice(0);
    }
  }, [activeTrade, formData.workType, services, surfaceSol, surfaceMurs]);

  // ===== Produits suggérés =====
  useEffect(() => {
    if (!formData.workType) {
      setSuggestedProducts([]);
      return;
    }

    const preset = formData.workType === "renovation" ? "renovation" : "refresh";
    const suggestions = SUGGESTED_PRODUCTS[preset] || [];
    const foundProducts: SelectedProduct[] = [];

    suggestions.forEach((name) => {
      const product =
        allProducts.find((p) => p.name.toLowerCase().includes(name.toLowerCase())) ||
        MARKET_REFERENCE_PRODUCTS.find((p) => p.name.toLowerCase().includes(name.toLowerCase()));

      if (product) {
        foundProducts.push({
          id: product.id,
          name: product.name,
          quantity: 1,
          unitPrice: product.salePrice,
        });
      }
    });

    setSuggestedProducts(foundProducts.length > 0 ? foundProducts : MARKET_REFERENCE_PRODUCTS.slice(0, 4).map((product) => ({
      id: product.id,
      name: product.name,
      quantity: 1,
      unitPrice: product.salePrice,
    })));
  }, [formData.workType, allProducts]);

  // ===== Recherche de produits (sol) =====
  useEffect(() => {
    if (solSearchTerm.trim() === "") {
      setSolSearchResults([]);
      return;
    }
    const filtered = allProducts.filter(
      (p) =>
        p.name.toLowerCase().includes(solSearchTerm.toLowerCase()) &&
        !solProducts.some((sp) => sp.id === p.id)
    );
    setSolSearchResults(filtered);
  }, [solSearchTerm, allProducts, solProducts]);

  // ===== Recherche de produits (mur) =====
  useEffect(() => {
    if (murSearchTerm.trim() === "") {
      setMurSearchResults([]);
      return;
    }
    const filtered = allProducts.filter(
      (p) =>
        p.name.toLowerCase().includes(murSearchTerm.toLowerCase()) &&
        !murProducts.some((sp) => sp.id === p.id)
    );
    setMurSearchResults(filtered);
  }, [murSearchTerm, allProducts, murProducts]);

  // ===== Gestion des produits (sol) =====
  const addSolProduct = (product: Product) => {
    setSolProducts([
      ...solProducts,
      {
        id: product.id,
        name: product.name,
        quantity: surfaceSol > 0 ? surfaceSol : 1,
        unitPrice: product.salePrice,
      },
    ]);
    setSolSearchTerm("");
    setSolSearchResults([]);
  };

  const removeSolProduct = (id: string) => {
    setSolProducts(solProducts.filter((p) => p.id !== id));
  };

  const updateSolProductQuantity = (id: string, quantity: number) => {
    setSolProducts(
      solProducts.map((p) =>
        p.id === id ? { ...p, quantity: Math.max(0, quantity) } : p
      )
    );
  };

  const updateSolProductUnitPrice = (id: string, unitPrice: number) => {
    setSolProducts(
      solProducts.map((p) =>
        p.id === id ? { ...p, unitPrice: Math.max(0, unitPrice) } : p
      )
    );
  };

  // ===== Gestion des produits (mur) =====
  const addMurProduct = (product: Product) => {
    setMurProducts([
      ...murProducts,
      {
        id: product.id,
        name: product.name,
        quantity: surfaceMurs > 0 ? surfaceMurs : 1,
        unitPrice: product.salePrice,
      },
    ]);
    setMurSearchTerm("");
    setMurSearchResults([]);
  };

  const removeMurProduct = (id: string) => {
    setMurProducts(murProducts.filter((p) => p.id !== id));
  };

  const updateMurProductQuantity = (id: string, quantity: number) => {
    setMurProducts(
      murProducts.map((p) =>
        p.id === id ? { ...p, quantity: Math.max(0, quantity) } : p
      )
    );
  };

  const updateMurProductUnitPrice = (id: string, unitPrice: number) => {
    setMurProducts(
      murProducts.map((p) =>
        p.id === id ? { ...p, unitPrice: Math.max(0, unitPrice) } : p
      )
    );
  };

  // ===== Gestion des produits suggérés =====
  const removeSuggestedProduct = (id: string) => {
    setSuggestedProducts(suggestedProducts.filter((p) => p.id !== id));
  };

  const updateSuggestedProductQuantity = (id: string, quantity: number) => {
    setSuggestedProducts(
      suggestedProducts.map((p) =>
        p.id === id ? { ...p, quantity: Math.max(0, quantity) } : p
      )
    );
  };

  // ===== Construction des items du projet =====
  const buildItems = (): ProjectItem[] => {
    const items: ProjectItem[] = [];

    const effectiveSuggestedProducts = suggestedProducts.length > 0
      ? suggestedProducts
      : (formData.workType ? MARKET_REFERENCE_PRODUCTS.slice(0, 4).map((product) => ({
          id: product.id,
          name: product.name,
          quantity: 1,
          unitPrice: product.salePrice,
        })) : []);

    // Produits du sol
    solProducts.forEach((p) => {
      items.push({
        productId: p.id,
        quantity: p.quantity,
        unitPriceHtAtSale: p.unitPrice / 1.2,
        tvaRate: 20,
        name: p.name,
        type: "product",
        surface: "sol",
      });
    });

    // Produits des murs
    murProducts.forEach((p) => {
      items.push({
        productId: p.id,
        quantity: p.quantity,
        unitPriceHtAtSale: p.unitPrice / 1.2,
        tvaRate: 20,
        name: p.name,
        type: "product",
        surface: "mur",
      });
    });

    // Produits suggérés
    effectiveSuggestedProducts.forEach((p) => {
      items.push({
        productId: p.id,
        quantity: p.quantity,
        unitPriceHtAtSale: p.unitPrice / 1.2,
        tvaRate: 20,
        name: p.name,
        type: "product",
      });
    });

    // Service Sol
    const effectiveSolService = solService || (surfaceSol > 0 && formData.workType ? {
      id: `fallback-sol`,
      name: 'Pose de carrelage sol',
      unitPrice: FALLBACK_SERVICE_PRICES[formData.workType === "renovation" ? "renovation" : "refresh"]?.sol ?? 32,
    } : null);

    if (surfaceSol > 0 && effectiveSolService) {
      items.push({
        serviceId: effectiveSolService.id,
        quantity: surfaceSol,
        unitPriceHtAtSale: (solUnitPrice || effectiveSolService.unitPrice) / 1.2,
        tvaRate: 20,
        name: `${effectiveSolService.name} (sol)`,
        type: "service",
      });
    }

    // Service Mur
    const effectiveMurService = murService || (surfaceMurs > 0 && formData.workType ? {
      id: `fallback-mur`,
      name: 'Pose de carrelage mur',
      unitPrice: FALLBACK_SERVICE_PRICES[formData.workType === "renovation" ? "renovation" : "refresh"]?.mur ?? 35,
    } : null);

    if (surfaceMurs > 0 && effectiveMurService) {
      items.push({
        serviceId: effectiveMurService.id,
        quantity: surfaceMurs,
        unitPriceHtAtSale: (murUnitPrice || effectiveMurService.unitPrice) / 1.2,
        tvaRate: 20,
        name: `${effectiveMurService.name} (murs)`,
        type: "service",
      });
    }

    return items;
  };

  // ===== SOUMISSION =====
  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    if (!hasActiveSubscription) {
      alert('Vous devez souscrire à un agent actif pour créer un projet.');
      router.push('/abonnement');
      return;
    }

    if (!formData.name.trim()) {
      alert("Veuillez donner un nom au projet.");
      return;
    }

    const directSurfaceSol = solLongueur && solLargeur ? Number(solLongueur) * Number(solLargeur) : surfaceSol;
    const directSurfaceMurs = walls.reduce((acc, wall) => acc + Number(wall.longueur || 0) * Number(wall.hauteur || 0), 0) || surfaceMurs;

    const items = buildItems();
    const hasFallbackContent = directSurfaceSol > 0 || directSurfaceMurs > 0 || solProducts.length > 0 || murProducts.length > 0 || suggestedProducts.length > 0;

    if (items.length === 0 && !hasFallbackContent) {
      alert("Veuillez ajouter au moins un produit ou une prestation (sol ou murs).");
      return;
    }

    setSubmitting(true);
    try {
      const apiItems = items.map((item) => ({
        productId: item.productId,
        serviceId: item.serviceId,
        name: item.name,
        quantity: item.quantity,
        unitPriceHtAtSale: item.unitPriceHtAtSale,
        tvaRate: item.tvaRate,
      }));

      const res = await fetch("/api/projects", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          name: formData.name,
          description: formData.description || null,
          type: formData.type || null,
          workType: formData.workType || null,
          surface: surfaceSol + surfaceMurs,
          budgetEstimate: formData.budgetEstimate ? parseFloat(formData.budgetEstimate) : null,
          items: apiItems,
          solDetails: {
            longueur: solLongueur || 0,
            largeur: solLargeur || 0,
            surface: surfaceSol,
          },
          murDetails: {
            nbMurs,
            walls: walls.map((w) => ({ longueur: w.longueur, hauteur: w.hauteur })),
            surface: surfaceMurs,
          },
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Erreur");
      }
      const data = await res.json();
      alert(`✅ Projet "${formData.name}" créé avec succès !`);
      router.push("/artisan");
    } catch (error) {
      console.error("Erreur création projet:", error);
      alert("Erreur lors de la création du projet : " + (error as Error).message);
    } finally {
      setSubmitting(false);
    }
  };

  const projectItems = buildItems();

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar />
      <div className="flex-1 ml-64 p-8">
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 max-w-4xl mx-auto">
          <h1 className="text-2xl font-bold text-gray-800 mb-6">📋 Nouveau projet</h1>

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Informations générales */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Nom du projet *</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Type de projet</label>
                <select
                  value={formData.type}
                  onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">Sélectionner un type...</option>
                  {projectTypeOptions.map((type) => (
                    <option key={type} value={type}>{type}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Type de chantier *</label>
                <select
                  value={formData.workType}
                  onChange={(e) => setFormData({ ...formData, workType: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                  required
                >
                  <option value="">Sélectionner...</option>
                  {workTypeOptions.map((wt) => (
                    <option key={wt.value} value={wt.value}>{wt.label}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Budget estimé (€)</label>
                <input
                  type="number"
                  step="0.01"
                  placeholder="ex: 5000"
                  value={formData.budgetEstimate}
                  onChange={(e) => setFormData({ ...formData, budgetEstimate: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                <textarea
                  rows={2}
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            {/* SECTION SOL */}
            <div className="border rounded-lg p-4 bg-blue-50">
              <h3 className="text-lg font-semibold text-gray-800 mb-3">🟦 Sol</h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Longueur (m)</label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={solLongueur}
                    onChange={(e) => setSolLongueur(e.target.value === "" ? "" : parseFloat(e.target.value))}
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Largeur (m)</label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={solLargeur}
                    onChange={(e) => setSolLargeur(e.target.value === "" ? "" : parseFloat(e.target.value))}
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Surface (m²)</label>
                  <input
                    type="text"
                    value={surfaceSol ? surfaceSol.toFixed(2) : "0.00"}
                    readOnly
                    className="w-full px-4 py-2 border bg-gray-100 rounded-lg text-gray-700"
                  />
                </div>
              </div>

              {/* Affichage de la prestation sol (sélectionnée selon workType) */}
              {surfaceSol > 0 && solService && (
                <div className="mt-3 p-3 bg-white rounded-lg border border-blue-200">
                  <div className="flex items-center gap-4 flex-wrap">
                    <span className="font-medium text-sm">✅ Prestation sol :</span>
                    <span className="text-sm">{solService.name}</span>
                    <span className="text-sm text-gray-500">{surfaceSol.toFixed(2)} m²</span>
                    <div className="flex items-center gap-2">
                      <label className="text-sm text-gray-600">Prix / m² :</label>
                      <input
                        type="number"
                        step="0.01"
                        min="0"
                        value={solUnitPrice}
                        onChange={(e) => setSolUnitPrice(parseFloat(e.target.value) || 0)}
                        className="w-24 px-2 py-1 border rounded text-sm"
                      />
                      <span className="text-sm text-gray-500">€</span>
                    </div>
                    <span className="text-sm font-medium text-green-600">
                      Total : {(surfaceSol * solUnitPrice).toFixed(2)} €
                    </span>
                  </div>
                </div>
              )}
              {surfaceSol > 0 && !solService && (
                <p className="text-xs text-amber-600 mt-2">
                  ⚠️ Aucune prestation trouvée pour le sol avec ce type de chantier. Vérifiez vos paramètres.
                </p>
              )}

              {/* Produits pour le sol */}
              <div className="mt-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">Produits pour le sol</label>
                <div className="flex gap-2 mb-2">
                  <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                    <input
                      type="text"
                      placeholder="Rechercher un produit pour le sol..."
                      value={solSearchTerm}
                      onChange={(e) => setSolSearchTerm(e.target.value)}
                      className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                </div>
                {solSearchResults.length > 0 && (
                  <ul className="border border-gray-200 rounded-lg divide-y max-h-40 overflow-y-auto">
                    {solSearchResults.map((p) => (
                      <li
                        key={p.id}
                        className="px-4 py-2 hover:bg-gray-50 cursor-pointer flex justify-between items-center"
                        onClick={() => addSolProduct(p)}
                      >
                        <span>{p.name}</span>
                        <span className="text-sm text-gray-500">{p.salePrice} €</span>
                      </li>
                    ))}
                  </ul>
                )}
                {solProducts.length > 0 && (
                  <div className="mt-2 overflow-x-auto">
                    <table className="w-full text-left">
                      <thead className="bg-gray-50 border-b border-gray-200">
                        <tr>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Produit</th>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Quantité</th>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Prix unitaire</th>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Total</th>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {solProducts.map((p) => (
                          <tr key={p.id} className="border-b border-gray-100">
                            <td className="px-4 py-1 text-sm">{p.name}</td>
                            <td className="px-4 py-1">
                              <input
                                type="number"
                                min="0"
                                step="1"
                                value={p.quantity}
                                onChange={(e) => updateSolProductQuantity(p.id, parseFloat(e.target.value) || 0)}
                                className="w-16 px-1 py-0.5 border rounded text-sm"
                              />
                            </td>
                            <td className="px-4 py-1">
                              <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={p.unitPrice}
                                onChange={(e) => updateSolProductUnitPrice(p.id, parseFloat(e.target.value) || 0)}
                                className="w-24 px-1 py-0.5 border rounded text-sm"
                              />
                            </td>
                            <td className="px-4 py-1 text-sm font-medium">
                              {(p.quantity * p.unitPrice).toFixed(2)} €
                            </td>
                            <td className="px-4 py-1">
                              <button
                                type="button"
                                onClick={() => removeSolProduct(p.id)}
                                className="text-red-600 hover:text-red-800"
                              >
                                <X className="w-4 h-4" />
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </div>

            {/* SECTION MURS */}
            <div className="border rounded-lg p-4 bg-green-50">
              <h3 className="text-lg font-semibold text-gray-800 mb-3">🧱 Murs</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Nombre de murs</label>
                  <select
                    value={nbMurs}
                    onChange={(e) => setNbMurs(parseInt(e.target.value))}
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                  >
                    <option value={0}>0</option>
                    <option value={1}>1</option>
                    <option value={2}>2</option>
                    <option value={3}>3</option>
                    <option value={4}>4</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Surface totale des murs (m²)</label>
                  <input
                    type="text"
                    value={surfaceMurs ? surfaceMurs.toFixed(2) : "0.00"}
                    readOnly
                    className="w-full px-4 py-2 border bg-gray-100 rounded-lg text-gray-700"
                  />
                </div>
              </div>

              {walls.length > 0 && (
                <div className="mt-4 overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-gray-50 border-b border-gray-200">
                      <tr>
                        <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Mur</th>
                        <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Longueur (m)</th>
                        <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Hauteur (m)</th>
                        <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Surface (m²)</th>
                      </tr>
                    </thead>
                    <tbody>
                      {walls.map((wall, index) => {
                        const surface = wall.longueur * wall.hauteur;
                        return (
                          <tr key={wall.id} className="border-b border-gray-100">
                            <td className="px-4 py-2 text-sm font-medium">Mur {index + 1}</td>
                            <td className="px-4 py-2">
                              <input
                                type="number"
                                step="0.01"
                                min="0"
                                value={wall.longueur || ""}
                                onChange={(e) => updateWall(index, "longueur", parseFloat(e.target.value) || 0)}
                                className="w-24 px-2 py-1 border rounded text-sm"
                              />
                            </td>
                            <td className="px-4 py-2">
                              <input
                                type="number"
                                step="0.01"
                                min="0"
                                value={wall.hauteur || ""}
                                onChange={(e) => updateWall(index, "hauteur", parseFloat(e.target.value) || 0)}
                                className="w-24 px-2 py-1 border rounded text-sm"
                              />
                            </td>
                            <td className="px-4 py-2 text-sm">{surface ? surface.toFixed(2) : "0.00"}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}

              {/* Affichage de la prestation mur (sélectionnée selon workType) */}
              {surfaceMurs > 0 && murService && (
                <div className="mt-3 p-3 bg-white rounded-lg border border-green-200">
                  <div className="flex items-center gap-4 flex-wrap">
                    <span className="font-medium text-sm">✅ Prestation murs :</span>
                    <span className="text-sm">{murService.name}</span>
                    <span className="text-sm text-gray-500">{surfaceMurs.toFixed(2)} m²</span>
                    <div className="flex items-center gap-2">
                      <label className="text-sm text-gray-600">Prix / m² :</label>
                      <input
                        type="number"
                        step="0.01"
                        min="0"
                        value={murUnitPrice}
                        onChange={(e) => setMurUnitPrice(parseFloat(e.target.value) || 0)}
                        className="w-24 px-2 py-1 border rounded text-sm"
                      />
                      <span className="text-sm text-gray-500">€</span>
                    </div>
                    <span className="text-sm font-medium text-green-600">
                      Total : {(surfaceMurs * murUnitPrice).toFixed(2)} €
                    </span>
                  </div>
                </div>
              )}
              {surfaceMurs > 0 && !murService && (
                <p className="text-xs text-amber-600 mt-2">
                  ⚠️ Aucune prestation trouvée pour les murs avec ce type de chantier. Vérifiez vos paramètres.
                </p>
              )}

              {/* Produits pour les murs */}
              <div className="mt-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">Produits pour les murs</label>
                <div className="flex gap-2 mb-2">
                  <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                    <input
                      type="text"
                      placeholder="Rechercher un produit pour les murs..."
                      value={murSearchTerm}
                      onChange={(e) => setMurSearchTerm(e.target.value)}
                      className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                    />
                  </div>
                </div>
                {murSearchResults.length > 0 && (
                  <ul className="border border-gray-200 rounded-lg divide-y max-h-40 overflow-y-auto">
                    {murSearchResults.map((p) => (
                      <li
                        key={p.id}
                        className="px-4 py-2 hover:bg-gray-50 cursor-pointer flex justify-between items-center"
                        onClick={() => addMurProduct(p)}
                      >
                        <span>{p.name}</span>
                        <span className="text-sm text-gray-500">{p.salePrice} €</span>
                      </li>
                    ))}
                  </ul>
                )}
                {murProducts.length > 0 && (
                  <div className="mt-2 overflow-x-auto">
                    <table className="w-full text-left">
                      <thead className="bg-gray-50 border-b border-gray-200">
                        <tr>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Produit</th>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Quantité</th>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Prix unitaire</th>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Total</th>
                          <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {murProducts.map((p) => (
                          <tr key={p.id} className="border-b border-gray-100">
                            <td className="px-4 py-1 text-sm">{p.name}</td>
                            <td className="px-4 py-1">
                              <input
                                type="number"
                                min="0"
                                step="1"
                                value={p.quantity}
                                onChange={(e) => updateMurProductQuantity(p.id, parseFloat(e.target.value) || 0)}
                                className="w-16 px-1 py-0.5 border rounded text-sm"
                              />
                            </td>
                            <td className="px-4 py-1">
                              <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={p.unitPrice}
                                onChange={(e) => updateMurProductUnitPrice(p.id, parseFloat(e.target.value) || 0)}
                                className="w-24 px-1 py-0.5 border rounded text-sm"
                              />
                            </td>
                            <td className="px-4 py-1 text-sm font-medium">
                              {(p.quantity * p.unitPrice).toFixed(2)} €
                            </td>
                            <td className="px-4 py-1">
                              <button
                                type="button"
                                onClick={() => removeMurProduct(p.id)}
                                className="text-red-600 hover:text-red-800"
                              >
                                <X className="w-4 h-4" />
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </div>

            {/* PRODUITS SUGGÉRÉS */}
            {suggestedProducts.length > 0 && (
              <div className="border rounded-lg p-4 bg-yellow-50 border-yellow-200">
                <h3 className="text-lg font-semibold text-gray-800 mb-3">
                  💡 Produits suggérés pour {formData.workType === "refresh" ? "un rafraîchissement" : "une rénovation"}
                </h3>
                <p className="text-sm text-gray-600 mb-3">
                  Ces produits sont généralement nécessaires pour ce type de chantier. Vous pouvez les ajuster ou les supprimer.
                </p>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-gray-50 border-b border-gray-200">
                      <tr>
                        <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Produit</th>
                        <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Quantité</th>
                        <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Prix unitaire</th>
                        <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Total</th>
                        <th className="px-4 py-1 text-xs font-medium text-gray-500 uppercase">Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {suggestedProducts.map((p) => (
                        <tr key={p.id} className="border-b border-gray-100">
                          <td className="px-4 py-1 text-sm">{p.name}</td>
                          <td className="px-4 py-1">
                            <input
                              type="number"
                              min="0"
                              step="1"
                              value={p.quantity}
                              onChange={(e) => updateSuggestedProductQuantity(p.id, parseFloat(e.target.value) || 0)}
                              className="w-16 px-1 py-0.5 border rounded text-sm"
                            />
                          </td>
                          <td className="px-4 py-1">{p.unitPrice} €</td>
                          <td className="px-4 py-1 text-sm font-medium">
                            {(p.quantity * p.unitPrice).toFixed(2)} €
                          </td>
                          <td className="px-4 py-1">
                            <button
                              type="button"
                              onClick={() => removeSuggestedProduct(p.id)}
                              className="text-red-600 hover:text-red-800"
                            >
                              <X className="w-4 h-4" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* PRÉVISUALISATION DES ITEMS DU PROJET */}
            {projectItems.length > 0 && (
              <div className="border rounded-lg overflow-hidden">
                <table className="w-full text-left">
                  <thead className="bg-gray-50 border-b border-gray-200">
                    <tr>
                      <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Type</th>
                      <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Nom</th>
                      <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Surface</th>
                      <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Quantité</th>
                      <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Prix HT</th>
                      <th className="px-4 py-2 text-xs font-medium text-gray-500 uppercase">Total HT</th>
                    </tr>
                  </thead>
                  <tbody>
                    {projectItems.map((item, index) => {
                      const totalHT = item.quantity * item.unitPriceHtAtSale;
                      return (
                        <tr key={index} className="border-b border-gray-100">
                          <td className="px-4 py-2 text-sm">
                            {item.type === "product" ? "📦 Produit" : "🔧 Prestation"}
                          </td>
                          <td className="px-4 py-2 text-sm">{item.name}</td>
                          <td className="px-4 py-2 text-sm">
                            {item.surface === "sol" ? "Sol" : item.surface === "mur" ? "Mur" : "-"}
                          </td>
                          <td className="px-4 py-2 text-sm">{item.quantity.toFixed(2)}</td>
                          <td className="px-4 py-2 text-sm">{item.unitPriceHtAtSale.toFixed(2)} €</td>
                          <td className="px-4 py-2 text-sm font-medium">{totalHT.toFixed(2)} €</td>
                        </tr>
                      );
                    })}
                  </tbody>
                  <tfoot className="bg-gray-50 border-t border-gray-200">
                    <tr>
                      <td colSpan={5} className="px-4 py-2 text-right font-semibold">Total HT</td>
                      <td className="px-4 py-2 font-semibold">
                        {projectItems.reduce((acc, i) => acc + i.quantity * i.unitPriceHtAtSale, 0).toFixed(2)} €
                      </td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            )}

            {/* Boutons */}
            <div className="flex gap-3 pt-4 border-t border-gray-200">
              <button
                type="button"
                onClick={() => router.push("/artisan")}
                className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Annuler
              </button>
              <button
                type="submit"
                disabled={submitting}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition disabled:opacity-50 flex items-center gap-2"
              >
                {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : hasActiveSubscription ? 'Créer le projet' : 'Souscrire un agent pour créer'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

'use client';

import Link from 'next/link';
import { useEffect, useMemo, useState } from 'react';
import ProjectRequestForm from '@/app/client/[id]/ProjectRequestForm';

const specialtyOptions = {
  artisan: [
    ['carreleur', 'Carreleur'], ['plombier', 'Plombier'], ['electricien', 'Électricien'],
    ['peintre', 'Peintre'], ['menuisier', 'Menuisier'], ['maçon', 'Maçon'],
    ['couvreur', 'Couvreur'], ['terrassier', 'Terrassier'], ['renovation', 'Rénovation'],
  ],
  vendeur: [
    ['materiaux', 'Matériaux de construction'], ['sanitaire', 'Sanitaire'], ['quincaillerie', 'Quincaillerie'],
    ['menuiserie', 'Menuiserie'], ['isolation', 'Isolation'], ['outillage', 'Outillage'], ['decoration', 'Décoration'],
  ],
  promoteur: [
    ['promotion-immobiliere', 'Promotion immobilière'], ['gestion-chantier', 'Gestion de chantier'],
    ['maitrise-oeuvre', 'Maîtrise d’œuvre'], ['coordination-travaux', 'Coordination travaux'], ['amenagement', 'Aménagement'],
  ],
} as const;

type Professional = {
  id: string;
  name: string;
  companyName: string | null;
  city: string | null;
  trade: string | null;
  certificationScore: number | null;
};

const dynamicFields: Record<string, string[]> = {
  carreleur: ['Surface à carreler (m²)', 'Type de travaux', 'Photos du chantier'],
  electricien: ['Type d’intervention', 'Éléments concernés', 'Photos ou plans'],
  plombier: ['Type d’intervention', 'Équipement concerné', 'Niveau d’urgence'],
  peintre: ['Surface à peindre (m²)', 'Zone concernée', 'État du support'],
  menuisier: ['Équipement concerné', 'Type de travaux', 'Dimensions'],
};

export default function ProfessionalRequestFlow({ category, title }: { category: string; title: string }) {
  const options = specialtyOptions[category as keyof typeof specialtyOptions] ?? [];
  const [trade, setTrade] = useState(options[0]?.[0] ?? '');
  const [professionals, setProfessionals] = useState<Professional[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const fields = useMemo(() => dynamicFields[trade] ?? ['Description détaillée du besoin', 'Budget estimatif', 'Photos ou documents'], [trade]);
  const selectedTradeLabel = (options as readonly (readonly [string, string])[]).find(([value]) => value === trade)?.[1] || trade;

  useEffect(() => {
    const loadProfessionals = async () => {
      setLoading(true);
      setError('');
      try {
        const response = await fetch(`/api/public/professionals?role=${category}&trade=${encodeURIComponent(trade)}`);
        const data = await response.json();
        if (!response.ok) throw new Error(data.error || 'Impossible de charger les professionnels.');
        setProfessionals(Array.isArray(data) ? data : []);
      } catch (loadError) {
        setError(loadError instanceof Error ? loadError.message : 'Erreur de chargement.');
        setProfessionals([]);
      } finally {
        setLoading(false);
      }
    };

    if (trade) void loadProfessionals();
  }, [category, trade]);

  return (
    <main className="min-h-screen bg-slate-50 px-4 py-12 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-6xl">
        <Link href="/" className="text-sm font-semibold text-blue-700 hover:underline">← Retour à l’accueil</Link>
        <header className="mt-8 max-w-3xl">
          <p className="text-sm font-bold uppercase tracking-[0.2em] text-orange-600">Demande de devis</p>
          <h1 className="mt-3 text-4xl font-black tracking-tight text-slate-950">{title}</h1>
          <p className="mt-4 text-lg text-slate-600">Choisissez la spécialité pour voir les professionnels correspondants.</p>
        </header>

        <section className="mt-10 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
          <label htmlFor="specialty" className="block text-sm font-bold text-slate-800">Spécialité recherchée</label>
          <select id="specialty" value={trade} onChange={(event) => setTrade(event.target.value)} className="mt-3 w-full max-w-xl rounded-xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none focus:border-blue-600">
            {options.map(([value, label]) => <option key={value} value={value}>{label}</option>)}
          </select>
        </section>

        <section className="mt-8">
          <div className="flex items-end justify-between gap-4"><h2 className="text-2xl font-bold text-slate-950">Professionnels disponibles</h2><span className="text-sm text-slate-500">{professionals.length} résultat{professionals.length > 1 ? 's' : ''}</span></div>
          {loading && <p className="mt-5 text-slate-600">Recherche en cours...</p>}
          {error && <p className="mt-5 rounded-xl bg-rose-50 p-4 text-rose-700">{error}</p>}
          {!loading && !error && professionals.length === 0 && <p className="mt-5 rounded-xl border border-dashed border-slate-300 bg-white p-8 text-slate-600">Aucun professionnel trouvé pour cette spécialité.</p>}
          <div className="mt-5 grid gap-5 md:grid-cols-2 lg:grid-cols-3">
            {professionals.map((professional) => (
              <Link key={professional.id} href={`/client/${professional.id}`} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition hover:-translate-y-1 hover:border-blue-300 hover:shadow-lg">
                <p className="text-xs font-bold uppercase tracking-[0.15em] text-blue-600">{trade}</p>
                <h3 className="mt-2 text-xl font-bold text-slate-950">{professional.companyName || professional.name}</h3>
                <p className="mt-1 text-sm text-slate-600">{professional.city || 'Ville non renseignée'}</p>
                <p className="mt-4 text-sm font-semibold text-emerald-700">Certification : {professional.certificationScore ?? 0}%</p>
                <span className="mt-5 inline-block text-sm font-bold text-blue-700">Voir le profil et demander un devis →</span>
              </Link>
            ))}
          </div>
        </section>

        <section className="mt-10 rounded-3xl border border-blue-100 bg-blue-50 p-6">
          <h2 className="text-xl font-bold text-slate-950">Demande de devis pour {selectedTradeLabel}</h2>
          <p className="mt-2 text-sm text-slate-600">Vous pouvez choisir un professionnel ci-dessus ou envoyer la même demande à tous les professionnels de cette spécialité.</p>
          {professionals.length > 0 && (
            <div className="mt-6 rounded-2xl bg-white p-4 sm:p-6">
              <ProjectRequestForm
                artisanId={professionals[0].id}
                artisanName={`tous les professionnels ${selectedTradeLabel}`}
                trade={trade}
                broadcastMode
                defaultValues={{
                  clientName: '',
                  clientPhone: '',
                  clientEmail: '',
                  clientAddress: '',
                  projectName: `Demande de devis - ${selectedTradeLabel}`,
                  projectType: dynamicFields[trade]?.[1] || 'Demande de prestation',
                  customProjectType: '',
                  workType: '',
                  description: '',
                  solLongueur: '',
                  solLargeur: '',
                  solSurface: '',
                  murLongueur: '',
                  murHauteur: '',
                  nbMurs: '',
                  murSurface: '',
                  surface: '',
                  budgetEstimate: '',
                  specialtyDetails: '',
                }}
              />
            </div>
          )}
        </section>
      </div>
    </main>
  );
}

"use client";

import { useRef, useState } from "react";
import { ArrowRight, AlertTriangle, CheckCircle2, ImageIcon, Loader2 } from "lucide-react";

const mockAnnotations = [
  { label: "Surface estimée : 12.5 m²", left: "18%", top: "22%", width: "26%", height: "18%", color: "#22c55e" },
  { label: "Fissure détectée", left: "40%", top: "48%", width: "18%", height: "10%", color: "#ef4444" },
  { label: "Câble visible", left: "60%", top: "22%", width: "16%", height: "14%", color: "#0ea5e9" },
];

export default function AnalyseIaPage() {
  const inputRef = useRef<HTMLInputElement | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isAnalyzed, setIsAnalyzed] = useState(false);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setSelectedFile(file);
    const url = URL.createObjectURL(file);
    setPreview(url);
    setIsAnalyzed(false);
    setIsAnalyzing(true);

    window.setTimeout(() => {
      setIsAnalyzing(false);
      setIsAnalyzed(true);
    }, 1800);
  };

  const resetAnalysis = () => {
    setSelectedFile(null);
    setPreview(null);
    setIsAnalyzing(false);
    setIsAnalyzed(false);
    if (inputRef.current) inputRef.current.value = "";
  };

  return (
    <main className="bg-white text-slate-900">
      <section className="mx-auto max-w-7xl px-4 py-16 sm:px-6 lg:px-8">
        <div className="mb-10 text-center">
          <p className="text-sm font-semibold uppercase tracking-[0.18em] text-blue-600">IA</p>
          <h1 className="mt-3 text-4xl font-black tracking-tight text-slate-900 sm:text-5xl">L'œil qui voit tout, même ce qui est caché</h1>
          <p className="mx-auto mt-5 max-w-3xl text-lg text-slate-700">
            L'IA analyse vos photos pour détecter les défauts, calculer les surfaces (m²) et générer automatiquement une liste de matériaux adaptés.
          </p>
        </div>

        <div className="flex flex-col items-center gap-4">
          <button
            onClick={() => inputRef.current?.click()}
            className="inline-flex items-center justify-center gap-2 rounded-full bg-gradient-to-r from-orange-500 to-amber-500 px-6 py-3 text-base font-bold text-white shadow-lg shadow-orange-200"
          >
            <ImageIcon className="h-4 w-4" />
            Tester l'analyse sur ma photo
          </button>
          <input ref={inputRef} type="file" accept="image/*" className="hidden" onChange={handleFileChange} />
        </div>
      </section>

      <section className="mx-auto max-w-6xl px-4 pb-20 sm:px-6 lg:px-8">
        {!preview ? (
          <div className="grid gap-6 rounded-[32px] border border-slate-200 bg-slate-50 p-8 shadow-sm lg:grid-cols-2">
            <div className="rounded-[28px] border border-dashed border-slate-300 bg-white p-8">
              <div className="mb-4 inline-flex rounded-2xl bg-blue-100 p-3 text-2xl">📷</div>
              <h2 className="text-2xl font-black text-slate-900">Avant</h2>
              <div className="mt-4 aspect-[4/3] rounded-2xl bg-[radial-gradient(circle_at_center,_rgba(14,165,233,0.15),_transparent_40%),linear-gradient(135deg,#eff6ff,#dbeafe)] p-4" />
            </div>
            <div className="rounded-[28px] border border-dashed border-slate-300 bg-white p-8">
              <div className="mb-4 inline-flex rounded-2xl bg-emerald-100 p-3 text-2xl">✨</div>
              <h2 className="text-2xl font-black text-slate-900">Après</h2>
              <div className="mt-4 aspect-[4/3] rounded-2xl bg-[linear-gradient(135deg,#f0fdf4,#dcfce7)] p-4" />
            </div>
          </div>
        ) : (
          <div className="rounded-[32px] border border-slate-200 bg-slate-50 p-4 shadow-sm sm:p-6">
            <div className="mb-4 flex items-center justify-between gap-3">
              <div className="flex items-center gap-2 text-sm font-semibold text-slate-700">
                {isAnalyzing ? <Loader2 className="h-4 w-4 animate-spin text-blue-600" /> : <CheckCircle2 className="h-4 w-4 text-emerald-600" />}
                {isAnalyzing ? "L'IA analyse votre image..." : "Analyse terminée"}
              </div>
              <button
                onClick={resetAnalysis}
                className="rounded-full border border-slate-200 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100"
              >
                Analyser une autre image
              </button>
            </div>

            <div className="relative overflow-hidden rounded-[28px] border border-slate-200 bg-white">
              <img
                src={preview}
                alt="Image analysée"
                className="block max-h-[620px] w-full object-contain"
                onContextMenu={(event) => event.preventDefault()}
              />

              {!isAnalyzing && isAnalyzed && (
                <div className="absolute inset-0">
                  {mockAnnotations.map((annotation, index) => (
                    <div key={index} className="absolute rounded-xl border-2 border-dashed" style={{
                      left: annotation.left,
                      top: annotation.top,
                      width: annotation.width,
                      height: annotation.height,
                      borderColor: annotation.color,
                      background: "rgba(255,255,255,0.08)",
                    }}>
                      <span
                        className="absolute -top-7 left-0 rounded-full px-2 py-1 text-[10px] font-bold text-white"
                        style={{ backgroundColor: annotation.color }}
                      >
                        {annotation.label}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {!isAnalyzing && isAnalyzed && (
              <div className="mt-6 grid gap-4 md:grid-cols-3">
                <div className="rounded-2xl border border-slate-200 bg-white p-4">
                  <div className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-500">Surface</div>
                  <div className="mt-2 text-2xl font-black text-slate-900">12.5 m²</div>
                </div>
                <div className="rounded-2xl border border-slate-200 bg-white p-4">
                  <div className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-500">Anomalies</div>
                  <div className="mt-2 text-2xl font-black text-red-600">3</div>
                </div>
                <div className="rounded-2xl border border-slate-200 bg-white p-4">
                  <div className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-500">Matériaux</div>
                  <div className="mt-2 text-xl font-black text-emerald-700">9 éléments</div>
                </div>
              </div>
            )}

            {!isAnalyzing && isAnalyzed && (
              <div className="mt-6 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">
                <div className="flex items-center gap-2 font-semibold">
                  <AlertTriangle className="h-4 w-4" />
                  Légende :
                </div>
                <div className="mt-2 space-y-1">
                  <div>• Rouge = fissure détectée</div>
                  <div>• Vert = surface calculée</div>
                  <div>• Bleu = réseaux / câbles détectés</div>
                </div>
              </div>
            )}
          </div>
        )}

        {!isAnalyzing && isAnalyzed && (
          <div className="mt-8 flex flex-col items-center justify-center gap-4 sm:flex-row">
            <button className="inline-flex items-center gap-2 rounded-full bg-gradient-to-r from-blue-600 to-cyan-600 px-6 py-3 text-base font-bold text-white shadow-lg shadow-blue-200">
              Obtenir un devis complet
              <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        )}
      </section>
    </main>
  );
}

"use client";

import Link from 'next/link';
import { Suspense, useEffect, useMemo, useState } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Users, Building2, BriefcaseBusiness, ShieldCheck, XCircle, CheckCircle2, Send, Sparkles, MapPin, Search, Filter } from 'lucide-react';
import Sidebar from '@/components/Sidebar';

const reasons = [
  'Manque de confiance',
  'Désaccord commercial',
  'Rupture de communication',
  'Problèmes de qualité',
  'Autre',
];

const roleLabels: Record<string, string> = {
  artisan: 'Artisan',
  vendeur: 'Vendeur',
  promoteur: 'Promoteur',
};

type PartnerUser = {
  id: string;
  name: string;
  email: string;
  role: string;
  trade?: string | null;
  companyName?: string | null;
  city?: string | null;
};

type Partnership = {
  id: string;
  status: string;
  targetRole: string;
  cancellationReasons?: string | null;
  cancellationDetails?: string | null;
  evaluationStatus?: string | null;
  initiator: PartnerUser;
  targetUser: PartnerUser;
  reviewedByAdmin?: PartnerUser | null;
  createdAt: string;
};

function PartenairesPageContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { data: session, status } = useSession();
  const [role, setRole] = useState<string>('artisan');
  const [users, setUsers] = useState<PartnerUser[]>([]);
  const [partnerships, setPartnerships] = useState<Partnership[]>([]);
  const [selectedUserId, setSelectedUserId] = useState<string>('');
  const [cancelReasonInputs, setCancelReasonInputs] = useState<Record<string, string[]>>({});
  const [cancelDetails, setCancelDetails] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [cityFilter, setCityFilter] = useState('');

  useEffect(() => {
    if (status === 'loading') return;
    if (!session) {
      router.push('/login');
      return;
    }

    const requestedRole = searchParams.get('role') || 'artisan';
    setRole(requestedRole);
  }, [searchParams, session, status, router]);

  useEffect(() => {
    if (!session) return;

    const load = async () => {
      setLoading(true);
      try {
        const res = await fetch(`/api/partnerships?role=${encodeURIComponent(role)}`, { credentials: 'include' });
        if (!res.ok) throw new Error('Erreur');
        const data = await res.json();
        setUsers(Array.isArray(data.candidates) ? data.candidates : []);
        setPartnerships(Array.isArray(data.partnerships) ? data.partnerships : []);
      } catch (error) {
        console.error('Erreur chargement partenariats', error);
      } finally {
        setLoading(false);
      }
    };

    void load();

    const interval = window.setInterval(() => {
      void load();
    }, 15000);

    return () => window.clearInterval(interval);
  }, [session, role]);

  const filteredUsers = useMemo(() => {
    const normalizedSearch = searchTerm.trim().toLowerCase();

    return users
      .filter((user) => user.id !== session?.user?.id)
      .filter((user) => {
        const matchesSearch = !normalizedSearch || [user.name, user.email, user.companyName, user.trade, user.role, user.city]
          .filter(Boolean)
          .join(' ')
          .toLowerCase()
          .includes(normalizedSearch);

        const matchesCity = !cityFilter || (user.city || '').toLowerCase().includes(cityFilter.trim().toLowerCase());

        return matchesSearch && matchesCity;
      })
      .sort((a, b) => {
        const aMatchesRole = a.role === role || a.trade === role ? 0 : 1;
        const bMatchesRole = b.role === role || b.trade === role ? 0 : 1;
        if (aMatchesRole !== bMatchesRole) return aMatchesRole - bMatchesRole;

        const aCategory = (a.trade || a.role || '').toLowerCase();
        const bCategory = (b.trade || b.role || '').toLowerCase();
        return aCategory.localeCompare(bCategory);
      });
  }, [users, session, role, searchTerm, cityFilter]);

  const createPartnershipForUser = async (userId: string) => {
    if (!userId) return;

    try {
      const res = await fetch('/api/partnerships', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ targetUserId: userId, targetRole: role }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Erreur');

      setSelectedUserId('');
      const refreshed = await fetch(`/api/partnerships?role=${encodeURIComponent(role)}`, { credentials: 'include' });
      if (refreshed.ok) {
        const payload = await refreshed.json();
        setPartnerships(Array.isArray(payload.partnerships) ? payload.partnerships : []);
      }
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Erreur lors de la demande');
    }
  };

  const createPartnership = async () => {
    await createPartnershipForUser(selectedUserId);
  };

  const respondToPartnership = async (partnershipId: string, decision: 'accept' | 'reject') => {
    try {
      const res = await fetch('/api/partnerships', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ partnershipId, action: 'respond', decision }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Erreur');

      setPartnerships((prev) => prev.map((row) => {
        if (row.id !== partnershipId) return row;
        const nextStatus = decision === 'accept' ? 'ACTIVE' : 'REJECTED';
        const nextEvaluationStatus = decision === 'accept' ? 'VALIDATED' : 'REJECTED';

        return {
          ...row,
          status: nextStatus,
          evaluationStatus: nextEvaluationStatus,
        };
      }));
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Erreur lors de la réponse à la demande');
    }
  };

  const cancelPartnership = async (partnershipId: string) => {
    const selectedReasons = cancelReasonInputs[partnershipId] || [];
    const details = cancelDetails[partnershipId] || '';

    try {
      const res = await fetch('/api/partnerships', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ partnershipId, action: 'cancel', reasons: selectedReasons, details }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Erreur');

      setPartnerships((prev) => prev.map((row) => row.id === partnershipId ? { ...row, status: 'CANCELLED', cancellationReasons: selectedReasons.join(', '), cancellationDetails: details } : row));
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Erreur lors de l’annulation');
    }
  };

  const toggleReason = (partnershipId: string, reason: string) => {
    setCancelReasonInputs((prev) => {
      const prevValue = prev[partnershipId] || [];
      const next = prevValue.includes(reason)
        ? prevValue.filter((item) => item !== reason)
        : [...prevValue, reason];
      return { ...prev, [partnershipId]: next };
    });
  };

  const currentLabel = roleLabels[role] || 'Partenaire';

  if (status === 'loading' || !session) return null;

  return (
    <div className="min-h-screen bg-slate-100 text-slate-800">
      <Sidebar />
      <main className="ml-64 p-6">
      <div className="mx-auto max-w-7xl space-y-6">
        <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
          <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
            <div>
              <p className="text-xs font-semibold uppercase tracking-[0.2em] text-slate-500">Relations</p>
              <h1 className="mt-2 text-3xl font-bold text-slate-900">Partenaires</h1>
            </div>
            <div className="flex items-center gap-2 rounded-full border border-blue-200 bg-blue-50 px-3 py-2 text-sm font-medium text-blue-700">
              <Sparkles className="h-4 w-4" />
              Partenariats durables
            </div>
          </div>

          <div className="mt-6 flex flex-wrap gap-3">
            {['artisan', 'vendeur', 'promoteur'].map((tab) => (
              <button
                key={tab}
                onClick={() => router.push(`/partenaires?role=${tab}`)}
                className={`rounded-full px-4 py-2 text-sm font-medium transition ${role === tab ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
              >
                {roleLabels[tab]}
              </button>
            ))}
          </div>
        </div>

        <div className="grid gap-6 xl:grid-cols-[2fr_1fr]">
          <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="mb-5 flex items-center gap-3">
              <Search className="h-5 w-5 text-blue-700" />
              <h2 className="text-xl font-semibold text-slate-900">Rechercher un partenaire</h2>
            </div>

            <div className="grid gap-4 md:grid-cols-[1.6fr_1fr]">
              <div className="rounded-xl border border-slate-200 bg-slate-50 p-3">
                <label className="mb-2 block text-xs font-medium uppercase tracking-[0.2em] text-slate-500">Mot-clé</label>
                <input
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Nom, entreprise, spécialité, produit..."
                  className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500"
                />
              </div>

              <div className="rounded-xl border border-slate-200 bg-slate-50 p-3">
                <label className="mb-2 block text-xs font-medium uppercase tracking-[0.2em] text-slate-500">Région / ville</label>
                <input
                  value={cityFilter}
                  onChange={(e) => setCityFilter(e.target.value)}
                  placeholder="Ex: Lyon, Paris..."
                  className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500"
                />
              </div>
            </div>

            <div className="mt-5 flex items-center gap-2 text-xs font-medium uppercase tracking-[0.2em] text-slate-500">
              <Filter className="h-3.5 w-3.5" />
              Propositions prioritaires
            </div>

            <div className="mt-4 grid gap-4 md:grid-cols-2">
              {filteredUsers.length === 0 ? (
                <div className="md:col-span-2 rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-6 text-sm text-slate-500">
                  Aucun profil ne correspond à votre recherche pour le moment.
                </div>
              ) : (
                filteredUsers.map((user) => (
                  <div key={user.id} className="rounded-2xl border border-rose-100 bg-gradient-to-br from-rose-50 via-violet-50 to-sky-50 p-4 shadow-sm">
                    <div className="flex items-start justify-between gap-3">
                      <div>
                        <p className="text-xs font-semibold uppercase tracking-[0.2em] text-slate-500">{user.role}</p>
                        <h3 className="mt-2 text-lg font-semibold text-slate-900">{user.companyName || user.name || 'Profil'}</h3>
                      </div>
                      <span className="rounded-full bg-white/80 px-2 py-1 text-[10px] font-bold uppercase text-slate-700">
                        {user.trade || 'Général'}
                      </span>
                    </div>

                    <div className="mt-3 space-y-2 text-sm text-slate-600">
                      <p className="font-medium text-slate-700">{user.name || user.email}</p>
                      {user.city && (
                        <p className="flex items-center gap-2">
                          <MapPin className="h-4 w-4 text-rose-500" />
                          {user.city}
                        </p>
                      )}
                    </div>

                    <div className="mt-4 grid gap-2 sm:grid-cols-2">
                      <Link
                        href={`/client/${user.id}`}
                        className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-center text-sm font-medium text-slate-700 hover:border-blue-300 hover:text-blue-600"
                      >
                        Envoyer la demande de devis
                      </Link>
                      <button
                        onClick={() => createPartnershipForUser(user.id)}
                        className="rounded-xl bg-blue-600 px-3 py-2 text-sm font-medium text-white hover:bg-blue-700"
                      >
                        Demander le partenariat
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          </section>

          <aside className="space-y-6">
            <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
              <div className="mb-4 flex items-center gap-3">
                <Users className="h-5 w-5 text-blue-700" />
                <h2 className="text-xl font-semibold text-slate-900">Créer une relation de partenariat</h2>
              </div>

              <div className="space-y-4">
                <select
                  value={selectedUserId}
                  onChange={(e) => setSelectedUserId(e.target.value)}
                  className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-sm outline-none focus:border-blue-500"
                >
                  <option value="">Sélectionner un profil {currentLabel.toLowerCase()}</option>
                  {filteredUsers.map((user) => (
                    <option key={user.id} value={user.id}>
                      {user.name || user.email} · {user.companyName || user.trade || user.role}
                    </option>
                  ))}
                </select>

                <button
                  onClick={() => createPartnershipForUser(selectedUserId)}
                  disabled={!selectedUserId}
                  className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-blue-600 px-4 py-3 font-medium text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-slate-300"
                >
                  <CheckCircle2 className="h-4 w-4" />
                  Demander le partenariat
                </button>
              </div>
            </section>

            <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
              <div className="mb-4 flex items-center gap-3">
                <ShieldCheck className="h-5 w-5 text-emerald-600" />
                <h2 className="text-xl font-semibold text-slate-900">Validation admin</h2>
              </div>

              <div className="space-y-3 text-sm text-slate-600">
                <p>Les demandes de partenariat sont envoyées au système d’évaluation.</p>
                <p>Après validation par l’admin, le partenariat devient actif et visible dans le réseau.</p>
                <p className="rounded-xl bg-emerald-50 p-3 text-emerald-700">Status prévu : PENDING → VALIDATED / REJECTED par l’admin.</p>
              </div>
            </section>
          </aside>
        </div>

        <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
          <div className="mb-5 flex items-center gap-3">
            <Building2 className="h-5 w-5 text-violet-600" />
            <h2 className="text-xl font-semibold text-slate-900">Mes partenariats</h2>
          </div>

          {loading ? (
            <div className="text-sm text-slate-500">Chargement…</div>
          ) : partnerships.length === 0 ? (
            <div className="text-sm text-slate-500">Aucun partenariat pour ce profil.</div>
          ) : (
            <div className="space-y-4">
              {partnerships.map((partnership) => {
                const relatedUser = partnership.initiator.id === session.user.id ? partnership.targetUser : partnership.initiator;
                const isCancelled = partnership.status === 'CANCELLED';
                const isPendingForTarget = partnership.targetUser.id === session.user.id && partnership.status === 'PENDING';
                return (
                  <div key={partnership.id} className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                    <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
                      <div>
                        <h3 className="font-semibold text-slate-900">{relatedUser.name || relatedUser.email}</h3>
                        <p className="text-sm text-slate-600">{relatedUser.companyName || relatedUser.trade || relatedUser.role}</p>
                      </div>

                      <div className="flex items-center gap-2 text-xs font-medium">
                        <span className={`rounded-full px-2 py-1 ${partnership.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-700' : partnership.status === 'CANCELLED' ? 'bg-red-100 text-red-700' : partnership.status === 'REJECTED' ? 'bg-rose-100 text-rose-700' : 'bg-amber-100 text-amber-700'}`}>
                          {partnership.status}
                        </span>
                        <span className="rounded-full bg-slate-200 px-2 py-1 text-slate-700">
                          {partnership.evaluationStatus || 'PENDING'}
                        </span>
                      </div>
                    </div>

                    {isPendingForTarget && (
                      <div className="mt-4 rounded-xl border border-emerald-200 bg-emerald-50 p-3">
                        <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-emerald-700">
                          <CheckCircle2 className="h-4 w-4" />
                          Demande en attente de validation
                        </div>
                        <div className="flex flex-wrap gap-2">
                          <button
                            onClick={() => respondToPartnership(partnership.id, 'accept')}
                            className="rounded-xl bg-emerald-600 px-3 py-2 text-sm font-medium text-white hover:bg-emerald-700"
                          >
                            Valider la demande
                          </button>
                          <button
                            onClick={() => respondToPartnership(partnership.id, 'reject')}
                            className="rounded-xl bg-red-600 px-3 py-2 text-sm font-medium text-white hover:bg-red-700"
                          >
                            Rejeter la demande
                          </button>
                        </div>
                      </div>
                    )}

                    {!isCancelled ? (
                      <div className="mt-4 rounded-xl border border-red-200 bg-red-50 p-3">
                        <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-red-700">
                          <XCircle className="h-4 w-4" />
                          Annulation du partenariat
                        </div>

                        <div className="space-y-2">
                          {reasons.map((reason) => (
                            <label key={reason} className="flex items-center gap-2 text-sm text-slate-700">
                              <input
                                type="checkbox"
                                checked={(cancelReasonInputs[partnership.id] || []).includes(reason)}
                                onChange={() => toggleReason(partnership.id, reason)}
                                className="h-4 w-4 rounded border-slate-300 text-red-600 focus:ring-red-500"
                              />
                              {reason}
                            </label>
                          ))}
                        </div>

                        <textarea
                          value={cancelDetails[partnership.id] || ''}
                          onChange={(e) => setCancelDetails((prev) => ({ ...prev, [partnership.id]: e.target.value }))}
                          placeholder="Précisez la raison détaillée…"
                          className="mt-3 w-full rounded-xl border border-red-200 bg-white px-3 py-2 text-sm outline-none focus:border-red-400"
                          rows={3}
                        />

                        <button
                          onClick={() => cancelPartnership(partnership.id)}
                          className="mt-3 inline-flex items-center gap-2 rounded-xl bg-red-600 px-3 py-2 text-sm font-medium text-white hover:bg-red-700"
                        >
                          <Send className="h-4 w-4" />
                          Envoyer l’annulation
                        </button>
                      </div>
                    ) : (
                      <div className="mt-4 rounded-xl border border-slate-200 bg-white p-3 text-sm text-slate-600">
                        <p className="font-medium text-slate-800">Motif d’annulation :</p>
                        <p>{partnership.cancellationReasons || 'Aucun motif renseigné'}</p>
                        {partnership.cancellationDetails && (
                          <p className="mt-2 text-slate-700">{partnership.cancellationDetails}</p>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </section>
      </div>
      </main>
    </div>
  );
}

export default function PartenairesPage() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-slate-100 p-6 text-slate-600">Chargement des partenariats…</div>}>
      <PartenairesPageContent />
    </Suspense>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useSession } from "next-auth/react";
import { ArrowRight, Clock3, Loader2, Mail, MapPin, User } from "lucide-react";
import Sidebar from "@/components/Sidebar";

type RequestRecipient = {
  id: string;
  status: string;
  trade: string;
  message: string | null;
  createdAt: string;
  project: {
    id: string;
    name: string;
    description: string | null;
    type: string | null;
    surface: number | null;
    budgetEstimate: number | null;
    clientName: string | null;
    clientAddress: string | null;
    status: string;
    sharePublicUrl: string | null;
    projectAccessPin: string | null;
    createdAt: string;
  };
};

const statusLabels: Record<string, string> = {
  INVITE: "Nouvelle demande",
  VUE: "Vue",
  CANDIDAT: "Candidature envoyée",
  NEGOCIATION: "En discussion",
  RETENU: "Professionnel retenu",
  REFUSE: "Refusée",
  NON_RETENU: "Autre professionnel retenu",
};

export default function VendeurDemandesPage() {
  const { data: session, status } = useSession();
  const [requests, setRequests] = useState<RequestRecipient[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (status !== "authenticated") return;

    const load = async () => {
      try {
        setLoading(true);
        const res = await fetch("/api/vendor/requests", { credentials: "include" });
        if (!res.ok) {
          const payload = await res.json().catch(() => ({}));
          throw new Error(payload.error || "Erreur de chargement des demandes");
        }

        const data = await res.json();
        setRequests(Array.isArray(data) ? data : []);
      } catch (e) {
        setError(e instanceof Error ? e.message : "Erreur inconnue");
      } finally {
        setLoading(false);
      }
    };

    void load();
  }, [status]);

  if (status === "loading") {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50">
        <Loader2 className="h-7 w-7 animate-spin text-blue-600" />
      </div>
    );
  }

  if (!session) {
    return null;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar />

      <main className="flex-1 pl-64">
        <div className="mx-auto max-w-6xl p-8">
          <div className="mb-6 flex items-end justify-between gap-4">
            <div>
              <p className="text-sm font-medium uppercase tracking-[0.16em] text-blue-600">Vendeur</p>
              <h1 className="mt-2 text-3xl font-bold text-gray-900">Demandes de devis reçues</h1>
            </div>
            <div className="rounded-full bg-blue-50 px-3 py-1 text-sm font-medium text-blue-700">
              {requests.length} demande{requests.length > 1 ? "s" : ""}
            </div>
          </div>

          {loading ? (
            <div className="rounded-xl border border-slate-200 bg-white p-6 text-slate-500">Chargement des demandes…</div>
          ) : error ? (
            <div className="rounded-xl border border-red-200 bg-red-50 p-6 text-red-700">{error}</div>
          ) : requests.length === 0 ? (
            <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-slate-500">
              Aucune demande de devis reçue pour le moment.
            </div>
          ) : (
            <div className="space-y-4">
              {requests.map((request) => (
                <article key={request.id} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
                  <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
                    <div className="space-y-2">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="rounded-full bg-blue-50 px-2.5 py-1 text-xs font-semibold text-blue-700">
                          {statusLabels[request.status] || request.status}
                        </span>
                        {request.trade && (
                          <span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-600">
                            {request.trade}
                          </span>
                        )}
                      </div>

                      <h2 className="text-xl font-bold text-slate-900">{request.project.name}</h2>

                      <div className="flex flex-wrap items-center gap-4 text-sm text-slate-500">
                        <span className="inline-flex items-center gap-1"><User className="h-4 w-4" /> {request.project.clientName || "Client anonyme"}</span>
                        {request.project.type && <span>{request.project.type}</span>}
                        {request.project.surface && <span>{request.project.surface} m²</span>}
                        {request.project.budgetEstimate && <span>{request.project.budgetEstimate} €</span>}
                      </div>

                      {request.project.description && (
                        <p className="text-sm text-slate-600">{request.project.description}</p>
                      )}

                      {(request.project.clientAddress || request.message) && (
                        <div className="space-y-1 text-sm text-slate-500">
                          {request.project.clientAddress && (
                            <div className="inline-flex items-center gap-1"><MapPin className="h-4 w-4" /> {request.project.clientAddress}</div>
                          )}
                          {request.message && <div>{request.message}</div>}
                        </div>
                      )}
                    </div>

                    <div className="flex min-w-[220px] flex-col gap-2 text-sm text-slate-600">
                      <div className="inline-flex items-center gap-1"><Clock3 className="h-4 w-4" /> {new Date(request.createdAt).toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric" })}</div>
                      <Link
                        href={`/projets/${request.project.id}`}
                        className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-blue-700"
                      >
                        Voir le projet <ArrowRight className="h-4 w-4" />
                      </Link>
                    </div>
                  </div>
                </article>
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState, useEffect, FormEvent } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { useSession } from "next-auth/react";
import {
  Package, Eye, Send, Store, Plus, Edit, Trash2,
  Search, Loader2, Upload, Sparkles, Zap, CheckCircle,
  XCircle, Calendar, Clock, TrendingUp, ArrowRight,
  AlertCircle, LayoutDashboard, Download
} from "lucide-react";
import Sidebar from "@/components/Sidebar";

// ===== TYPES =====
type Product = {
  id: string;
  name: string;
  description: string | null;
  category: string;
  brand: string | null;
  purchasePrice: number;
  salePrice: number;
  stock: number;
  reservedStock: number;
  tvaRate: number;
  imageUrl: string | null;
  catalogId: string;
  createdAt: string;
};

type Catalog = {
  id: string;
  name: string;
  description: string | null;
  productCount: number;
};

type Proposal = {
  id: string;
  projectId: string;
  productId: string;
  quantity: number;
  unitPrice: number;
  status: string;
  message: string | null;
  marketingMessage: string | null;
  deliveryDate: string | null;
  expirationDate: string | null;
  createdAt: string;
  product: { name: string; brand: string | null };
  project?: { name: string };
};

type Listing = {
  id: string;
  productId: string;
  quantity: number;
  unitPrice: number;
  description: string | null;
  endDate: string | null;
  isActive: boolean;
  createdAt: string;
  product: { name: string; brand: string | null; category: string; salePrice: number };
};

type AvailableProject = {
  id: string;
  name: string;
  type: string | null;
  surface: number | null;
  clientName: string;
  description: string | null;
  needs: { id: string; name: string; quantity: number }[];
  availabilityDetails: {
    name: string;
    quantity: number;
    available: boolean;
    stock: number;
    productId: string | null;
  }[];
  color: "green" | "orange" | "red";
  createdAt: string;
};

type SectionType = "dashboard" | "catalogue" | "projets" | "offres" | "annonces" | "ia";

export default function VendeurPage() {
  const router = useRouter();
  const { data: session, status } = useSession();

  // ===== ÉTATS =====
  const [products, setProducts] = useState<Product[]>([]);
  const [proposals, setProposals] = useState<Proposal[]>([]);
  const [listings, setListings] = useState<Listing[]>([]);
  const [availableProjects, setAvailableProjects] = useState<AvailableProject[]>([]);
  const [loading, setLoading] = useState(true);
  const [catalogs, setCatalogs] = useState<Catalog[]>([]);
  const [selectedCatalogId, setSelectedCatalogId] = useState<string | null>(() => {
    if (typeof window === "undefined") return null;
    return new URLSearchParams(window.location.search).get("catalog");
  });
  const [section, setSection] = useState<SectionType>(() => {
    if (typeof window === "undefined") return "dashboard";

    const params = new URLSearchParams(window.location.search);
    const catalogParam = params.get("catalog");
    const sectionParam = params.get("section") as SectionType | null;

    if (catalogParam) return "catalogue";
    if (sectionParam && ["dashboard", "catalogue", "projets", "offres", "annonces", "ia"].includes(sectionParam)) {
      return sectionParam;
    }

    return "dashboard";
  });
  const [catalogsLoading, setCatalogsLoading] = useState(false);

  // Vérification agent actif
  const [hasActiveAgent, setHasActiveAgent] = useState<boolean | null>(null);
  const [checkingAgent, setCheckingAgent] = useState(true);

  // États modale produit
  const [showModal, setShowModal] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [uploadedImageUrl, setUploadedImageUrl] = useState<string | null>(null);
  const [uploadingImage, setUploadingImage] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    category: "",
    brand: "",
    purchasePrice: "",
    salePrice: "",
    stock: "",
    tvaRate: "20",
    imageUrl: "",
    catalogId: "",
  });

  // États offres
  const [offerProjectId, setOfferProjectId] = useState("");
  const [offerProductId, setOfferProductId] = useState("");
  const [offerQuantity, setOfferQuantity] = useState("1");
  const [offerUnitPrice, setOfferUnitPrice] = useState("");
  const [offerMessage, setOfferMessage] = useState("");
  const [offerMarketingMessage, setOfferMarketingMessage] = useState("");
  const [offerDeliveryDate, setOfferDeliveryDate] = useState("");
  const [sendingOffer, setSendingOffer] = useState(false);

  // États annonces
  const [showListingModal, setShowListingModal] = useState(false);
  const [listingProductId, setListingProductId] = useState("");
  const [listingQuantity, setListingQuantity] = useState("");
  const [listingUnitPrice, setListingUnitPrice] = useState("");
  const [listingDescription, setListingDescription] = useState("");
  const [listingEndDate, setListingEndDate] = useState("");
  const [sendingListing, setSendingListing] = useState(false);

  const listingTotalPrice = (() => {
    const quantity = Number(listingQuantity);
    const unitPrice = Number(listingUnitPrice);

    if (!Number.isFinite(quantity) || !Number.isFinite(unitPrice) || quantity <= 0 || unitPrice < 0) {
      return 0;
    }

    return quantity * unitPrice;
  })();

  // IA
  const [aiSuggestions, setAiSuggestions] = useState<Array<{
    projectId: string;
    projectName: string;
    summary: string;
    recommendedProducts: Array<Record<string, unknown>>;
    recommendedTutorials: Array<Record<string, unknown>>;
    questions: string[];
    nextAction: string;
  }>>([]);
  const [aiLoading, setAiLoading] = useState(false);

  // Import
  const [showImportModal, setShowImportModal] = useState(false);
  const [importFile, setImportFile] = useState<File | null>(null);
  const [importLoading, setImportLoading] = useState(false);
  const [importCatalogId, setImportCatalogId] = useState("");
  const [importNewCatalogName, setImportNewCatalogName] = useState("");

  // Suppression globale d'un catalogue
  const [showClearCatalogModal, setShowClearCatalogModal] = useState(false);

  // Relance
  const [showRelaunchModal, setShowRelaunchModal] = useState(false);
  const [relaunchData, setRelaunchData] = useState<{
    id: string;
    quantity: string;
    unitPrice: string;
    message: string;
    marketingMessage: string;
    deliveryDate: string;
  } | null>(null);

  // ===== STATISTIQUES =====
  const stats = [
    {
      label: "Produits",
      value: products.length,
      icon: Package,
      color: "blue",
      section: "catalogue" as SectionType
    },
    {
      label: "Projets dispo.",
      value: availableProjects.length,
      icon: Eye,
      color: "green",
      section: "projets" as SectionType
    },
    {
      label: "Offres envoyées",
      value: proposals.length,
      icon: Send,
      color: "purple",
      section: "offres" as SectionType
    },
    {
      label: "Annonces actives",
      value: listings.filter(l => l.isActive).length,
      icon: Store,
      color: "orange",
      section: "annonces" as SectionType
    },
  ];

  const pendingProposals = proposals.filter(p => p.status === "EN_ATTENTE").length;
  const lowStockProducts = products.filter(p => p.stock < 5);
  const recentProjects = [...availableProjects]
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    .slice(0, 3);

  // ===== CHARGEMENT =====
  const fetchProducts = async () => {
    try {
      const res = await fetch("/api/seller/products", { credentials: "include" });
      if (!res.ok) throw new Error("Erreur chargement produits");
      const data = await res.json();
      setProducts(data);
    } catch (error) {
      console.error("Erreur fetchProducts :", error);
    }
  };

  const fetchProposals = async () => {
    try {
      const res = await fetch("/api/seller/proposals", { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setProposals(data);
      }
    } catch (error) {
      console.error("Erreur chargement offres :", error);
    }
  };

  const fetchListings = async () => {
    try {
      const res = await fetch("/api/seller/listings", { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setListings(data);
      }
    } catch (error) {
      console.error("Erreur chargement annonces :", error);
    }
  };

  const cancelListing = async (id: string) => {
    if (!window.confirm("Annuler cette annonce ? Elle ne sera plus visible pour les artisans.")) {
      return;
    }

    try {
      const res = await fetch(`/api/seller/listings/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ action: "cancel" }),
      });

      if (res.ok) {
        await fetchListings();
      } else {
        const errorData = await res.json().catch(() => ({}));
        console.error("Erreur cancelListing :", errorData);
        alert(errorData.error || "Impossible d’annuler cette annonce.");
      }
    } catch (error) {
      console.error("Erreur cancelListing :", error);
      alert("Une erreur est survenue lors de l’annulation.");
    }
  };

  const deleteListing = async (id: string) => {
    if (!window.confirm("Supprimer définitivement cette annonce ?")) {
      return;
    }

    try {
      const res = await fetch(`/api/seller/listings/${id}`, {
        method: "DELETE",
        credentials: "include",
      });

      if (res.ok) {
        await fetchListings();
      } else {
        const errorData = await res.json().catch(() => ({}));
        console.error("Erreur deleteListing :", errorData);
        alert(errorData.error || "Impossible de supprimer cette annonce.");
      }
    } catch (error) {
      console.error("Erreur deleteListing :", error);
      alert("Une erreur est survenue lors de la suppression.");
    }
  };

  const fetchAvailableProjects = async () => {
    try {
      const res = await fetch("/api/vendor/projects", { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setAvailableProjects(data);
      }
    } catch (error) {
      console.error("Erreur chargement projets :", error);
    }
  };

  const fetchCatalogs = async () => {
    setCatalogsLoading(true);
    try {
      const res = await fetch("/api/seller/catalogs", { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setCatalogs(data);

        const tradeName = (session?.user?.trade || "").trim();
        const preferredCatalog =
          (tradeName
            ? data.find((cat: Catalog) => {
                const normalizedName = cat.name.toLowerCase().replace(/[^a-z0-9]/g, "");
                const tradeNormalized = tradeName.toLowerCase().replace(/[^a-z0-9]/g, "");
                return normalizedName.includes(tradeNormalized) || tradeNormalized.includes(normalizedName);
              })
            : null) ||
          data[0] || null;

        if (preferredCatalog && !selectedCatalogId) {
          setSelectedCatalogId(preferredCatalog.id);
        }
      }
    } catch (error) {
      console.error("Erreur chargement catalogues :", error);
    } finally {
      setCatalogsLoading(false);
    }
  };

  const refreshCatalogSidebar = () => {
    window.dispatchEvent(new CustomEvent("seller-catalogs:refresh"));
  };

  const fetchAISuggestions = async () => {
    setAiLoading(true);
    try {
      const projectPool = availableProjects.slice(0, 4);
      if (projectPool.length === 0) {
        setAiSuggestions([]);
        return;
      }

      const analyses = await Promise.all(
        projectPool.map(async (project) => {
          const res = await fetch('/api/agent/analyze', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            credentials: 'include',
            body: JSON.stringify({ projectId: project.id }),
          });

          if (!res.ok) {
            return null;
          }

          const data = await res.json();
          return {
            projectId: project.id,
            projectName: project.name,
            summary: typeof data.summary === 'string' ? data.summary : 'Analyse du projet en cours.',
            recommendedProducts: Array.isArray(data.recommendedProducts) ? data.recommendedProducts : [],
            recommendedTutorials: Array.isArray(data.recommendedTutorials) ? data.recommendedTutorials : [],
            questions: Array.isArray(data.questions) ? data.questions : [],
            nextAction: typeof data.nextAction === 'string' ? data.nextAction : 'Suivre la recommandation IA.',
          };
        })
      );

      setAiSuggestions(analyses.filter(Boolean) as Array<{
        projectId: string;
        projectName: string;
        summary: string;
        recommendedProducts: Array<Record<string, unknown>>;
        recommendedTutorials: Array<Record<string, unknown>>;
        questions: string[];
        nextAction: string;
      }>);
    } catch (error) {
      console.error('AI suggestions error:', error);
      setAiSuggestions([]);
    } finally {
      setAiLoading(false);
    }
  };

  const checkActiveAgent = async () => {
    if (!session?.user?.id) {
      setHasActiveAgent(false);
      setCheckingAgent(false);
      return;
    }
    try {
      const res = await fetch("/api/user/agents/check", { credentials: "include" });
      if (res.ok) {
        const data = await res.json();
        setHasActiveAgent(Boolean(data?.hasActive));
      } else {
        setHasActiveAgent(false);
      }
    } catch (error) {
      setHasActiveAgent(false);
    } finally {
      setCheckingAgent(false);
    }
  };

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      await Promise.all([
        fetchProducts(),
        fetchProposals(),
        fetchListings(),
        fetchAvailableProjects(),
        fetchCatalogs(),
        checkActiveAgent(),
      ]);
      setLoading(false);
    };

    load();
  }, [session]);

  const normalizeCatalogId = (catalogId: string | null | undefined) => {
    if (typeof catalogId !== "string") return null;
    const value = catalogId.trim();
    return value ? value : null;
  };

  const handleCatalogSelect = (catalogId: string | null) => {
    const safeCatalogId = normalizeCatalogId(catalogId);
    setSelectedCatalogId(safeCatalogId);
    const params = new URLSearchParams(window.location.search);
    params.set("section", "catalogue");

    if (safeCatalogId) {
      params.set("catalog", safeCatalogId);
      setSection("catalogue");
    } else {
      params.delete("catalog");
    }

    window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
  };

  // ===== CRUD PRODUITS =====
  const uploadProductImage = async (file: File) => {
    const form = new FormData();
    form.append("file", file);

    const res = await fetch("/api/upload", {
      method: "POST",
      credentials: "include",
      body: form,
    });

    const data = await res.json();
    if (!res.ok) {
      throw new Error(data.error || "Erreur lors de l'upload de l'image");
    }

    return data.url as string | undefined;
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) {
      setUploadedImageUrl(null);
      return;
    }

    try {
      setUploadingImage(true);
      const url = await uploadProductImage(file);
      if (url) {
        setUploadedImageUrl(url);
      }
    } catch (error) {
      console.error("Erreur upload image produit:", error);
      alert(error instanceof Error ? error.message : "Impossible d'importer cette image.");
    } finally {
      setUploadingImage(false);
      e.target.value = "";
    }
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      const url = editingProduct
        ? `/api/seller/products/${editingProduct.id}`
        : "/api/seller/products";
      const method = editingProduct ? "PUT" : "POST";
      const resolvedImageUrl = uploadedImageUrl || formData.imageUrl.trim() || null;
      const payload = {
        ...formData,
        imageUrl: resolvedImageUrl,
        purchasePrice: parseFloat(formData.purchasePrice),
        salePrice: parseFloat(formData.salePrice),
        stock: parseInt(formData.stock),
        tvaRate: parseFloat(formData.tvaRate),
        catalogId: formData.catalogId || undefined,
        brand: formData.brand || null,
      };
      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(payload),
      });
      if (res.ok) {
        setShowModal(false);
        await fetchProducts();
        await fetchCatalogs();
        refreshCatalogSidebar();
        setEditingProduct(null);
        setUploadedImageUrl(null);
        setFormData({
          name: "",
          description: "",
          category: "",
          brand: "",
          purchasePrice: "",
          salePrice: "",
          stock: "",
          tvaRate: "20",
          imageUrl: "",
          catalogId: "",
        });
      } else {
        console.error("Erreur lors de l'enregistrement du produit");
      }
    } catch (error) {
      console.error("Erreur handleSubmit :", error);
    }
  };

  const deleteProduct = async (id: string) => {
    if (!confirm("Voulez-vous vraiment supprimer ce produit ?")) return;
    try {
      const res = await fetch(`/api/seller/products/${id}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (res.ok) {
        await fetchProducts();
      } else {
        console.error("Erreur lors de la suppression");
      }
    } catch (error) {
      console.error("Erreur deleteProduct :", error);
    }
  };

  const clearCatalogProducts = async () => {
    if (!selectedCatalogId) return;

    const productsToDelete = products.filter(p => p.catalogId === selectedCatalogId);
    if (productsToDelete.length === 0) {
      setShowClearCatalogModal(false);
      return;
    }

    try {
      const deletions = productsToDelete.map(async (product) => 
        fetch(`/api/seller/products/${product.id}`, {
          method: "DELETE",
          credentials: "include",
        })
      );

      const results = await Promise.all(deletions);
      const hasError = results.some(res => !res.ok);

      if (hasError) {
        alert("Une erreur est survenue lors de la suppression de certains produits.");
      }

      setShowClearCatalogModal(false);
      await fetchProducts();
    } catch (error) {
      console.error("Erreur clearCatalogProducts :", error);
      alert("Impossible de vider ce catalogue pour le moment.");
    }
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setUploadedImageUrl(null);
    setFormData({
      name: product.name,
      description: product.description || "",
      category: product.category,
      brand: product.brand || "",
      purchasePrice: product.purchasePrice?.toString() ?? "",
      salePrice: product.salePrice?.toString() ?? "",
      stock: product.stock?.toString() ?? "",
      tvaRate: product.tvaRate?.toString() ?? "",
      imageUrl: product.imageUrl || "",
      catalogId: product.catalogId || "",
    });
    setShowModal(true);
  };

  // ===== IMPORT CSV =====
  const handleImport = async (e: FormEvent) => {
    e.preventDefault();
    if (!importFile) return;

    const resolvedCatalogId = importCatalogId || selectedCatalogId || "";
    let targetCatalogId = resolvedCatalogId;

    if (importCatalogId === "new" && importNewCatalogName.trim()) {
      try {
        const res = await fetch("/api/seller/catalogs", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
          body: JSON.stringify({ name: importNewCatalogName.trim() }),
        });
        if (!res.ok) {
          const err = await res.json();
          alert("Erreur lors de la création du catalogue : " + err.error);
          return;
        }
        const newCatalog = await res.json();
        targetCatalogId = newCatalog.id;
        setSelectedCatalogId(newCatalog.id);
        setImportCatalogId(newCatalog.id);
        await fetchCatalogs();
      } catch (error) {
        console.error("Erreur création catalogue:", error);
        alert("Erreur lors de la création du catalogue");
        return;
      }
    }

    if (!targetCatalogId) {
      alert("Veuillez sélectionner un catalogue ou en créer un nouveau.");
      return;
    }

    setImportLoading(true);
    const formDataFile = new FormData();
    formDataFile.append("file", importFile);
    formDataFile.append("catalogId", targetCatalogId);
    try {
      const res = await fetch("/api/seller/products/import", {
        method: "POST",
        credentials: "include",
        body: formDataFile,
      });
      if (res.ok) {
        const nextCatalogId = normalizeCatalogId(targetCatalogId) || normalizeCatalogId(selectedCatalogId) || null;
        if (nextCatalogId) {
          setSelectedCatalogId(nextCatalogId);
          const params = new URLSearchParams(window.location.search);
          params.set("section", "catalogue");
          params.set("catalog", nextCatalogId);
          window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
        }
        setShowImportModal(false);
        setImportFile(null);
        setImportCatalogId("");
        setImportNewCatalogName("");
        await fetchProducts();
        await fetchCatalogs();
        refreshCatalogSidebar();
        alert("Import réussi !");
      } else {
        const err = await res.json();
        alert("Erreur import : " + (err.error || "Erreur inconnue"));
      }
    } catch (error) {
      console.error("Erreur handleImport :", error);
      alert("Erreur lors de l'import");
    } finally {
      setImportLoading(false);
    }
  };

  // ===== ENVOI D'OFFRE =====
  const handleSendOffer = async (e: FormEvent) => {
    e.preventDefault();
    if (!offerProjectId || !offerProductId) return;
    setSendingOffer(true);
    try {
      const payload = {
        projectId: offerProjectId,
        productId: offerProductId,
        quantity: parseInt(offerQuantity),
        unitPrice: parseFloat(offerUnitPrice),
        message: offerMessage,
        marketingMessage: offerMarketingMessage,
        deliveryDate: offerDeliveryDate || undefined,
      };
      const res = await fetch("/api/seller/proposals", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(payload),
      });
      if (res.ok) {
        setOfferProjectId("");
        setOfferProductId("");
        setOfferQuantity("1");
        setOfferUnitPrice("");
        setOfferMessage("");
        setOfferMarketingMessage("");
        setOfferDeliveryDate("");
        await fetchProposals();
        await fetchProducts();
      } else {
        console.error("Erreur envoi offre");
      }
    } catch (error) {
      console.error("Erreur handleSendOffer :", error);
    } finally {
      setSendingOffer(false);
    }
  };

  // ===== RELANCE =====
  const openRelaunchModal = (proposal: Proposal) => {
    setRelaunchData({
      id: proposal.id,
      quantity: proposal.quantity.toString(),
      unitPrice: proposal.unitPrice.toString(),
      message: proposal.message || "",
      marketingMessage: proposal.marketingMessage || "",
      deliveryDate: proposal.deliveryDate || "",
    });
    setShowRelaunchModal(true);
  };

  const handleRelaunch = async (e: FormEvent) => {
    e.preventDefault();
    if (!relaunchData) return;
    try {
      const res = await fetch(`/api/seller/proposals/${relaunchData.id}/relaunch`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          quantity: parseInt(relaunchData.quantity),
          unitPrice: parseFloat(relaunchData.unitPrice),
          message: relaunchData.message,
          marketingMessage: relaunchData.marketingMessage,
          deliveryDate: relaunchData.deliveryDate || undefined,
        }),
      });
      if (res.ok) {
        setShowRelaunchModal(false);
        setRelaunchData(null);
        await fetchProposals();
      }
    } catch (error) {
      console.error("Erreur handleRelaunch :", error);
    }
  };

  const cancelProposal = async (id: string) => {
    if (!confirm("Annuler cette offre ?")) return;
    try {
      const res = await fetch(`/api/seller/proposals/${id}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (res.ok) {
        await fetchProposals();
        await fetchProducts();
      }
    } catch (error) {
      console.error("Erreur cancelProposal :", error);
    }
  };

  const goToLowStockSource = (product?: Product) => {
    if (product) {
      setSelectedCatalogId(product.catalogId);
    }
    setSection("catalogue");
  };

  // ===== CRÉATION D'ANNONCE =====
  const handleCreateListing = async (e: FormEvent) => {
    e.preventDefault();
    if (!listingProductId || !listingQuantity || !listingUnitPrice || !listingEndDate) return;
    setSendingListing(true);
    try {
      const payload = {
        productId: listingProductId,
        quantity: parseInt(listingQuantity),
        unitPrice: parseFloat(listingUnitPrice),
        description: listingDescription,
        endDate: listingEndDate,
      };
      const res = await fetch("/api/seller/listings", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(payload),
      });
      if (res.ok) {
        setShowListingModal(false);
        setListingProductId("");
        setListingQuantity("");
        setListingUnitPrice("");
        setListingDescription("");
        setListingEndDate("");
        await fetchListings();
      }
    } catch (error) {
      console.error("Erreur handleCreateListing :", error);
    } finally {
      setSendingListing(false);
    }
  };

  // ===== RENDU DES SECTIONS =====
  const renderSection = () => {
    const safeSelectedCatalogId = normalizeCatalogId(selectedCatalogId);
    const activeCatalog = catalogs.find(c => c.id === safeSelectedCatalogId) ?? null;
    const activeCatalogId = safeSelectedCatalogId ?? (catalogs.length === 1 ? catalogs[0].id : null);

    const filteredProducts = activeCatalogId
      ? products.filter(p => p.catalogId === activeCatalogId)
      : products;

    const getCatalogsWithProducts = () => {
      if (activeCatalogId) {
        const catalog = catalogs.find(c => c.id === activeCatalogId) ?? activeCatalog;
        if (!catalog) return [];
        const prods = products.filter(p => p.catalogId === activeCatalogId);
        return [{ catalog, products: prods }];
      }
      return catalogs
        .map(cat => ({
          catalog: cat,
          products: products.filter(p => p.catalogId === cat.id),
        }))
        .filter(group => group.products.length > 0);
    };

    const catalogGroups = getCatalogsWithProducts();

    switch (section) {
      case "dashboard":
        return (
          <div>
            {lowStockProducts.length > 0 && (
              <button
                type="button"
                onClick={() => goToLowStockSource(lowStockProducts[0])}
                className="w-full bg-red-50 border border-red-200 rounded-lg p-3 mb-6 flex items-center gap-2 text-left hover:bg-red-100 transition"
              >
                <AlertCircle className="w-5 h-5 text-red-600 shrink-0" />
                <span className="text-sm text-red-700 flex flex-wrap items-center gap-1">
                  <span>⚠️ {lowStockProducts.length} produit(s) en stock critique (&lt; 5 unités) :</span>
                  {lowStockProducts.slice(0, 3).map((p) => (
                    <button
                      key={p.id}
                      type="button"
                      onClick={(event) => {
                        event.stopPropagation();
                        goToLowStockSource(p);
                      }}
                      className="font-medium underline underline-offset-2 decoration-red-500 hover:text-red-900"
                    >
                      {p.name}
                    </button>
                  ))}
                  {lowStockProducts.length > 3 && <span>et {lowStockProducts.length - 3} autres</span>}
                  <span className="ml-1 text-red-600 font-semibold">→ Voir le catalogue concerné</span>
                </span>
              </button>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
              {stats.map((stat, idx) => (
                <div
                  key={idx}
                  onClick={() => setSection(stat.section)}
                  className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 flex items-center gap-4 cursor-pointer hover:shadow-md transition"
                >
                  <div className={`p-3 rounded-lg bg-${stat.color}-100`}>
                    <stat.icon className={`w-5 h-5 text-${stat.color}-600`} />
                  </div>
                  <div>
                    <p className="text-2xl font-bold text-gray-800">{stat.value}</p>
                    <p className="text-xs text-gray-500">{stat.label}</p>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-3 gap-4 mb-6">
              <div className="col-span-2 bg-white rounded-xl shadow-sm border border-gray-100 p-4">
                <h3 className="text-sm font-medium text-gray-700 flex items-center gap-2">
                  <Clock className="w-4 h-4 text-yellow-600" />
                  Offres en attente
                </h3>
                <p className="text-2xl font-bold text-gray-800 mt-1">{pendingProposals}</p>
                <button
                  onClick={() => setSection("offres")}
                  className="text-xs text-blue-600 hover:underline mt-1"
                >
                  Voir les offres en attente →
                </button>
              </div>
              <div className="col-span-1 bg-white rounded-xl shadow-sm border border-gray-100 p-4">
                <h3 className="text-sm font-medium text-gray-700 flex items-center gap-2">
                  <TrendingUp className="w-4 h-4 text-green-600" />
                  Projets récents
                </h3>
                {recentProjects.length === 0 ? (
                  <p className="text-sm text-gray-500 mt-1">Aucun projet récent</p>
                ) : (
                  <ul className="mt-1 space-y-1">
                    {recentProjects.map(p => (
                      <li key={p.id} className="text-sm text-gray-600 flex justify-between">
                        <span>{p.name}</span>
                        <span className="text-xs text-gray-400">{new Date(p.createdAt).toLocaleDateString()}</span>
                      </li>
                    ))}
                  </ul>
                )}
                <button
                  onClick={() => setSection("projets")}
                  className="text-xs text-blue-600 hover:underline mt-1"
                >
                  Voir tous →
                </button>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-md font-semibold text-gray-700 flex items-center gap-2">
                  <Package className="w-5 h-5 text-blue-600" /> 
                  {selectedCatalogId 
                    ? `Produits en vedette - ${catalogs.find(c => c.id === selectedCatalogId)?.name || "Catalogue"}`
                    : "Produits en vedette"}
                </h3>
                <button
                  onClick={() => {
                    if (selectedCatalogId) {
                      setSelectedCatalogId(null);
                    } else {
                      setSection("catalogue");
                    }
                  }}
                  className="text-sm text-blue-600 hover:underline flex items-center gap-1"
                >
                  {selectedCatalogId ? "Voir tous les catalogues" : "Voir tout le catalogue"} 
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>

              {catalogGroups.length === 0 ? (
                <p className="text-sm text-gray-400">Aucun produit dans ce catalogue.</p>
              ) : selectedCatalogId ? (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  {filteredProducts
                    .sort(() => Math.random() - 0.5)
                    .slice(0, 8)
                    .map(p => (
                      <div key={p.id} className="bg-gray-50 rounded-lg p-3 border border-gray-200">
                        {p.imageUrl && (
                          <img src={p.imageUrl} alt={p.name} className="w-full h-16 object-cover rounded-md mb-2" />
                        )}
                        <div className="flex justify-between">
                          <span className="text-sm font-medium truncate">{p.name}</span>
                          <span className="text-xs text-gray-500">{p.category}</span>
                        </div>
                        {p.brand && <div className="text-xs text-gray-400">Marque: {p.brand}</div>}
                        <div className="mt-1 text-sm font-bold text-blue-600">{p.salePrice} €</div>
                        <div className="text-xs text-gray-500">Stock: {p.stock}</div>
                      </div>
                    ))}
                  {filteredProducts.length === 0 && (
                    <p className="text-sm text-gray-400 col-span-4">Aucun produit dans ce catalogue.</p>
                  )}
                </div>
              ) : (
                <div className="space-y-4">
                  {catalogGroups.map((group, index) => {
                    const isLast = index === catalogGroups.length - 1;
                    const isOddLast = isLast && catalogGroups.length % 2 === 1;
                    const productsToShow = group.products
                      .sort(() => Math.random() - 0.5)
                      .slice(0, isOddLast ? 8 : 4);

                    return (
                      <div key={group.catalog.id} className="border-b border-gray-100 last:border-0 pb-4 last:pb-0">
                        <div className="flex justify-between items-center mb-2">
                          <h4 className="text-sm font-medium text-gray-700">
                            {group.catalog.name}
                            <span className="ml-2 text-xs text-gray-400">({group.products.length} produits)</span>
                          </h4>
                          <button
                            onClick={() => {
                              setSelectedCatalogId(group.catalog.id);
                              setSection("catalogue");
                            }}
                            className="text-xs text-blue-600 hover:underline"
                          >
                            Voir tout →
                          </button>
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                          {productsToShow.map(p => (
                            <div key={p.id} className="bg-gray-50 rounded-lg p-3 border border-gray-200">
                              {p.imageUrl && (
                                <img src={p.imageUrl} alt={p.name} className="w-full h-16 object-cover rounded-md mb-2" />
                              )}
                              <div className="flex justify-between">
                                <span className="text-sm font-medium truncate">{p.name}</span>
                                <span className="text-xs text-gray-500">{p.category}</span>
                              </div>
                              {p.brand && <div className="text-xs text-gray-400">Marque: {p.brand}</div>}
                              <div className="mt-1 text-sm font-bold text-blue-600">{p.salePrice} €</div>
                              <div className="text-xs text-gray-500">Stock: {p.stock}</div>
                            </div>
                          ))}
                          {productsToShow.length === 0 && (
                            <p className="text-xs text-gray-400 col-span-4">Aucun produit</p>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            <div className="grid grid-cols-3 gap-6 mb-6">
              <div className="col-span-1 bg-white rounded-xl shadow-sm border border-gray-100 p-4">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                    <Send className="w-4 h-4 text-purple-600" /> Offres
                  </h3>
                  <button
                    onClick={() => setSection("offres")}
                    className="text-xs text-blue-600 hover:underline"
                  >
                    Voir tout
                  </button>
                </div>
                <div className="space-y-3">
                  {proposals
                    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
                    .slice(0, 4)
                    .map(offre => (
                      <div key={offre.id} className="bg-gray-50 rounded-lg p-2 border border-gray-200">
                        <div className="flex justify-between items-start">
                          <span className="text-xs font-medium truncate">{offre.product.name}</span>
                          <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${
                            offre.status === "EN_ATTENTE" ? "bg-yellow-100 text-yellow-700" :
                            offre.status === "ACCEPTEE" ? "bg-green-100 text-green-700" :
                            "bg-red-100 text-red-700"
                          }`}>{offre.status}</span>
                        </div>
                        <div className="text-xs text-gray-600">
                          Qté: {offre.quantity} | {offre.unitPrice} €
                        </div>
                        <div className="text-[10px] text-gray-400">
                          {new Date(offre.createdAt).toLocaleDateString()}
                        </div>
                      </div>
                    ))}
                  {proposals.length === 0 && (
                    <p className="text-xs text-gray-400">Aucune offre</p>
                  )}
                </div>
              </div>

              <div className="col-span-2 bg-white rounded-xl shadow-sm border border-gray-100 p-4">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                    <Store className="w-4 h-4 text-orange-600" /> Annonces
                  </h3>
                  <button
                    onClick={() => setSection("annonces")}
                    className="text-xs text-blue-600 hover:underline"
                  >
                    Voir tout
                  </button>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  {listings
                    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
                    .slice(0, 4)
                    .map(annonce => (
                      <div key={annonce.id} className="bg-gray-50 rounded-lg p-2 border border-gray-200">
                        <div className="flex justify-between items-start">
                          <span className="text-xs font-medium truncate">{annonce.product.name}</span>
                          <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${
                            annonce.isActive ? "bg-green-100 text-green-700" : "bg-gray-100 text-gray-600"
                          }`}>{annonce.isActive ? "Active" : "Inactive"}</span>
                        </div>
                        <div className="text-xs text-gray-600">
                          {annonce.quantity} u | {annonce.unitPrice} €/u
                        </div>
                        <div className="text-[10px] text-gray-400">
                          {new Date(annonce.createdAt).toLocaleDateString()}
                        </div>
                      </div>
                    ))}
                  {listings.length === 0 && (
                    <p className="text-xs text-gray-400 col-span-2">Aucune annonce</p>
                  )}
                </div>
              </div>
            </div>

            <div className="bg-gradient-to-r from-purple-50 to-blue-50 rounded-xl shadow-sm border border-purple-200 p-4">
              <div className="flex justify-between items-center">
                <h3 className="text-sm font-medium flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-purple-600" /> Assistant IA Vendeur
                </h3>
                <button
                  onClick={() => setSection("ia")}
                  className="text-xs text-blue-600 hover:underline"
                >
                  Voir les recommandations →
                </button>
              </div>
              <p className="text-xs text-gray-500 mt-1">
                Analysez votre catalogue et les projets disponibles avec l’IA.
              </p>
            </div>
          </div>
        );

      case "catalogue":
        if (activeCatalogId) {
          return (
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-5">
              <div className="flex justify-between items-center mb-4 flex-wrap gap-3">
                <div className="flex items-center gap-3">
                  <h2 className="text-lg font-semibold text-gray-800">
                    {activeCatalog ? activeCatalog.name : "Catalogue"}
                  </h2>
                  <button
                    onClick={() => {
                      setSelectedCatalogId(null);
                      const params = new URLSearchParams(window.location.search);
                      params.set("section", "catalogue");
                      params.delete("catalog");
                      window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
                    }}
                    className="text-xs bg-blue-50 text-blue-600 px-3 py-1 rounded-full hover:bg-blue-100 transition flex items-center gap-1"
                  >
                    <ArrowRight className="w-3 h-3 rotate-180" /> Retour à tous les catalogues
                  </button>
                  <span className="text-xs text-gray-500 bg-gray-100 px-3 py-1 rounded-full">
                    {activeCatalog ? activeCatalog.name : "Catalogue"}
                  </span>
                </div>

                <div className="flex gap-2">
                  <button
                    onClick={() => {
                      setImportCatalogId(activeCatalogId || selectedCatalogId || "");
                      setImportNewCatalogName("");
                      setShowImportModal(true);
                    }}
                    className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition flex items-center gap-2 text-sm"
                  >
                    <Upload className="w-4 h-4" /> Importer
                  </button>
                  <button
                    onClick={() => {
                      setEditingProduct(null);
                      setFormData({
                        name: "",
                        description: "",
                        category: "",
                        brand: "",
                        purchasePrice: "",
                        salePrice: "",
                        stock: "",
                        tvaRate: "20",
                        imageUrl: "",
                        catalogId: activeCatalogId || "",
                      });
                      setShowModal(true);
                    }}
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition flex items-center gap-2 text-sm"
                  >
                    <Plus className="w-4 h-4" /> Ajouter un produit
                  </button>
                  <button
                    onClick={() => setShowClearCatalogModal(true)}
                    className="px-4 py-2 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 transition flex items-center gap-2 text-sm"
                  >
                    <Trash2 className="w-4 h-4" /> Effacer tout
                  </button>
                  <button
                    onClick={() => router.push("/abonnement")}
                    className="px-4 py-2 bg-violet-600 text-white rounded-lg hover:bg-violet-700 transition flex items-center gap-2 text-sm"
                  >
                    <Plus className="w-4 h-4" /> Souscrire un agent
                  </button>
                </div>
              </div>

              {filteredProducts.length === 0 ? (
                <div className="text-center py-12 text-gray-500">
                  <Package className="w-12 h-12 mx-auto text-gray-300 mb-3" />
                  <p>Aucun produit dans ce catalogue.</p>
                  <p className="text-sm">Ajoutez votre premier produit ou importez un fichier CSV.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {filteredProducts.map((p) => (
                    <div key={p.id} className="bg-white rounded-lg border border-gray-200 p-4 hover:shadow-md transition">
                      <div className="flex justify-between items-start">
                        <h3 className="font-medium text-gray-800 truncate">{p.name}</h3>
                        <span className="text-xs px-2 py-1 rounded-full bg-gray-100 text-gray-600">{p.category}</span>
                      </div>
                      {p.brand && (
                        <div className="text-xs text-gray-400 mt-0.5">Marque: {p.brand}</div>
                      )}
                      {p.imageUrl && (
                        <img src={p.imageUrl} alt={p.name} className="w-full h-24 object-cover rounded-md my-2" />
                      )}
                      <p className="text-sm text-gray-500 line-clamp-2">{p.description || "Aucune description"}</p>
                      <div className="mt-2 flex justify-between text-sm">
                        <span className="font-bold text-blue-600">{p.salePrice} €</span>
                        <span className={`${p.stock < 5 ? 'text-red-500' : 'text-gray-600'}`}>
                          Stock: {p.stock}
                        </span>
                      </div>
                      <div className="mt-3 flex gap-2">
                        <button
                          onClick={() => openEditModal(p)}
                          className="flex-1 px-3 py-1.5 bg-blue-50 text-blue-600 rounded hover:bg-blue-100 flex items-center justify-center gap-1 text-xs"
                        >
                          <Edit className="w-3 h-3" /> Modifier
                        </button>
                        <button
                          onClick={() => deleteProduct(p.id)}
                          className="flex-1 px-3 py-1.5 bg-red-50 text-red-600 rounded hover:bg-red-100 flex items-center justify-center gap-1 text-xs"
                        >
                          <Trash2 className="w-3 h-3" /> Supprimer
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        }

        if (catalogGroups.length === 0) {
          return (
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-10 text-center text-gray-500">
              <Package className="w-12 h-12 mx-auto text-gray-300 mb-3" />
              <p>Aucun catalogue disponible.</p>
              <p className="text-sm mt-1">Créez votre premier catalogue pour commencer.</p>
            </div>
          );
        }

        return (
          <div className="space-y-5">
            {catalogGroups.map((group) => {
              const previewProducts = [...group.products]
                .sort(() => Math.random() - 0.5)
                .slice(0, catalogGroups.length === 1 ? 8 : 4);

              return (
                <div key={group.catalog.id} className="bg-white rounded-xl border border-gray-200 shadow-sm p-5">
                  <div className="flex justify-between items-center mb-4 flex-wrap gap-3">
                    <div>
                      <h3 className="text-lg font-semibold text-gray-800">{group.catalog.name}</h3>
                      <p className="text-xs text-gray-500">{group.products.length} produit{group.products.length > 1 ? 's' : ''}</p>
                    </div>
                    <button
                      onClick={() => {
                        setSelectedCatalogId(group.catalog.id);
                        const params = new URLSearchParams(window.location.search);
                        params.set("section", "catalogue");
                        params.set("catalog", group.catalog.id);
                        window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
                      }}
                      className="px-3 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition text-sm"
                    >
                      Voir le catalogue
                    </button>
                  </div>

                  {previewProducts.length === 0 ? (
                    <div className="text-sm text-gray-500">Aucun produit dans ce catalogue.</div>
                  ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                      {previewProducts.map((p) => (
                        <div key={p.id} className="bg-gray-50 rounded-lg border border-gray-200 p-3">
                          {p.imageUrl && (
                            <img src={p.imageUrl} alt={p.name} className="w-full h-20 object-cover rounded-md mb-2" />
                          )}
                          <div className="flex justify-between items-start gap-2">
                            <h4 className="font-medium text-gray-800 text-sm truncate">{p.name}</h4>
                            <span className="text-[10px] px-2 py-1 rounded-full bg-gray-100 text-gray-600">{p.category}</span>
                          </div>
                          {p.brand && <div className="text-xs text-gray-400 mt-0.5">Marque: {p.brand}</div>}
                          <div className="mt-2 flex justify-between text-sm">
                            <span className="font-bold text-blue-600">{p.salePrice} €</span>
                            <span className={`${p.stock < 5 ? 'text-red-500' : 'text-gray-600'}`}>
                              Stock: {p.stock}
                            </span>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        );

      case "projets":
        return (
          <div>
            <h2 className="text-lg font-semibold text-gray-800 mb-4">📋 Projets disponibles</h2>
            {availableProjects.length === 0 ? (
              <p className="text-gray-500">Aucun projet disponible pour le moment.</p>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {availableProjects.map(proj => (
                  <div key={proj.id} className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm">
                    <div className="flex justify-between">
                      <h3 className="font-medium">{proj.name}</h3>
                      <span className={`text-xs px-2 py-1 rounded-full ${
                        proj.color === "green" ? "bg-green-100 text-green-700" :
                        proj.color === "orange" ? "bg-orange-100 text-orange-700" :
                        "bg-red-100 text-red-700"
                      }`}>
                        {proj.color === "green" ? "Disponible" :
                         proj.color === "orange" ? "Stock partiel" : "Rupture"}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600">Client: {proj.clientName}</p>
                    <p className="text-sm text-gray-500">Surface: {proj.surface ?? "N/A"} m²</p>
                    <p className="text-xs text-gray-400 mt-1">
                      {new Date(proj.createdAt).toLocaleDateString()}
                    </p>
                    <button
                      onClick={() => {
                        setOfferProjectId(proj.id);
                        document.getElementById("offer-section")?.scrollIntoView({ behavior: "smooth" });
                      }}
                      className="mt-2 text-xs bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700"
                    >
                      Faire une offre
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        );

      case "offres":
        return (
          <div>
            <h2 className="text-lg font-semibold text-gray-800 mb-4">📨 Offres envoyées</h2>
            {proposals.length === 0 ? (
              <p className="text-gray-500">Aucune offre envoyée.</p>
            ) : (
              <div className="space-y-3">
                {proposals.map(offre => (
                  <div key={offre.id} className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm flex flex-wrap justify-between items-center">
                    <div>
                      <p className="font-medium">
                        {offre.product.name}
                        {offre.product.brand && <span className="text-sm text-gray-400 ml-1">({offre.product.brand})</span>}
                      </p>
                      <p className="text-sm text-gray-600">Projet: {offre.project?.name || "N/A"}</p>
                      <p className="text-sm">Quantité: {offre.quantity} | Prix unitaire: {offre.unitPrice} €</p>
                      <p className="text-xs text-gray-400">Statut: {offre.status}</p>
                      {offre.marketingMessage && (
                        <p className="text-xs text-gray-500 italic">“{offre.marketingMessage}”</p>
                      )}
                    </div>
                    <div className="flex gap-2">
                      {offre.status === "EN_ATTENTE" && (
                        <button
                          onClick={() => cancelProposal(offre.id)}
                          className="text-xs bg-red-100 text-red-700 px-3 py-1 rounded hover:bg-red-200"
                        >
                          Annuler
                        </button>
                      )}
                      {offre.status === "EXPIREE" && (
                        <button
                          onClick={() => openRelaunchModal(offre)}
                          className="text-xs bg-yellow-100 text-yellow-700 px-3 py-1 rounded hover:bg-yellow-200"
                        >
                          Relancer
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        );

      case "annonces":
        return (
          <div>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-lg font-semibold text-gray-800">📢 Mes annonces</h2>
              <button
                onClick={() => setShowListingModal(true)}
                className="px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 transition text-sm"
              >
                <Plus className="w-4 h-4 inline mr-1" /> Nouvelle annonce
              </button>
            </div>
            {listings.length === 0 ? (
              <p className="text-gray-500">Aucune annonce publiée.</p>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {listings.map(ann => (
                  <div key={ann.id} className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm">
                    <div className="flex justify-between items-start gap-3">
                      <h3 className="font-medium">
                        {ann.product.name}
                        {ann.product.brand && <span className="text-sm text-gray-400 ml-1">({ann.product.brand})</span>}
                      </h3>
                      <span className={`text-xs px-2 py-1 rounded-full ${ann.isActive ? "bg-green-100 text-green-700" : "bg-gray-100 text-gray-600"}`}>
                        {ann.isActive ? "Active" : "Inactive"}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600">
                      Quantité: {ann.quantity} | Prix unitaire: {ann.unitPrice} € | Prix total: {(ann.quantity * ann.unitPrice).toFixed(2)} €
                    </p>
                    {ann.endDate && <p className="text-sm text-gray-600">Fin de l’offre: {new Date(ann.endDate).toLocaleDateString()}</p>}
                    {ann.description && <p className="text-sm text-gray-500 mt-1">{ann.description}</p>}
                    <p className="text-xs text-gray-400 mt-1">Créée le {new Date(ann.createdAt).toLocaleDateString()}</p>

                    <div className="flex gap-2 mt-3">
                      {ann.isActive && (
                        <button
                          type="button"
                          onClick={() => cancelListing(ann.id)}
                          className="flex-1 text-xs bg-red-100 text-red-700 px-3 py-2 rounded hover:bg-red-200"
                        >
                          Annuler
                        </button>
                      )}
                      <button
                        type="button"
                        onClick={() => deleteListing(ann.id)}
                        className="flex-1 text-xs bg-gray-100 text-gray-700 px-3 py-2 rounded hover:bg-gray-200"
                      >
                        Supprimer
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        );

      case "ia":
        return (
          <div>
            <div className="flex items-center justify-between gap-3 mb-4">
              <h2 className="text-lg font-semibold text-gray-800">🤖 Assistant IA Vendeur</h2>
              <button
                onClick={fetchAISuggestions}
                disabled={aiLoading}
                className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 disabled:opacity-50 flex items-center gap-2"
              >
                {aiLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                {aiLoading ? "Analyse en cours..." : "Analyser les projets"}
              </button>
            </div>

            {aiSuggestions.length === 0 && !aiLoading && (
              <div className="bg-white border border-purple-200 rounded-lg p-5 text-gray-600">
                Cliquez sur le bouton pour analyser les projets disponibles et obtenir des recommandations IA à partir du catalogue du vendeur.
              </div>
            )}

            {aiLoading && <p className="text-gray-500">Chargement des recommandations IA...</p>}

            {!aiLoading && aiSuggestions.length > 0 && (
              <div className="space-y-4">
                {aiSuggestions.map((suggestion) => (
                  <div key={suggestion.projectId} className="bg-white border border-purple-200 rounded-lg p-4 shadow-sm">
                    <div className="flex items-center justify-between gap-3 mb-2">
                      <h4 className="font-semibold text-purple-800">{suggestion.projectName}</h4>
                      <span className="text-[10px] uppercase tracking-wide bg-purple-100 text-purple-700 px-2 py-1 rounded-full">IA</span>
                    </div>

                    <p className="text-sm text-gray-700 mb-3">{suggestion.summary}</p>

                    {suggestion.recommendedProducts.length > 0 && (
                      <div className="mb-3">
                        <p className="text-xs font-semibold uppercase text-gray-500 mb-2">Produits recommandés</p>
                        <div className="space-y-2">
                          {suggestion.recommendedProducts.map((product, index) => (
                            <div key={`${suggestion.projectId}-${index}`} className="rounded-md border border-gray-200 bg-gray-50 p-2">
                              <div className="flex items-center justify-between gap-3">
                                <span className="text-sm font-medium text-gray-800">{String(product.name || 'Produit')}</span>
                                <span className="text-xs text-blue-700 font-medium">{Number(product.price || 0).toFixed(2)} €</span>
                              </div>
                              <p className="text-xs text-gray-500 mt-1">{String(product.justification || '')}</p>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {suggestion.recommendedTutorials.length > 0 && (
                      <div className="mb-3">
                        <p className="text-xs font-semibold uppercase text-gray-500 mb-2">Tutoriels</p>
                        <div className="space-y-2">
                          {suggestion.recommendedTutorials.map((tutorial, index) => (
                            <div key={`${suggestion.projectId}-tutorial-${index}`} className="rounded-md border border-gray-200 bg-white p-2">
                              <p className="text-sm font-medium text-gray-800">{String(tutorial.title || 'Tutoriel')}</p>
                              <p className="text-xs text-gray-500">{String(tutorial.description || '')}</p>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {suggestion.questions.length > 0 && (
                      <div className="mb-3">
                        <p className="text-xs font-semibold uppercase text-gray-500 mb-2">Questions</p>
                        <ul className="list-disc pl-4 text-sm text-gray-700 space-y-1">
                          {suggestion.questions.map((question, index) => (
                            <li key={`${suggestion.projectId}-question-${index}`}>{question}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    <div className="rounded-md bg-purple-50 border border-purple-200 p-2">
                      <p className="text-xs font-semibold uppercase text-purple-700 mb-1">Action suivante</p>
                      <p className="text-sm text-purple-800">{suggestion.nextAction}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        );

      default:
        return null;
    }
  };

  if (checkingAgent) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  if (hasActiveAgent === false) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 px-4">
        <div className="bg-white rounded-xl shadow-lg p-8 max-w-md w-full text-center">
          <Sparkles className="w-16 h-16 text-blue-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-gray-800 mb-2">🚀 Activez votre agent</h2>
          <p className="text-gray-600 mb-6">
            Pour accéder à votre espace vendeur et gérer vos produits, vous devez choisir un abonnement.
          </p>
          <Link
            href="/abonnement"
            className="inline-block bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition font-semibold"
          >
            Voir les offres
          </Link>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar
        onSectionChange={(section: string) => setSection(section as SectionType)}
        activeSection={section}
        onCatalogSelect={handleCatalogSelect}
        selectedCatalogId={selectedCatalogId}
      />
      <div className="flex-1 ml-64 p-8">
        <header className="flex justify-between items-center mb-6">
          <div>
            <h1 className="text-2xl font-bold text-gray-800">
              📦 Agent Vendeur – {session?.user?.companyName || session?.user?.name || "Vendeur"}
            </h1>
            <p className="text-gray-500 text-sm">Gérez votre catalogue et vos offres</p>
          </div>
        </header>

        <div className="rounded-xl p-0 bg-transparent shadow-none border-0">
          {renderSection()}
        </div>

        <div id="offer-section" className="mt-6 bg-white rounded-xl shadow-sm border border-gray-100 p-6">
          <h2 className="text-lg font-semibold text-gray-800 mb-3">📩 Envoyer une offre</h2>
          <form onSubmit={handleSendOffer} className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">Projet</label>
              <select
                value={offerProjectId}
                onChange={(e) => setOfferProjectId(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm"
                required
              >
                <option value="">Sélectionner un projet</option>
                {availableProjects.map(p => (
                  <option key={p.id} value={p.id}>{p.name} ({p.clientName})</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Produit</label>
              <select
                value={offerProductId}
                onChange={(e) => setOfferProductId(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm"
                required
              >
                <option value="">Sélectionner un produit</option>
                {products.map(p => (
                  <option key={p.id} value={p.id}>{p.name} {p.brand ? `(${p.brand})` : ''} (stock: {p.stock})</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Quantité</label>
              <input
                type="number"
                value={offerQuantity}
                onChange={(e) => setOfferQuantity(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm"
                min="1"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Prix unitaire (€)</label>
              <input
                type="number"
                value={offerUnitPrice}
                onChange={(e) => setOfferUnitPrice(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm"
                step="0.01"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Message</label>
              <input
                type="text"
                value={offerMessage}
                onChange={(e) => setOfferMessage(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm"
                placeholder="Message privé"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Message marketing</label>
              <input
                type="text"
                value={offerMarketingMessage}
                onChange={(e) => setOfferMarketingMessage(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm"
                placeholder="Visible par l'artisan"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700">Date de livraison</label>
              <input
                type="date"
                value={offerDeliveryDate}
                onChange={(e) => setOfferDeliveryDate(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm"
              />
            </div>
            <div className="flex items-end">
              <button
                type="submit"
                disabled={sendingOffer}
                className="w-full bg-blue-600 text-white rounded-lg px-4 py-2 hover:bg-blue-700 disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {sendingOffer ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                {sendingOffer ? "Envoi..." : "Envoyer l'offre"}
              </button>
            </div>
          </form>
        </div>
      </div>

      {/* MODALES */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-4">{editingProduct ? "Modifier" : "Ajouter"} un produit</h2>
            <form onSubmit={handleSubmit} className="space-y-3">
              <input
                type="text"
                placeholder="Nom"
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                required
              />
              <input
                type="text"
                placeholder="Marque (optionnel)"
                value={formData.brand}
                onChange={(e) => setFormData({...formData, brand: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
              />
              <textarea
                placeholder="Description"
                value={formData.description}
                onChange={(e) => setFormData({...formData, description: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                rows={2}
              />
              <input
                type="text"
                placeholder="Catégorie"
                value={formData.category}
                onChange={(e) => setFormData({...formData, category: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                required
              />
              <select
                value={formData.catalogId}
                onChange={(e) => setFormData({...formData, catalogId: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                required
              >
                <option value="">Sélectionner un catalogue</option>
                {catalogs.map(cat => (
                  <option key={cat.id} value={cat.id}>{cat.name}</option>
                ))}
              </select>
              <div className="grid grid-cols-2 gap-3">
                <input
                  type="number"
                  placeholder="Prix d'achat"
                  value={formData.purchasePrice}
                  onChange={(e) => setFormData({...formData, purchasePrice: e.target.value})}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  required
                />
                <input
                  type="number"
                  placeholder="Prix de vente"
                  value={formData.salePrice}
                  onChange={(e) => setFormData({...formData, salePrice: e.target.value})}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  required
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <input
                  type="number"
                  placeholder="Stock"
                  value={formData.stock}
                  onChange={(e) => setFormData({...formData, stock: e.target.value})}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  required
                />
                <input
                  type="number"
                  placeholder="TVA (%)"
                  value={formData.tvaRate}
                  onChange={(e) => setFormData({...formData, tvaRate: e.target.value})}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">URL de l&apos;image</label>
                <input
                  type="text"
                  placeholder="https://... ou /uploads/..."
                  value={formData.imageUrl}
                  onChange={(e) => setFormData({...formData, imageUrl: e.target.value})}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Ou importer une image</label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleImageUpload}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2 file:mr-3 file:rounded file:border-0 file:bg-blue-50 file:px-3 file:py-1.5 file:text-blue-700"
                />
                {uploadingImage && (
                  <p className="text-xs text-blue-600 mt-1">Téléchargement de l'image en cours...</p>
                )}
                {(uploadedImageUrl || formData.imageUrl) && (
                  <div className="mt-2 overflow-hidden rounded-lg border border-gray-200 bg-gray-50 p-2">
                    <img
                      src={uploadedImageUrl || formData.imageUrl}
                      alt="Aperçu produit"
                      className="h-20 w-full object-cover rounded-md"
                    />
                    <p className="text-[10px] text-gray-500 mt-1">
                      {uploadedImageUrl ? "Image importée (prioritaire)" : "Image URL utilisée"}
                    </p>
                  </div>
                )}
              </div>

              <div className="flex gap-2 pt-2">
                <button type="submit" className="flex-1 bg-blue-600 text-white rounded-lg px-4 py-2 hover:bg-blue-700">
                  {editingProduct ? "Modifier" : "Ajouter"}
                </button>
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 bg-gray-200 text-gray-700 rounded-lg px-4 py-2 hover:bg-gray-300"
                >
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showClearCatalogModal && selectedCatalogId && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md">
            <div className="flex items-start gap-3 mb-4">
              <div className="p-2 bg-red-100 rounded-full">
                <AlertCircle className="w-5 h-5 text-red-600" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-gray-900">Effacer tous les produits</h2>
                <p className="text-sm text-gray-600 mt-1">
                  Cette action supprimera tous les produits du catalogue <strong>{catalogs.find(c => c.id === selectedCatalogId)?.name || "sélectionné"}</strong>.
                </p>
              </div>
            </div>

            <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-700 mb-4">
              Cette action est irréversible. Les produits supprimés ne seront plus accessibles dans ce catalogue.
            </div>

            <div className="flex gap-2">
              <button
                type="button"
                onClick={clearCatalogProducts}
                className="flex-1 bg-red-600 text-white rounded-lg px-4 py-2 hover:bg-red-700 transition"
              >
                Confirmer
              </button>
              <button
                type="button"
                onClick={() => setShowClearCatalogModal(false)}
                className="flex-1 bg-gray-200 text-gray-700 rounded-lg px-4 py-2 hover:bg-gray-300 transition"
              >
                Annuler
              </button>
            </div>
          </div>
        </div>
      )}

      {showImportModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">Importer des produits</h2>

            {/* Templates téléchargeables */}
            <div className="mb-4 flex flex-wrap gap-2">
              <a
                href="/api/templates/produits.csv"
                download="template_produits.csv"
                className="text-sm bg-blue-50 text-blue-600 px-3 py-1.5 rounded-lg hover:bg-blue-100 transition flex items-center gap-1"
              >
                <Download className="w-4 h-4" /> Template CSV
              </a>
              <a
                href="/api/templates/produits.xlsx"
                download="template_produits.xlsx"
                className="text-sm bg-green-50 text-green-600 px-3 py-1.5 rounded-lg hover:bg-green-100 transition flex items-center gap-1"
              >
                <Download className="w-4 h-4" /> Template XLSX
              </a>
            </div>

            <form onSubmit={handleImport}>
              <div className="mb-3">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Fichier CSV ou XLSX <span className="text-xs text-gray-400">(utilisez les templates ci-dessus)</span>
                </label>
                <input
                  type="file"
                  accept=".csv,.xlsx"
                  onChange={(e) => setImportFile(e.target.files?.[0] || null)}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  required
                />
              </div>

              <div className="mb-3">
                <label className="block text-sm font-medium text-gray-700 mb-1">Catalogue</label>
                <select
                  value={importCatalogId}
                  onChange={(e) => {
                    setImportCatalogId(e.target.value);
                    if (e.target.value !== "new") setImportNewCatalogName("");
                  }}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                >
                  <option value="">Sélectionner un catalogue</option>
                  {catalogs.map(cat => (
                    <option key={cat.id} value={cat.id}>{cat.name}</option>
                  ))}
                  <option value="new">+ Créer un nouveau catalogue</option>
                </select>
              </div>

              {importCatalogId === "new" && (
                <div className="mb-3">
                  <label className="block text-sm font-medium text-gray-700 mb-1">Nom du nouveau catalogue</label>
                  <input
                    type="text"
                    placeholder="Ex: Peinture, Électricité..."
                    value={importNewCatalogName}
                    onChange={(e) => setImportNewCatalogName(e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2"
                    required
                  />
                </div>
              )}

              <div className="flex gap-2 mt-4">
                <button
                  type="submit"
                  disabled={importLoading}
                  className="flex-1 bg-green-600 text-white rounded-lg px-4 py-2 hover:bg-green-700 disabled:opacity-50"
                >
                  {importLoading ? "Import..." : "Importer"}
                </button>
                <button
                  type="button"
                  onClick={() => setShowImportModal(false)}
                  className="flex-1 bg-gray-200 text-gray-700 rounded-lg px-4 py-2 hover:bg-gray-300"
                >
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showRelaunchModal && relaunchData && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">Relancer l’offre</h2>
            <form onSubmit={handleRelaunch} className="space-y-3">
              <input
                type="number"
                placeholder="Quantité"
                value={relaunchData.quantity}
                onChange={(e) => setRelaunchData({...relaunchData, quantity: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                required
              />
              <input
                type="number"
                placeholder="Prix unitaire"
                value={relaunchData.unitPrice}
                onChange={(e) => setRelaunchData({...relaunchData, unitPrice: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                step="0.01"
                required
              />
              <input
                type="text"
                placeholder="Message"
                value={relaunchData.message}
                onChange={(e) => setRelaunchData({...relaunchData, message: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
              />
              <input
                type="text"
                placeholder="Message marketing"
                value={relaunchData.marketingMessage}
                onChange={(e) => setRelaunchData({...relaunchData, marketingMessage: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
              />
              <input
                type="date"
                value={relaunchData.deliveryDate}
                onChange={(e) => setRelaunchData({...relaunchData, deliveryDate: e.target.value})}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
              />
              <div className="flex gap-2 pt-2">
                <button type="submit" className="flex-1 bg-yellow-600 text-white rounded-lg px-4 py-2 hover:bg-yellow-700">
                  Relancer
                </button>
                <button type="button" onClick={() => setShowRelaunchModal(false)} className="flex-1 bg-gray-200 text-gray-700 rounded-lg px-4 py-2 hover:bg-gray-300">
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showListingModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">Créer une annonce</h2>
            <form onSubmit={handleCreateListing} className="space-y-3">
              <select
                value={listingProductId}
                onChange={(e) => {
                  const selectedProduct = products.find((p) => p.id === e.target.value);
                  setListingProductId(e.target.value);
                  if (selectedProduct) {
                    setListingUnitPrice(String(selectedProduct.salePrice));
                  }
                }}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                required
              >
                <option value="">Choisir un produit</option>
                {products.map(p => (
                  <option key={p.id} value={p.id}>{p.name} {p.brand ? `(${p.brand})` : ''} (stock: {p.stock})</option>
                ))}
              </select>
              <input
                type="number"
                placeholder="Quantité"
                value={listingQuantity}
                onChange={(e) => setListingQuantity(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                required
              />
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Prix unitaire</label>
                <input
                  type="number"
                  placeholder="Prix unitaire"
                  value={listingUnitPrice}
                  onChange={(e) => setListingUnitPrice(e.target.value)}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  step="0.01"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Prix total</label>
                <div className="w-full border border-gray-300 bg-gray-50 rounded-lg px-3 py-2 text-gray-800 font-semibold">
                  {listingTotalPrice.toFixed(2)} €
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date de fin</label>
                <input
                  type="date"
                  value={listingEndDate}
                  onChange={(e) => setListingEndDate(e.target.value)}
                  className="w-full border border-gray-300 rounded-lg px-3 py-2"
                  required
                />
              </div>
              <textarea
                placeholder="Description (optionnelle)"
                value={listingDescription}
                onChange={(e) => setListingDescription(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2"
                rows={2}
              />
              <div className="flex gap-2 pt-2">
                <button type="submit" disabled={sendingListing} className="flex-1 bg-orange-600 text-white rounded-lg px-4 py-2 hover:bg-orange-700 disabled:opacity-50">
                  {sendingListing ? "Création..." : "Créer l'annonce"}
                </button>
                <button type="button" onClick={() => setShowListingModal(false)} className="flex-1 bg-gray-200 text-gray-700 rounded-lg px-4 py-2 hover:bg-gray-300">
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Send, Eye, Package } from "lucide-react";
import { useRouter } from "next/navigation";
import Sidebar from "@/components/Sidebar";

type Product = {
  id: string;
  name: string;
  salePrice: number;
};

type AvailableProject = {
  id: string;
  name: string;
  type: string | null;
  surface: number | null;
  budgetEstimate: number | null;
  clientName: string;
  items: { name: string; quantity: number }[];
  createdAt: string;
};

export default function VendeurProjetsPage() {
  const router = useRouter();
  const [availableProjects, setAvailableProjects] = useState<AvailableProject[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  // États pour le formulaire d'offre
  const [offerProjectId, setOfferProjectId] = useState("");
  const [offerProductId, setOfferProductId] = useState("");
  const [offerQuantity, setOfferQuantity] = useState("1");
  const [offerUnitPrice, setOfferUnitPrice] = useState("");
  const [offerMessage, setOfferMessage] = useState("");
  const [sendingOffer, setSendingOffer] = useState(false);

  const fetchAvailableProjects = async () => {
    try {
      const res = await fetch('/api/vendor/projects', { credentials: 'include' });
      if (res.ok) {
        const data = await res.json();
        setAvailableProjects(data);
      }
    } catch (error) {
      console.error("Erreur chargement projets :", error);
    }
  };

  const fetchProducts = async () => {
    try {
      const res = await fetch('/api/seller/products', { credentials: 'include' });
      if (res.ok) {
        const data = await res.json();
        setProducts(data);
      }
    } catch (error) {
      console.error("Erreur chargement produits :", error);
    }
  };

  useEffect(() => {
    const load = async () => {
      await fetchAvailableProjects();
      await fetchProducts();
      setLoading(false);
    };
    load();
  }, []);

  const handleSendOffer = async (e: React.FormEvent) => {
    e.preventDefault();

    const quantityNum = parseFloat(offerQuantity);
    const unitPriceNum = parseFloat(offerUnitPrice);

    if (!offerProjectId || !offerProductId) {
      alert("Veuillez sélectionner un projet et un produit.");
      return;
    }

    if (isNaN(quantityNum) || quantityNum <= 0) {
      alert("Veuillez entrer une quantité valide (nombre > 0).");
      return;
    }

    if (isNaN(unitPriceNum) || unitPriceNum < 0) {
      alert("Veuillez entrer un prix unitaire valide.");
      return;
    }

    setSendingOffer(true);
    try {
      const res = await fetch('/api/seller/proposals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          projectId: offerProjectId,
          productId: offerProductId,
          quantity: quantityNum,
          unitPrice: unitPriceNum,
          message: offerMessage || null,
        }),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || 'Erreur');
      }
      const data = await res.json();
      alert(`✅ Offre envoyée avec succès ! (ID: ${data.id})`);
      setOfferProjectId("");
      setOfferProductId("");
      setOfferQuantity("1");
      setOfferUnitPrice("");
      setOfferMessage("");
      await fetchAvailableProjects();
    } catch (error) {
      console.error("Erreur envoi offre :", error);
      alert("Erreur : " + (error as Error).message);
    } finally {
      setSendingOffer(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar />

      <main className="flex-1 pl-64">
        <div className="max-w-7xl mx-auto p-8">
          <h1 className="text-2xl font-bold text-gray-800 mb-6">🛒 Marché des projets</h1>

          {loading ? (
            <p className="text-gray-500">Chargement...</p>
          ) : availableProjects.length === 0 ? (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 text-center text-gray-500">
              <p>Aucun projet disponible pour le moment.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {availableProjects.map((project) => (
                <div key={project.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 hover:shadow-md transition">
                  <h3 className="text-lg font-semibold text-gray-800">{project.name}</h3>
                  <p className="text-sm text-gray-600">Client : {project.clientName}</p>
                  <p className="text-sm text-gray-600">Type : {project.type || 'Non spécifié'} {project.surface ? `- ${project.surface} m²` : ''}</p>
                  <p className="text-sm text-gray-600">Budget : {project.budgetEstimate ? `${project.budgetEstimate} €` : 'Non défini'}</p>
                  <div className="mt-2">
                    <p className="text-xs font-semibold text-gray-500">Produits demandés :</p>
                    <ul className="text-xs text-gray-600 list-disc list-inside">
                      {project.items.length > 0 ? project.items.map((item, idx) => (
                        <li key={idx}>{item.name} (x{item.quantity})</li>
                      )) : <li>Aucun produit spécifié</li>}
                    </ul>
                  </div>
                  <button
                    onClick={() => {
                      setOfferProjectId(project.id);
                      document.getElementById('offer-form')?.scrollIntoView({ behavior: 'smooth' });
                    }}
                    className="mt-4 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition flex items-center gap-2"
                  >
                    <Send className="w-4 h-4" /> Faire une offre
                  </button>
                </div>
              ))}
            </div>
          )}

          <div id="offer-form" className="mt-8 bg-white rounded-xl shadow-sm border border-gray-100 p-6">
            <h2 className="text-lg font-semibold text-gray-800 mb-4 flex items-center gap-2">
              <Send className="w-5 h-5" /> Faire une offre sur un projet
            </h2>
            <form onSubmit={handleSendOffer} className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">ID du projet *</label>
                <input
                  type="text"
                  placeholder="ex: cmsp0t1rp000elmiggnhdlyz9"
                  value={offerProjectId}
                  onChange={(e) => setOfferProjectId(e.target.value)}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                  required
                />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Produit *</label>
            <select
              value={offerProductId}
              onChange={(e) => setOfferProductId(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
              required
            >
              <option value="">Sélectionner un produit...</option>
              {products.map((p) => (
                <option key={p.id} value={p.id}>{p.name} - {p.salePrice} €</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Quantité *</label>
            <input
              type="number"
              step="0.01"
              min="1"
              value={offerQuantity}
              onChange={(e) => setOfferQuantity(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Prix unitaire (€) *</label>
            <input
              type="number"
              step="0.01"
              placeholder="ex: 42.50"
              value={offerUnitPrice}
              onChange={(e) => setOfferUnitPrice(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
              required
            />
          </div>
          <div className="md:col-span-2">
            <label className="block text-sm font-medium text-gray-700 mb-1">Message (optionnel)</label>
            <input
              type="text"
              placeholder="Message pour l'artisan"
              value={offerMessage}
              onChange={(e) => setOfferMessage(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div className="md:col-span-2">
            <button
              type="submit"
              disabled={sendingOffer}
              className="w-full bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition disabled:opacity-50 flex items-center justify-center gap-2"
            >
              <Send className="w-4 h-4" />
              {sendingOffer ? 'Envoi en cours...' : 'Envoyer l\'offre'}
            </button>
          </div>
            </form>
          </div>
        </div>
      </main>
    </div>
  );
}

export default {
  nav: {
    home: 'Accueil',
    ia: 'IA',
    casUsage: 'Cas d\'usage',
    tarifs: 'Tarifs',
    appareils: 'Appareils',
    aide: 'Aide',
    contact: 'Contact',
    login: 'Connexion',
    trial: 'Essai gratuit',
    logout: 'Déconnexion',
  },
  home: {
    badge: 'IA pour le BTP, au service des talents terrain',
    cta: 'Trouver un artisan',
    secondary: 'Rechercher',
    headline: "L'IA qui booste les talents du BTP, pas qui les remplace.",
    subheadline: "Aqil Bina s'adapte à votre métier, pas l'inverse.",
  },
  profile: {
    findArtisan: 'Trouver un artisan',
    findVendor: 'Trouver un vendeur',
  },
};
